INSERT INTO public.movimiento VALUES ('MV00027', 'Arm Thrust', 'Empujón', 'Hits 2-5 times in one turn.', 'Golpea de 2 a 5 veces en un turno.', '
INSERT INTO public.movimiento VALUES ('MV00028', 'Armor Cannon', NULL, 'Lowers user''s Defense and Special Defense.', 'Reduce la Defensa y la Defensa Especial del usuario.', '
INSERT INTO public.movimiento VALUES ('MV00029', 'Aromatherapy', 'Aromaterapia', 'Cures all status problems in your party.', 'Cura todos los problemas de estado en tu grupo.', '
INSERT INTO public.movimiento VALUES ('MV00030', 'Aromatic Mist', 'Niebla Aromática', 'Raises Special Defense of an ally.', 'Aumenta la defensa especial de un aliado.', '
INSERT INTO public.movimiento VALUES ('MV00031', 'Assist', 'Ayuda', 'User performs a move known by its allies at random.', 'El usuario realiza un movimiento conocido por sus aliados al azar.', '
INSERT INTO public.movimiento VALUES ('MV00032', 'Assurance', 'Buena Baza', 'Power doubles if opponent already took damage in the same turn.', 'El poder se duplica si el oponente ya recibió daño en el mismo turno.', '
INSERT INTO public.movimiento VALUES ('MV00033', 'Astonish', 'Impresionar', 'May cause flinching.', 'Puede causar estremecimiento.', '
INSERT INTO public.movimiento VALUES ('MV00034', 'Astral Barrage', 'Orbes Espectro', 'The user attacks by sending a frightful amount of small ghosts at opposing Pokémon.', 'El usuario ataca enviando una gran cantidad de pequeños fantasmas a los Pokémon rivales.', '
INSERT INTO public.movimiento VALUES ('MV00035', 'Attack Order', 'Al Ataque', 'High critical hit ratio.', 'Alto porcentaje de golpes críticos.', '
INSERT INTO public.movimiento VALUES ('MV00036', 'Attract', 'Atracción', 'If opponent is the opposite gender, it''s less likely to attack.', 'Si el oponente es del sexo opuesto, es menos probable que ataque.', '
INSERT INTO public.movimiento VALUES ('MV00037', 'Aura Sphere', 'Esfera Aural', 'Ignores Accuracy and Evasiveness.', 'Ignora la precisión y la evasividad.', '
INSERT INTO public.movimiento VALUES ('MV00038', 'Aura Wheel', 'Rueda Aural', 'Changes type based on Morpeko''s Mode.', 'Cambia el tipo según el modo de Morpeko.', '
INSERT INTO public.movimiento VALUES ('MV00039', 'Aurora Beam', 'Rayo Aurora', 'May lower opponent''s Attack.', 'Puede reducir el Ataque del oponente.', '
INSERT INTO public.movimiento VALUES ('MV00040', 'Aurora Veil', 'Velo Aurora', 'Halves damage from Physical and Special attacks for five turns.', 'Reduce a la mitad el daño de los ataques físicos y especiales durante cinco turnos.', '
INSERT INTO public.movimiento VALUES ('MV00041', 'Autotomize', 'Aligerar', 'Reduces weight and sharply raises Speed.', 'Reduce el peso y aumenta bruscamente la velocidad.', '
INSERT INTO public.movimiento VALUES ('MV00042', 'Avalanche', 'Alud', 'Power doubles if user took damage first.', 'El poder se duplica si el usuario recibió daño primero.', '
INSERT INTO public.movimiento VALUES ('MV00043', 'Axe Kick', NULL, 'May confuse opponent. If it misses, the user loses HP.', 'Puede confundir al oponente. Si falla, el usuario pierde HP.', '
INSERT INTO public.movimiento VALUES ('MV00044', 'Baby-Doll Eyes', 'Ojitos Tiernos', 'Always goes first. Lowers the target''s attack.', 'Siempre va primero. Reduce el ataque del objetivo.', '
INSERT INTO public.movimiento VALUES ('MV00045', 'Baddy Bad', 'Umbreozona', 'Reduces damage from Physical attacks.', 'Reduce el daño de los ataques físicos.', '
INSERT INTO public.movimiento VALUES ('MV00046', 'Baneful Bunker', 'Búnker', 'Protects the user and poisons opponent on contact.', 'Protege al usuario y envenena al oponente al contacto.', '
INSERT INTO public.movimiento VALUES ('MV00047', 'Barb Barrage', NULL, 'Inflicts double damage if the target has a status condition.', 'Inflige el doble de daño si el objetivo tiene una condición de estado.', '
INSERT INTO public.movimiento VALUES ('MV00048', 'Barrage', 'Presa', 'Hits 2-5 times in one turn.', 'Golpea de 2 a 5 veces en un turno.', '
INSERT INTO public.movimiento VALUES ('MV00049', 'Barrier', 'Barrera', 'Sharply raises user''s Defense.', 'Aumenta bruscamente la defensa del usuario.', '
INSERT INTO public.movimiento VALUES ('MV00050', 'Baton Pass', 'Relevo', 'User switches out and gives stat changes to the incoming Pokémon.', 'El usuario cambia y da cambios de estadísticas al Pokémon entrante.', '
INSERT INTO public.movimiento VALUES ('MV00051', 'Beak Blast', 'Pico Cañón', 'The user first heats up its beak, and then it attacks the target. Making direct contact with the Pokémon while it''s heating up its beak results in a burn.', 'El usuario primero calienta su pico y luego ataca al objetivo. Hacer contacto directo con el Pokémon mientras está calentando su pico resulta en una quemadura.', '
INSERT INTO public.movimiento VALUES ('MV00052', 'Beat Up', 'Paliza', 'Each Pokémon in user''s party attacks.', 'Cada Pokémon en el grupo del usuario ataca.', '
INSERT INTO public.movimiento VALUES ('MV00053', 'Behemoth Bash', 'Embate Supremo', 'Damage doubles if target is Dynamaxed.', 'El daño se duplica si el objetivo es Dynamaxed.', '
INSERT INTO public.movimiento VALUES ('MV00054', 'Behemoth Blade', 'Tajo Supremo', 'Damage doubles if target is Dynamaxed.', 'El daño se duplica si el objetivo es Dynamaxed.', '
INSERT INTO public.movimiento VALUES ('MV00055', 'Belch', 'Eructo', 'User must have consumed a Berry.', 'El usuario debe haber consumido una baya.', '
INSERT INTO public.movimiento VALUES ('MV00056', 'Belly Drum', 'Tambor', 'User loses 50% of its max HP, but Attack raises to maximum.', 'El usuario pierde el 50 % de su HP máximo, pero el ataque aumenta al máximo.', '
INSERT INTO public.movimiento VALUES ('MV00057', 'Bestow', 'Ofrenda', 'Gives the user''s held item to the target.', 'Da el elemento retenido del usuario al objetivo.', '
INSERT INTO public.movimiento VALUES ('MV00058', 'Bide', 'Venganza', 'User takes damage for two turns then strikes back double.', 'El usuario recibe daño durante dos turnos y luego devuelve el doble.', '
INSERT INTO public.movimiento VALUES ('MV00059', 'Bind', 'Atadura', 'Traps opponent, damaging them for 4-5 turns.', 'Atrapa al oponente, dañándolo durante 4-5 turnos.', '
INSERT INTO public.movimiento VALUES ('MV00060', 'Bite', 'Mordisco', 'May cause flinching.', 'Puede causar estremecimiento.', '
INSERT INTO public.movimiento VALUES ('MV00061', 'Bitter Blade', NULL, 'User recovers half the HP inflicted on opponent.', 'El usuario recupera la mitad del HP infligido al oponente.', '
INSERT INTO public.movimiento VALUES ('MV00062', 'Bitter Malice', NULL, 'Inflicts double damage if the target has a status condition.', 'Inflige el doble de daño si el objetivo tiene una condición de estado.', '
