INSERT INTO public.movimiento VALUES ('MV00810', 'Swords Dance', 'Danza Espada', 'Sharply raises user''s Attack.', 'Aumenta bruscamente el ataque del usuario.', '
INSERT INTO public.movimiento VALUES ('MV00811', 'Synchronoise', 'Sincrorruido', 'Hits any Pokémon that shares a type with the user.', 'Golpea a cualquier Pokémon que comparta un tipo con el usuario.', '
INSERT INTO public.movimiento VALUES ('MV00812', 'Synthesis', 'Síntesis', 'User recovers HP. Amount varies with the weather.', 'El usuario recupera HP. La cantidad varía con el clima.', '
