INSERT INTO public.movimiento VALUES ('MV00814', 'Tail Glow', 'Ráfaga', 'Drastically raises user''s Special Attack.', 'Aumenta drásticamente el ataque especial del usuario.', '
INSERT INTO public.movimiento VALUES ('MV00815', 'Tail Slap', 'Plumerazo', 'Hits 2-5 times in one turn.', 'Golpea de 2 a 5 veces en un turno.', '
INSERT INTO public.movimiento VALUES ('MV00816', 'Tail Whip', 'Látigo', 'Lowers opponent''s Defense.', 'Reduce la Defensa del oponente.', '
INSERT INTO public.movimiento VALUES ('MV00817', 'Tailwind', 'Viento Afín', 'Doubles Speed for 4 turns.', 'Duplica la velocidad durante 4 turnos.', '
INSERT INTO public.movimiento VALUES ('MV00818', 'Take Down', 'Derribo', 'User receives recoil damage.', 'El usuario recibe daños por retroceso.', '
INSERT INTO public.movimiento VALUES ('MV00819', 'Take Heart', NULL, 'Heals user''s status conditions and raises its stats.', 'Cura las condiciones de estado del usuario y aumenta sus estadísticas.', '
INSERT INTO public.movimiento VALUES ('MV00820', 'Tar Shot', 'Alquitranazo', 'Lowers the opponent''s Speed and makes them weaker to Fire-type moves.', 'Reduce la velocidad del oponente y lo hace más débil a los movimientos de tipo fuego.', '
INSERT INTO public.movimiento VALUES ('MV00821', 'Taunt', 'Mofa', 'Opponent can only use moves that attack.', 'El oponente solo puede usar movimientos que ataquen.', '
INSERT INTO public.movimiento VALUES ('MV00822', 'Tearful Look', 'Ojos Llorosos', 'The user gets teary eyed to make the target lose its combative spirit. This lowers the target''s Attack and Sp. Atk stats.', 'El usuario tiene los ojos llorosos para que el objetivo pierda su espíritu combativo. Esto reduce el Ataque y la Sp. del objetivo. Estadísticas de ataque.', '
INSERT INTO public.movimiento VALUES ('MV00823', 'Teatime', 'Hora del Té', 'Forces all Pokémon on the field to eat their berries.', 'Obliga a todos los Pokémon en el campo a comer sus bayas.', '
INSERT INTO public.movimiento VALUES ('MV00824', 'Techno Blast', 'Tecno Shock', 'Type depends on the Drive being held.', 'El tipo depende de la Unidad que se esté reteniendo.', '
INSERT INTO public.movimiento VALUES ('MV00825', 'Tectonic Rage', 'Barrena Telúrica', 'Ground type Z-Move.', 'Tipo de suelo Z-Move.', '
INSERT INTO public.movimiento VALUES ('MV00826', 'Teeter Dance', 'Danza Caos', 'Confuses all Pokémon.', 'Confunde a todos los Pokémon.', '
INSERT INTO public.movimiento VALUES ('MV00827', 'Telekinesis', 'Telequinesis', 'Ignores opponent''s Evasiveness for three turns, add Ground immunity.', 'Ignora la capacidad de evasión del oponente durante tres turnos, agrega inmunidad a tierra.', '
INSERT INTO public.movimiento VALUES ('MV00828', 'Teleport', 'Teletransporte', 'Allows user to flee wild battles; also warps player to last PokéCenter.', 'Permite al usuario huir de batallas salvajes; también transporta al jugador al último PokéCenter.', '
INSERT INTO public.movimiento VALUES ('MV00829', 'Tera Blast', NULL, 'Changes type when the user has Terastallized.', 'Cambia de tipo cuando el usuario se ha Terastallizado.', '
INSERT INTO public.movimiento VALUES ('MV00830', 'Terrain Pulse', 'Pulso de Campo', 'Type and power change depending on the Terrain in effect.', 'El tipo y el poder cambian dependiendo del Terreno en efecto.', '
INSERT INTO public.movimiento VALUES ('MV00831', 'Thief', 'Ladrón', 'Also steals opponent''s held item.', 'También roba el objeto retenido por el oponente.', '
INSERT INTO public.movimiento VALUES ('MV00832', 'Thousand Arrows', 'Mil Flechas', 'Makes Flying-type Pokémon vulnerable to Ground moves.', 'Hace que los Pokémon de tipo Volador sean vulnerables a los movimientos de tierra.', '
INSERT INTO public.movimiento VALUES ('MV00833', 'Thousand Waves', 'Mil Temblores', 'Opponent cannot flee or switch.', 'El oponente no puede huir o cambiar.', '
INSERT INTO public.movimiento VALUES ('MV00834', 'Thrash', 'Golpe', 'User attacks for 2-3 turns but then becomes confused.', 'El usuario ataca durante 2 o 3 turnos, pero luego se confunde.', '
