INSERT INTO public.movimiento VALUES ('MV00837', 'Thunder Cage', 'Electrojaula', 'Deals damage and traps opponent, damaging them for 4-5 turns.', 'Inflige daño y atrapa al oponente, dañándolo durante 4-5 turnos.', '
