INSERT INTO public.movimiento VALUES ('MV00845', 'Tidy Up', NULL, 'Removes the effects of entry hazards and Substitute, and boosts user’s Attack and Speed.', 'Elimina los efectos de los peligros de entrada y el Sustituto, y aumenta el Ataque y la Velocidad del usuario.', '
