INSERT INTO public.movimiento VALUES ('MV00852', 'Trailblaze', NULL, 'Raises user''s Speed.', 'Aumenta la velocidad del usuario.', '
INSERT INTO public.movimiento VALUES ('MV00853', 'Transform', 'Transformación', 'User takes on the form and attacks of the opponent.', 'El usuario toma la forma y ataca al oponente.', '
