INSERT INTO public.tipos_recurso VALUES ('CI01', 'Hold items', 'Artículos poseidos');
INSERT INTO public.tipos_recurso VALUES ('CI02', 'General items', 'Artículos generales');
INSERT INTO public.tipos_recurso VALUES ('CI03', 'Battle items', 'Objetos de batalla');
INSERT INTO public.tipos_recurso VALUES ('CI04', 'Berries', 'Bayas');
INSERT INTO public.tipos_recurso VALUES ('CI05', 'Medicine', 'Medicamento');
INSERT INTO public.tipos_recurso VALUES ('CI06', 'Pokeballs', 'Pokébolas');
INSERT INTO public.tipos_recurso VALUES ('CI07', 'Machines', 'Máquinas');
INSERT INTO public.recurso VALUES (1, 'Ability Capsule', 'Cápsula de habilidad', 'CI01', 'A capsule that allows a Pokémon with two Abilities to switch between these Abilities when it is used.', 'Una cápsula que permite a un Pokémon con dos Habilidades cambiar entre estas Habilidades cuando se usa.');
INSERT INTO public.recurso VALUES (2, 'Ability Patch', 'Parche de habilidad', 'CI02', 'Changes a Pokémon''s ability to its Hidden Ability.', 'Cambia la habilidad de un Pokémon a su Habilidad Oculta.');
INSERT INTO public.recurso VALUES (3, 'Ability Shield', 'Escudo de habilidad', NULL, 'An item to be held by a Pokémon. This cute and rather unique-looking shield protects the holder from having its Ability changed by others.', 'Un objeto para ser sostenido por un Pokémon. Este escudo lindo y de aspecto único protege al portador de que otros cambien su habilidad.');
INSERT INTO public.recurso VALUES (4, 'Ability Urge', 'Impulso de habilidad', 'CI03', 'When used, it activates the Ability of an ally Pokémon.', 'Cuando se usa, activa la habilidad de un Pokémon aliado.');
INSERT INTO public.recurso VALUES (5, 'Abomasite', 'Abomasita', 'CI01', 'Enables Abomasnow to Mega Evolve during battle.', 'Permite que Abomasnow megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (6, 'Absolite', 'Absoluto', 'CI01', 'Enables Absol to Mega Evolve during battle.', 'Permite a Absol megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (7, 'Absorb Bulb', 'Bombilla absorbente', 'CI01', 'A consumable bulb. If the holder is hit by a Water-type move, its Sp. Atk will rise.', 'Una bombilla consumible. Si el portador es golpeado por un movimiento de tipo Agua, su Sp. Atk aumentará.');
INSERT INTO public.recurso VALUES (8, 'Academy Ball', 'baile de la academia', NULL, 'The academy’s standard-issue ball in a regulation size. Lots of students believe that if you kick it right on the academy emblem, it’ll fly in a straight line.', 'El balón estándar de la academia en tamaño reglamentario. Muchos estudiantes creen que si lo pateas justo en el emblema de la academia, volará en línea recta.');
INSERT INTO public.recurso VALUES (9, 'Academy Bottle', 'botella de la academia', NULL, 'A bottle emblazoned with the academy’s emblem. It’s light, sturdy, and vacuum insulated, so it’ll keep your hots hot and your colds cold.', 'Una botella adornada con el emblema de la academia. Es liviano, resistente y está aislado al vacío, por lo que mantendrá calientes los calores y fríos los resfriados.');
INSERT INTO public.recurso VALUES (10, 'Academy Cup', 'Copa de la academia', NULL, 'The academy’s standard-issue cup for picnicking. The careful design of its mouth makes it popular both inside and outside the academy.', 'El vaso estándar de la academia para ir de picnic. El cuidado diseño de su boca lo hace popular tanto dentro como fuera de la academia.');
INSERT INTO public.recurso VALUES (11, 'Academy Tablecloth', 'mantel de la academia', NULL, 'The academy’s standard-issue tablecloth. It’s made with the latest fiber-processing technology and is so tough that not even a Razor Claw can tear it.', 'El mantel estándar de la academia. Está fabricado con la última tecnología de procesamiento de fibra y es tan resistente que ni siquiera una Razor Claw puede rasgarlo.');
INSERT INTO public.recurso VALUES (12, 'Adamant Crystal', 'Cristal firme', 'CI01', NULL, NULL);
INSERT INTO public.recurso VALUES (13, 'Adamant Mint', 'Menta Firme', 'CI03', 'Changes the Pokémon''s stats to match the Adamant nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Firme.');
INSERT INTO public.recurso VALUES (14, 'Adamant Orb', 'Orbe firme', 'CI01', 'Increases the power of Dragon- and Steel-type moves when held by Dialga.', 'Aumenta el poder de los movimientos de tipo Dragón y Acero cuando lo sostiene Dialga.');
INSERT INTO public.recurso VALUES (15, 'Adrenaline Orb', 'Orbe de adrenalina', 'CI01', 'Using it makes wild Pokémon more likely to call for help. If held by a Pokémon, it boosts Speed when intimidated. It can be used only once.', 'Usarlo hace que sea más probable que los Pokémon salvajes pidan ayuda. Si está en manos de un Pokémon, aumenta la velocidad cuando se siente intimidado. Se puede usar una sola vez.');
INSERT INTO public.recurso VALUES (16, 'Aerodactylite', 'Aerodactilita', 'CI01', 'Enables Aerodactyl to Mega Evolve during battle.', 'Permite que Aerodactyl megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (17, 'Aggronite', 'aggronita', 'CI01', 'Enables Aggron to Mega Evolve during battle.', 'Permite a Aggron megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (18, 'Aguav Berry', 'Baya de Aguav', 'CI04', 'Restores HP if it''s low, but may cause confusion.', 'Restaura HP si es bajo, pero puede causar confusión.');
INSERT INTO public.recurso VALUES (19, 'Air Balloon', 'Globo', 'CI01', 'When held by a Pokémon, the Pokémon will float into the air. When the holder is attacked, this item will burst.', 'Cuando está en manos de un Pokémon, el Pokémon flotará en el aire. Cuando el portador es atacado, este objeto estallará.');
INSERT INTO public.recurso VALUES (20, 'Alakazite', 'alakazita', 'CI01', 'Enables Alakazam to Mega Evolve during battle.', 'Permite a Alakazam megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (21, 'Alomomola Mucus', 'moco de alomomola', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (22, 'Aloraichium Z', 'Aloraichium Z', 'CI01', 'Allows Alolan Raichu to upgrade Thunderbolt to a Z-Move, Stoked Sparksurfer.', 'Permite a Alolan Raichu actualizar Thunderbolt a un Z-Move, Stoked Sparksurfer.');
INSERT INTO public.recurso VALUES (23, 'Altarianite', 'Altarianita', 'CI01', 'Enables Altaria to Mega Evolve during battle.', 'Permite a Altaria Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (24, 'Ampharosite', 'anfarosita', 'CI01', 'Enables Ampharos to Mega Evolve during battle.', 'Permite que Ampharos megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (25, 'Amulet Coin', 'moneda de amuleto', 'CI01', 'Doubles prize money if held.', 'Se duplica el dinero del premio si se tiene.');
INSERT INTO public.recurso VALUES (26, 'Antidote', 'Antídoto', 'CI05', 'A spray-type medicine. It lifts the effect of poison from one Pokémon.', 'Un medicamento tipo spray. Elimina el efecto del veneno de un Pokémon.');
INSERT INTO public.recurso VALUES (27, 'Apicot Berry', 'Baya de albaricoque', 'CI04', 'Raises Special Defense when HP is low.', 'Aumenta la defensa especial cuando HP es bajo.');
INSERT INTO public.recurso VALUES (28, 'Apple', 'Manzana', NULL, 'This very sweet ingredient is sliced thin to make it easy to add into a sandwich.', 'Este ingrediente muy dulce se corta en rodajas finas para que sea fácil de agregar a un sándwich.');
INSERT INTO public.recurso VALUES (29, 'Applin Juice', 'Jugo de aplicación', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (30, 'Apricorn', 'albaricoque', 'CI02', 'A fruit whose shell can be used to form the capsules of all manner of Poké Balls when crafting them from scratch.', 'Una fruta cuya cáscara se puede usar para formar las cápsulas de todo tipo de Poké Balls al crearlas desde cero.');
INSERT INTO public.recurso VALUES (31, 'Armor Fossil', 'Fósil de armadura', 'CI02', 'A fossil from a prehistoric Pokémon that lived on the land. It appears to be part of a collar.', 'Un fósil de un Pokémon prehistórico que vivió en la tierra. Parece ser parte de un collar.');
INSERT INTO public.recurso VALUES (32, 'Armorite Ore', 'Mineral de Armorita', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (33, 'Arrokuda Scales', 'Escamas de Arrokuda', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (34, 'Aspear Berry', 'Baya de lanza', 'CI04', 'If held by a Pokémon, it defrosts it.', 'Si lo sostiene un Pokémon, lo descongela.');
INSERT INTO public.recurso VALUES (35, 'Assault Vest', 'Chaleco de asalto', 'CI01', 'Raises Special Defense but prevents the use of status moves.', 'Aumenta la defensa especial pero evita el uso de movimientos de estado.');
INSERT INTO public.recurso VALUES (36, 'Audinite', 'Tela', 'CI01', 'Enables Audino to Mega Evolve during battle.', 'Permite a Audino megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (37, 'Auspicious Armor', 'Armadura auspiciosa', 'CI02', 'Evolves Charcadet into Armarouge.', 'Evolves Charcadet into Armarouge.');
INSERT INTO public.recurso VALUES (38, 'Aux Evasion', 'en la evasión', 'CI03', 'Makes moves less likely to strike a Pokémon during a battle.', 'Hace que los movimientos sean menos propensos a golpear a un Pokémon durante una batalla.');
INSERT INTO public.recurso VALUES (39, 'Aux Guard', 'Guardia auxiliar', 'CI03', 'Sharply boosts the defensive stats of a Pokémon during a battle.', 'Aumenta drásticamente las estadísticas defensivas de un Pokémon durante una batalla.');
INSERT INTO public.recurso VALUES (40, 'Aux Power', 'Alimentación auxiliar', 'CI03', 'Sharply boosts the offensive stats of a Pokémon during a battle.', 'Aumenta drásticamente las estadísticas ofensivas de un Pokémon durante una batalla.');
INSERT INTO public.recurso VALUES (41, 'Aux Powerguard', 'A los Powerguards', 'CI03', 'Sharply boosts the offensive and defensive stats of a Pokémon during a battle.', 'Aumenta drásticamente las estadísticas ofensivas y defensivas de un Pokémon durante una batalla.');
INSERT INTO public.recurso VALUES (42, 'Avocado', 'Palta', NULL, 'An ingredient with sweet notes—though its flavor is very mild. The avocado’s richness, however, makes it satisfying to eat.', 'Un ingrediente con notas dulces, aunque su sabor es muy suave. La riqueza del aguacate, sin embargo, lo hace satisfactorio para comer.');
INSERT INTO public.recurso VALUES (43, 'Awakening', 'Despertar', 'CI05', 'A spray-type medicine. It awakens a Pokémon from the clutches of sleep.', 'Un medicamento tipo spray. Despierta a un Pokémon de las garras del sueño.');
INSERT INTO public.recurso VALUES (44, 'Axew Scales', 'Escamas de hacha', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (45, 'Azurill Fur', 'Piel Azurill', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (46, 'Babiri Berry', 'dos bayas', 'CI04', 'Weakens a supereffective Steel-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Acero contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (47, 'Bach''s Food Tin', 'Lata de comida de Bach', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. The tinned food that Bach sells is curiously popular in Galar.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Las conservas que vende Bach son curiosamente populares en Galar.');
INSERT INTO public.recurso VALUES (48, 'Bacon', 'Tocino', NULL, 'This very salty ingredient has been cooked just shy of charred, making it burst with fragrance and tasty flavor.', 'Este ingrediente muy salado ha sido cocinado casi carbonizado, haciéndolo rebosar de fragancia y sabor sabroso.');
INSERT INTO public.recurso VALUES (49, 'Bagon Scales', 'Escalas de carro', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (50, 'Baguette', 'Junquillo', NULL, 'A long loaf sliced into top and bottom halves. Its aroma of wheat and its straightforward, salty flavor make it pair well with all kinds of sandwich ingredients.', 'Un pan largo cortado en mitades superior e inferior. Su aroma a trigo y su sabor directo y salado hacen que combine bien con todo tipo de ingredientes para sándwiches.');
INSERT INTO public.recurso VALUES (51, 'Ball of Mud', 'bola de barro', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (52, 'Balm Mushroom', 'Hongo Bálsamo', 'CI02', 'A rare mushroom which gives off a nice fragrance. A maniac will buy it for a high price.', 'Un hongo raro que desprende una agradable fragancia. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (53, 'Banana', 'Banana', NULL, 'A very sweet ingredient. This go-to fruit is sweet and rich, and it’s beloved by many Pokémon.', 'Un ingrediente muy dulce. Esta fruta favorita es dulce y rica, y es amada por muchos Pokémon.');
INSERT INTO public.recurso VALUES (54, 'Banettite', 'Banettita', 'CI01', 'Enables Banette to Mega Evolve during battle.', 'Permite a Banette Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (55, 'Barboach Slime', 'Baba de barboach', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (56, 'Barred Cup', 'Copa barrada', NULL, 'A cup that’s as good for using at home as on a picnic. It’s light, sturdy, and stacks well, so it’s a cinch to pack up and carry around.', 'Una taza que es tan buena para usar en casa como en un picnic. Es liviano, resistente y se apila bien, por lo que es muy fácil de empacar y transportar.');
INSERT INTO public.recurso VALUES (57, 'Basculin Fang', 'Colmillo basculino', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (58, 'Basil', 'Albahaca', NULL, 'A very bitter ingredient that’s quite versatile, as herbs go. It’s fragrant and goes well with tomatoes.', 'Un ingrediente muy amargo que es bastante versátil, como hierbas. Es fragante y va bien con los tomates.');
INSERT INTO public.recurso VALUES (59, 'Battle Tablecloth', 'Mantel de batalla', NULL, 'A garish, eye-catching tablecloth. Putting this on your picnic table will inspire any person or Pokémon who eats there to do their best.', 'Un mantel llamativo y llamativo. Poner esto en tu mesa de picnic inspirará a cualquier persona o Pokémon que coma allí a hacer lo mejor que pueda.');
INSERT INTO public.recurso VALUES (60, 'Beach Glass', 'Vidrio de playa', 'CI02', 'A piece of colored glass. Waves have rounded its edges. It''s slightly rough to the touch.', 'Un trozo de cristal de colores. Las olas han redondeado sus bordes. Es un poco áspero al tacto.');
INSERT INTO public.recurso VALUES (61, 'Bean Cake', 'Pastel De Frijoles', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (62, 'Beast Ball', 'Bola Ultraentes', 'CI06', 'A special Poké Ball designed to catch Ultra Beasts. It has a low success rate for catching others.', 'Una Pokébola especial diseñada para atrapar Ultraentes. Tiene una baja tasa de éxito para atrapar a otros.');
INSERT INTO public.recurso VALUES (63, 'Beedrillite', 'Beedrillita', 'CI01', 'Enables Beedrill to Mega Evolve during battle.', 'Permite que Beedrill megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (64, 'Belue Berry', 'Baya de belué', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (65, 'Bergmite Ice', 'Hielo de bergmita', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (66, 'Berry Juice', 'Jugo de bayas', 'CI05', 'A 100% pure juice made of Berries. It restores the HP of one Pokémon by just 20 points.', 'Un jugo 100% puro hecho de Berries. Restaura el HP de un Pokémon por solo 20 puntos.');
INSERT INTO public.recurso VALUES (67, 'Berry Sweet', 'baya dulce', 'CI01', 'Evolves Milcery into Blueberry Flavor Alcremie.', 'Evoluciona Milcery en Blueberry Flavor Alcremie.');
INSERT INTO public.recurso VALUES (68, 'Big Bamboo Shoot', 'Gran brote de bambú', NULL, 'A large and rare bamboo shoot. It’s extremely popular with a certain class of gourmands.', 'Un brote de bambú grande y raro. Es extremadamente popular entre cierta clase de gourmets.');
INSERT INTO public.recurso VALUES (69, 'Big Malasada', 'Gran Malasada', 'CI05', 'Heals all major status conditions.', 'Cura todas las principales condiciones de estado.');
INSERT INTO public.recurso VALUES (70, 'Big Mushroom', 'Hongo grande', 'CI02', 'A large and rare mushroom. It is sought after by collectors.', 'Un hongo grande y raro. Es buscado por los coleccionistas.');
INSERT INTO public.recurso VALUES (71, 'Big Nugget', 'pepita grande', 'CI02', 'A big nugget of pure gold that gives off a lustrous gleam. A maniac will buy it for a high price.', 'Una gran pepita de oro puro que desprende un brillo lustroso. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (72, 'Big Pearl', 'gran perla', 'CI02', 'A quite-large pearl that sparkles in a pretty silver color. It can be sold at a high price to shops.', 'Una perla bastante grande que brilla en un bonito color plateado. Se puede vender a un precio alto en las tiendas.');
INSERT INTO public.recurso VALUES (73, 'Big Root', 'Raíz grande', 'CI01', 'Recovers more HP from HP-stealing moves.', 'Recupera más HP de los movimientos de robo de HP.');
INSERT INTO public.recurso VALUES (74, 'Binding Band', 'Banda vinculante', 'CI01', 'A band that increases the power of binding moves when held.', 'Una banda que aumenta el poder de los movimientos vinculantes cuando se sostiene.');
INSERT INTO public.recurso VALUES (75, 'Bitter Herba Mystica', 'Hierba mística amarga', NULL, 'A legendary condiment with a deeply bitter taste. It’s said to dramatically bolster a body’s immune defenses, though that hasn’t been proven.', 'Un condimento legendario con un sabor profundamente amargo. Se dice que refuerza drásticamente las defensas inmunitarias del cuerpo, aunque eso no ha sido probado.');
INSERT INTO public.recurso VALUES (76, 'Black Apricorn', 'Albaricoque negro', 'CI02', 'A black Apricorn It has an indescribable scent.', 'Un Apricorn negro Tiene un olor indescriptible.');
INSERT INTO public.recurso VALUES (77, 'Black Augurite', 'Augurita negra', 'CI02', 'A glassy black stone that produces a sharp cutting edge when split. It’s loved by a certain Pokémon.', 'Una piedra negra vítrea que produce un filo afilado cuando se parte. Es amado por cierto Pokémon.');
INSERT INTO public.recurso VALUES (78, 'Black Belt', 'Cinta negra', 'CI01', 'Increases the power of Fighting-type moves.', 'Aumenta el poder de los movimientos de tipo Lucha.');
INSERT INTO public.recurso VALUES (79, 'Black Flute', 'flauta negra', 'CI02', 'A toy flute made from black glass. A maniac will buy it for a high price.', 'Una flauta de juguete hecha de cristal negro. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (80, 'Black Glasses', 'Gafas negras', 'CI01', 'Increases the power of Dark-type moves.', 'Aumenta el poder de los movimientos de tipo oscuro.');
INSERT INTO public.recurso VALUES (81, 'Black Sludge', 'lodo negro', 'CI01', 'A held item that gradually restores the HP of Poison-type Pokémon. It inflicts damage on all other types.', 'Un objeto retenido que restaura gradualmente el HP de los Pokémon de tipo Veneno. Inflige daño a todos los demás tipos.');
INSERT INTO public.recurso VALUES (82, 'Black Tumblestone', 'Piedra rodante negra', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (83, 'Blank Plate', 'placa en blanco', 'CI01', NULL, NULL);
INSERT INTO public.recurso VALUES (84, 'Blastoisinite', 'blastoisinita', 'CI01', 'Enables Blastoise to Mega Evolve during battle.', 'Permite a Blastoise megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (85, 'Blazikenite', 'blazikenita', 'CI01', 'Enables Blaziken to Mega Evolve during battle.', 'Permite a Blaziken Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (86, 'Blue Apricorn', 'Albaricoque Azul', 'CI02', 'A blue Apricorn. It smells a bit like grass.', 'Un albaricoque azul. Huele un poco a hierba.');
INSERT INTO public.recurso VALUES (87, 'Blue Bottle', 'botella azul', NULL, 'A go-to bottle widely used for drinks at picnics. Its simple design and portability make it popular among all sorts of people.', 'Una botella de referencia muy utilizada para bebidas en picnics. Su diseño simple y portabilidad lo hacen popular entre todo tipo de personas.');
INSERT INTO public.recurso VALUES (88, 'Blue Cup', 'Copa Azul', NULL, 'A cup sold with the Blue Bottle. The two don’t stack, so they’re tough to pack—but they look good, so they’re popular with those who like to post picnic photos.', 'Una taza vendida con la Botella Azul. Los dos no se apilan, por lo que son difíciles de empacar, pero se ven bien, por lo que son populares entre quienes les gusta publicar fotos de picnic.');
INSERT INTO public.recurso VALUES (89, 'Blue Dish', 'plato azul', NULL, 'A dish for picnics. Comes in plenty of colors to choose from based on the food or the mood. The blue variety is a consistent strong seller.', 'Un plato para picnics. Viene en muchos colores para elegir según la comida o el estado de ánimo. La variedad azul es un fuerte vendedor constante.');
INSERT INTO public.recurso VALUES (90, 'Blue-Flag Pick', 'Selección de bandera azul', NULL, 'This pick flies a blue flag that lends an air of adventure. The flag itself is made of card stock, so it’ll fly proudly even with no wind.', 'Esta selección ondea una bandera azul que le da un aire de aventura. La bandera en sí está hecha de cartulina, por lo que ondeará con orgullo incluso sin viento.');
INSERT INTO public.recurso VALUES (91, 'Blue Flute', 'flauta azul', 'CI02', 'A toy flute made from blue glass. A maniac will buy it for a high price.', 'Una flauta de juguete hecha de cristal azul. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (92, 'Blue Poké Ball Pick', 'Púa de Poké Ball Azul', NULL, 'A sandwich pick with a simple blue Poké Ball design. Often used by Trainers who picked a Water-type Pokémon for their first partner.', 'Una selección de sándwich con un diseño simple de Poké Ball azul. A menudo lo usan Entrenadores que eligieron un Pokémon de tipo Agua como su primer compañero.');
INSERT INTO public.recurso VALUES (93, 'Blue Scarf', 'Bufanda Azul', 'CI02', 'Raises holder''s Beauty aspect in a Contest.', 'Aumenta el aspecto Belleza del poseedor en un Concurso.');
INSERT INTO public.recurso VALUES (94, 'Blue Shard', 'Fragmento azul', 'CI02', 'A small blue shard. It appears to be from some sort of implement made long ago.', 'Un pequeño fragmento azul. Parece ser de algún tipo de implemento hecho hace mucho tiempo.');
INSERT INTO public.recurso VALUES (95, 'Blue-Sky Flower Pick', 'Pico de flor de cielo azul', NULL, 'A flower pick designed to evoke a blue sky. It’s part of a line of “sky-flower” picks. Using a few is guaranteed to boost that special picnic spirit.', 'Una selección de flores diseñada para evocar un cielo azul. Es parte de una línea de selecciones sky-flower. El uso de algunos está garantizado para impulsar ese espíritu especial de picnic.');
INSERT INTO public.recurso VALUES (96, 'Blue Tablecloth', 'Mantel Azul', NULL, 'A simple blue tablecloth. It’s smooth and pleasant to the touch, and dishes can be placed on it with hardly a sound.', 'Un simple mantel azul. Es suave y agradable al tacto, y se pueden colocar platos sobre él sin apenas ruido.');
INSERT INTO public.recurso VALUES (97, 'Bluk Berry', 'Baya borrosa', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (98, 'Blunder Policy', 'Política de errores', 'CI01', 'Raises Speed sharply if its attack misses.', 'Aumenta la velocidad bruscamente si su ataque falla.');
INSERT INTO public.recurso VALUES (99, 'Bob''s Food Tin', 'Lata de comida de Bob', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. The tinned food that Bob sells is curiously popular in Galar.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. La comida enlatada que vende Bob es curiosamente popular en Galar.');
INSERT INTO public.recurso VALUES (100, 'Boiled Egg', 'Huevo duro', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. Even just one boiled egg can really enhance a dish.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Incluso un solo huevo cocido realmente puede mejorar un plato.');
INSERT INTO public.recurso VALUES (101, 'Bold Mint', 'Menta Osada', 'CI03', 'Changes the Pokémon''s stats to match the Bold nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Osada.');
INSERT INTO public.recurso VALUES (102, 'Bombirdier Feather', 'Pluma de bombardero', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (103, 'Bonsly Tears', 'Lágrimas de Bonsly', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (104, 'Booster Energy', 'Energía de refuerzo', NULL, 'An item to be held by Pokémon with certain Abilities. The energy that fills this capsule boosts the strength of the Pokémon.', 'Un objeto para ser sostenido por Pokémon con ciertas Habilidades. La energía que llena esta cápsula potencia la fuerza de los Pokémon.');
INSERT INTO public.recurso VALUES (105, 'Bottle Cap', 'Tapa de botella', 'CI02', 'Maximizes one IV stat in Hyper Training.', 'Maximiza una estadística IV en Hyper Training.');
INSERT INTO public.recurso VALUES (106, 'Bounsweet Sweat', 'sudor dulce', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (107, 'Bramblin Twig', 'Ramita de Bramblin', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (108, 'Brave Mint', 'Menta Audaz', 'CI03', 'Changes the Pokémon''s stats to match the Brave nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Audaz.');
INSERT INTO public.recurso VALUES (109, 'Bread', 'Pan', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. An indispensable tool for mopping up that extra curry left on your plate.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Una herramienta indispensable para limpiar ese curry extra que queda en tu plato.');
INSERT INTO public.recurso VALUES (110, 'Bright Powder', 'polvo brillante', 'CI01', 'Lowers the opponent''s accuracy.', 'Reduce la precisión del oponente.');
INSERT INTO public.recurso VALUES (111, 'Brittle Bones', 'Huesos frágiles', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. The taste boiled off from the bones is sure to give a dish a light umami taste.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. El sabor hervido de los huesos seguramente le dará a un plato un ligero sabor a umami.');
INSERT INTO public.recurso VALUES (112, 'Bronze Bottle', 'Botella de bronce', NULL, 'A popular option among hikers. It’s made with titanium, so it doesn’t rust even if it’s used to hold drinks with high sodium content.', 'Una opción popular entre los excursionistas. Está fabricado con titanio, por lo que no se oxida aunque se utilice para contener bebidas con alto contenido de sodio.');
INSERT INTO public.recurso VALUES (113, 'Bronze Cup', 'Copa de Bronce', NULL, 'A popular option among hikers. It’s made with titanium, so it doesn’t rust even if it’s used to hold drinks with high sodium content.', 'Una opción popular entre los excursionistas. Está fabricado con titanio, por lo que no se oxida aunque se utilice para contener bebidas con alto contenido de sodio.');
INSERT INTO public.recurso VALUES (114, 'Bronzor Fragment', 'Fragmento de bronce', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (115, 'Bruxish Tooth', 'Diente brusco', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (116, 'Bug Gem', 'Gema de bicho', 'CI01', 'Increases the power of a Bug-type move only once.', 'Aumenta el poder de un movimiento de tipo Bicho solo una vez.');
INSERT INTO public.recurso VALUES (117, 'Bug Memory', 'Memoria de error', 'CI01', 'Changes Silvally and its move Multi-Attack to Bug type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Bicho.');
INSERT INTO public.recurso VALUES (118, 'Bug Tera Shard', 'Fragmento de insecto Tera', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (119, 'Buginium Z', 'Buginio Z', 'CI01', 'Allows the use of Savage Spin-Out, the Bug type Z-Move.', 'Permite el uso de Savage Spin-Out, el Z-Move tipo Bug.');
INSERT INTO public.recurso VALUES (120, 'Bugwort', 'bugwort', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (121, 'Buizel Fur', 'Piel de Buizel', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (122, 'Burn Drive', 'Grabar unidad', 'CI01', 'Changes Techno Blast to a Fire-type move when held by Genesect.', 'Cambia Techno Blast a un movimiento de tipo Fuego cuando lo sostiene Genesect.');
INSERT INTO public.recurso VALUES (123, 'Burn Heal', 'Quemar sanar', 'CI05', 'A spray-type medicine. It heals a single Pokémon that is suffering from a burn.', 'Un medicamento tipo spray. Cura a un solo Pokémon que sufre una quemadura.');
INSERT INTO public.recurso VALUES (124, 'Butter', 'Manteca', NULL, 'A condiment that unites salty and sweet and also packs a richness that makes bread a delight to eat. The finest butter products are made of 100 percent Moomoo Milk.', 'Un condimento que une lo salado y lo dulce y que además encierra una riqueza que hace que el pan sea una delicia para comer. Los mejores productos de mantequilla están hechos 100 por ciento de Moomoo Milk.');
INSERT INTO public.recurso VALUES (125, 'B&W Grass Tablecloth', 'Mantel de hierba blanco y negro', NULL, 'A tablecloth with a fun, trendy black-and-white design featuring Pokémon that seem poised to leap from the tall grass at any moment.', 'Un mantel con un diseño divertido y moderno en blanco y negro con Pokémon que parecen estar listos para saltar de la hierba alta en cualquier momento.');
INSERT INTO public.recurso VALUES (126, 'Cacnea Needle', 'Aguja de cnea', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (127, 'Cake-Lure Base', 'Base de señuelo de pastel', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (128, 'Calcium', 'Calcio', 'CI05', 'Increases Special Attack EVs by 10.', 'Aumenta los EV de los ataques especiales en 10.');
INSERT INTO public.recurso VALUES (129, 'Calm Mint', 'Menta Serena', 'CI03', 'Changes the Pokémon''s stats to match the Calm nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Serena.');
INSERT INTO public.recurso VALUES (130, 'Cameruptite', 'cameruptado', 'CI01', 'Enables Camerupt to Mega Evolve during battle.', 'Permite a Camerupt megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (131, 'Candy Truffle', 'Trufa De Caramelo', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (132, 'Capsakid Seed', 'Semilla de Capsakid', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (133, 'Carbos', 'carbohidratos', 'CI05', 'Increases Speed EVs by 10.', 'Aumenta los EV de velocidad en 10.');
INSERT INTO public.recurso VALUES (134, 'Careful Mint', 'Menta Cauta', 'CI03', 'Changes the Pokémon''s stats to match the Careful nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Cauta.');
INSERT INTO public.recurso VALUES (135, 'Carrot Seeds', 'Semillas de Zanahoria', 'CI02', 'Seeds to plant in a field. The kind of carrot you’ll get is determined by which field you plant the seeds in.', 'Semillas para plantar en un campo. El tipo de zanahoria que obtendrás está determinado por el campo en el que plantes las semillas.');
INSERT INTO public.recurso VALUES (136, 'Casteliacone', 'Casteliacone', 'CI05', 'Heals all major status conditions.', 'Cura todas las principales condiciones de estado.');
INSERT INTO public.recurso VALUES (137, 'Caster Fern', 'helecho lanzador', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (138, 'Cell Battery', 'Batería de celda', 'CI01', 'A consumable battery. If the holder is hit by an Electric-type move, its Attack will rise.', 'Una batería consumible. Si el poseedor es golpeado por un movimiento de tipo Eléctrico, su Ataque aumentará.');
INSERT INTO public.recurso VALUES (139, 'Cetoddle Grease', 'Grasa Cetoddle', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (140, 'Chalky Stone', 'Piedra Calcárea', 'CI02', 'A small whitish stone picked up at the edge of the road.', 'Una pequeña piedra blanquecina recogida al borde del camino.');
INSERT INTO public.recurso VALUES (141, 'Charcadet Soot', 'Hollín Charcadet', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (142, 'Charcoal', 'Carbón', 'CI01', 'Increases the power of Fire-type moves.', 'Aumenta la potencia de los movimientos de tipo Fuego.');
INSERT INTO public.recurso VALUES (143, 'Charizardite X', 'Charizardita X', 'CI01', 'Enables Charizard to Mega Evolve during battle.', 'Permite a Charizard Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (144, 'Charizardite Y', 'Charizardite Y', 'CI01', 'Enables Charizard to Mega Evolve during battle.', 'Permite a Charizard Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (145, 'Charti Berry', 'Baya Charti', 'CI04', 'Weakens a supereffective Rock-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Roca contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (146, 'Cheese', 'Queso', NULL, 'A very salty ingredient. This thinly sliced cheese is perfect for adding to a sandwich.', 'Un ingrediente muy salado. Este queso en rodajas finas es perfecto para agregar a un sándwich.');
INSERT INTO public.recurso VALUES (147, 'Cheri Berry', 'baya cheri', 'CI04', 'If held by a Pokémon, it recovers from paralysis.', 'Si lo sostiene un Pokémon, se recupera de la parálisis.');
INSERT INTO public.recurso VALUES (148, 'Cherish Ball', 'Bola Gloriosa', 'CI06', 'A quite rare Poké Ball that has been specially crafted to commemorate an occasion of some sort.', 'Una Pokébola bastante rara que ha sido especialmente diseñada para conmemorar algún tipo de ocasión.');
INSERT INTO public.recurso VALUES (149, 'Cherry Tomatoes', 'Tomates cherry', NULL, 'A very tart ingredient. Some varieties are also very sweet, and these are prized above all others by the people of Paldea.', 'Un ingrediente muy ácido. Algunas variedades también son muy dulces, y son las más apreciadas por la gente de Paldea.');
INSERT INTO public.recurso VALUES (150, 'Chesto Berry', 'Baya de Chesto', 'CI04', 'If held by a Pokémon, it recovers from sleep.', 'Si lo sostiene un Pokémon, se recupera del sueño.');
INSERT INTO public.recurso VALUES (151, 'Chewtle Claw', 'Garra masticable', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (152, 'Chilan Berry', 'Baya de Chilán', 'CI04', 'Weakens a Normal-type attack against the Pokémon holding this berry.', 'Debilita un ataque de tipo Normal contra el Pokémon que tenga esta baya.');
INSERT INTO public.recurso VALUES (153, 'Chili Sauce', 'salsa de chile', NULL, 'A condiment with a very spicy kick. It’s thanks to Scovillain that this sauce gets its signature mouth-tingling burn.', 'Un condimento con un toque muy picante. Es gracias a Scovillain que esta salsa obtiene su característica quemadura que hormiguea en la boca.');
INSERT INTO public.recurso VALUES (154, 'Chill Drive', 'Conducir frío', 'CI01', 'Changes Techno Blast to an Ice-type move when held by Genesect.', 'Cambia Techno Blast a un movimiento de tipo hielo cuando lo sostiene Genesect.');
INSERT INTO public.recurso VALUES (155, 'Chipped Pot', 'Olla Astillada', 'CI01', 'Evolves Sinistea into Polteageist.', 'Evoluciona a Sinistea en Polteageist.');
INSERT INTO public.recurso VALUES (156, 'Choice Band', 'Cinta Elegida', 'CI01', 'Raises Attack, but only one move can be used.', 'Aumenta el Ataque, pero solo se puede usar un movimiento.');
INSERT INTO public.recurso VALUES (157, 'Choice Dumpling', 'Elección de bola de masa hervida', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (158, 'Choice Scarf', 'Bufanda Elegida', 'CI01', 'Raises Speed, but only one move can be used.', 'Aumenta la velocidad, pero solo se puede usar un movimiento.');
INSERT INTO public.recurso VALUES (159, 'Choice Specs', 'Especificaciones de elección', 'CI01', 'Raises Special Attack, but only one move can be used.', 'Aumenta el ataque especial, pero solo se puede usar un movimiento.');
INSERT INTO public.recurso VALUES (160, 'Chople Berry', 'Baya Chople', 'CI04', 'Weakens a supereffective Fighting-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Lucha contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (161, 'Chorizo', 'Chorizo', NULL, 'A very salty and spicy ingredient. This type of sausage has particularly robust salty flavor, and the spicier varieties are extra popular.', 'Un ingrediente muy salado y picante. Este tipo de salchicha tiene un sabor salado particularmente fuerte, y las variedades más picantes son muy populares.');
INSERT INTO public.recurso VALUES (162, 'Clauncher Claw', 'Garra de lanzador', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (163, 'Claw Fossil', 'Fósil de garra', 'CI02', 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a claw.', 'Un fósil de un antiguo Pokémon que vivía en el mar. Parece ser parte de una garra.');
INSERT INTO public.recurso VALUES (164, 'Cleanse Tag', 'etiqueta de limpieza', 'CI01', 'An item to be held by a Pokémon. It helps keep wild Pokémon away if the holder is the first one in the party.', 'Un objeto para ser sostenido por un Pokémon. Ayuda a mantener alejados a los Pokémon salvajes si el titular es el primero en el grupo.');
INSERT INTO public.recurso VALUES (165, 'Clear Amulet', 'Amuleto claro', NULL, 'An item to be held by a Pokémon. This clear, sparkling amulet protects the holder from having its stats lowered by moves used against it or by other Pokémon’s Abilities.', 'Un objeto para ser sostenido por un Pokémon. Este amuleto transparente y brillante protege a su poseedor de que sus estadísticas disminuyan debido a los movimientos utilizados en su contra o por las habilidades de otros Pokémon.');
INSERT INTO public.recurso VALUES (166, 'Clever Wing', 'Ala inteligente', 'CI05', 'Increases Special Defense EVs by 1.', 'Aumenta los EV de Defensa Especial en 1.');
INSERT INTO public.recurso VALUES (167, 'Clover Sweet', 'trébol dulce', 'CI01', 'Evolves Milcery into Clover Flavor Alcremie.', 'Evoluciona Milcery en Clover Flavor Alcremie.');
INSERT INTO public.recurso VALUES (168, 'Coba Berry', 'Prueba las bayas', 'CI04', 'Weakens a supereffective Flying-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Volador contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (169, 'Coconut Milk', 'Leche de coco', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. The refined sweetness of this coconut milk makes it quite popular.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. La dulzura refinada de esta leche de coco la hace bastante popular.');
INSERT INTO public.recurso VALUES (170, 'Colbur Berry', 'Baya Colbur', 'CI04', 'Weakens a supereffective Dark-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Siniestro contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (171, 'Combee Honey', 'Combee miel', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (172, 'Comet Shard', 'Fragmento de cometa', 'CI02', 'A shard which fell to the ground when a comet approached. A maniac will buy it for a high price.', 'Un fragmento que cayó al suelo cuando se acercó un cometa. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (173, 'Cornn Berry', 'Maíz Baya', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (174, 'Courage Candy', 'Caramelo de coraje', 'CI05', 'Increases a Pokémon''s Special Defense stat by 1.', 'Aumenta la estadística de Defensa Especial de un Pokémon en 1.');
INSERT INTO public.recurso VALUES (175, 'Courage Candy L', 'Coraje Caramelo L', 'CI05', 'Increases a Pokémon''s Special Defense stat.', 'Aumenta la estadística de Defensa Especial de un Pokémon.');
INSERT INTO public.recurso VALUES (176, 'Courage Candy XL', 'Caramelo Coraje XL', 'CI05', 'Increases a Pokémon''s Special Defense stat.', 'Aumenta la estadística de Defensa Especial de un Pokémon.');
INSERT INTO public.recurso VALUES (177, 'Cover Fossil', 'Cubrir Fósil', 'CI02', 'A fossil of an ancient Pokémon that lived in the sea in ancient times. It appears to be part of its back.', 'Un fósil de un antiguo Pokémon que vivió en el mar en la antigüedad. Parece ser parte de su espalda.');
INSERT INTO public.recurso VALUES (178, 'Covert Cloak', 'Capa encubierta', 'CI01', 'Conceals the holder, protecting it from the additional effects of moves.', 'Oculta al titular, protegiéndolo de los efectos adicionales de los movimientos.');
INSERT INTO public.recurso VALUES (179, 'Crabrawler Shell', 'Caparazón de reptador', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (180, 'Cracked Pot', 'Olla rota', 'CI01', 'Evolves Sinistea into Polteageist.', 'Evoluciona a Sinistea en Polteageist.');
INSERT INTO public.recurso VALUES (181, 'Crafting Kit', 'Kit de elaboración', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (182, 'Cream Cheese', 'Queso crema', NULL, 'A condiment offering very sweet and very tart flavor. It goes well with more ingredients than you’d expect, making it a convenient go-to.', 'Un condimento que ofrece un sabor muy dulce y muy ácido. Va bien con más ingredientes de los que cabría esperar, lo que lo convierte en una opción conveniente.');
INSERT INTO public.recurso VALUES (183, 'Croagunk Poison', 'Veneno Croagunk', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (184, 'Crunchy Salt', 'sal crujiente', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (185, 'Cryogonal Ice', 'Hielo criogonal', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (186, 'Cubchoo Fur', 'Piel de cachorro', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (187, 'Cucumber', 'Pepino', NULL, 'A tart and bitter ingredient. Using it together with rich-tasting ingredients in a sandwich will really make the most of a cucumber’s fresh-veggie aroma.', 'Un ingrediente ácido y amargo. Usarlo junto con ingredientes de rico sabor en un sándwich realmente aprovechará al máximo el aroma de vegetales frescos de un pepino.');
INSERT INTO public.recurso VALUES (188, 'Cufant Tarnish', 'Cufant deslustre', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (189, 'Curry Powder', 'Polvo de curry', NULL, 'A very spicy condiment. Just watch out—use too much of this potent seasoning, and it’ll cancel out the other flavors.', 'Un condimento muy picante. Solo tenga cuidado: use demasiado de este potente condimento y cancelará los otros sabores.');
INSERT INTO public.recurso VALUES (190, 'Custap Berry', 'Baya Custap', 'CI04', 'Holder can move first when HP is low.', 'El titular puede moverse primero cuando HP es bajo.');
INSERT INTO public.recurso VALUES (191, 'Cyber Ball', 'Pelota cibernética', NULL, 'A ball themed after hardcore gaming PCs. It may not light up like its inspiration, but it still stands out.', 'Una pelota con el tema de las PC para juegos hardcore. Puede que no se ilumine como su inspiración, pero aun así se destaca.');
INSERT INTO public.recurso VALUES (192, 'Cyclizar Scales', 'Balanzas Ciclistas', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (193, 'Damp Mulch', 'mantillo húmedo', 'CI02', 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.', 'Un fertilizante para esparcir en suelos blandos en regiones donde se cultivan bayas. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (194, 'Damp Rock', 'roca húmeda', 'CI01', 'A Pokémon held item that extends the duration of the move Rain Dance used by the holder.', 'Un objeto Pokémon que se extiende la duración del movimiento Rain Dance utilizado por el poseedor.');
INSERT INTO public.recurso VALUES (195, 'Dark Gem', 'Gema oscura', 'CI01', 'Increases the power of a Dark-type move only once.', 'Aumenta el poder de un movimiento de tipo oscuro solo una vez.');
INSERT INTO public.recurso VALUES (196, 'Dark Memory', 'Memoria oscura', 'CI01', 'Changes Silvally and its move Multi-Attack to Dark type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Oscuro.');
INSERT INTO public.recurso VALUES (197, 'Dark Tera Shard', 'Fragmento de Tera oscuro', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (198, 'Darkinium Z', 'Darkinio Z', 'CI01', 'Allows the use of Black Hole Eclipse, the Dark type Z-Move.', 'Permite el uso de Black Hole Eclipse, el Z-Move de tipo oscuro.');
INSERT INTO public.recurso VALUES (199, 'Dawn Stone', 'Piedra del amanecer', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (200, 'Dazzling Honey', 'Miel deslumbrante', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (201, 'Decidium Z', 'Decidio Z', 'CI01', 'Allows Decidueye to upgrade Spirit Shackle to a Z-Move, Sinister Arrow Raid.', 'Permite a Decidueye actualizar Spirit Shackle a un Z-Move, Sinister Arrow Raid.');
INSERT INTO public.recurso VALUES (202, 'Dedenne Fur', 'Piel de Dedenne', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (203, 'Deep Sea Scale', 'Escala de aguas profundas', 'CI01', 'Increases Special Defense when held by Clamperl. Evolves Clamperl when traded holding the item.', 'Aumenta la defensa especial cuando está en manos de Clamperl. Evoluciona a Clamperl cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (204, 'Deep Sea Tooth', 'Diente de mar profundo', 'CI01', 'Increases Special Attack when held by Clamperl. Evolves Clamperl when traded holding the item.', 'Aumenta el Ataque Especial cuando lo sostiene Clamperl. Evoluciona a Clamperl cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (205, 'Deerling Hair', 'pelo de venado', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (206, 'Deino Scales', 'Balanzas Deino', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (207, 'Delibird Parcel', 'Paquete Delibird', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (208, 'Destiny Knot', 'Nudo del destino', 'CI01', 'A long, thin, bright-red string to be held by a Pokémon. If the holder becomes infatuated, the foe does too.', 'Una cuerda larga, delgada y de color rojo brillante para ser sostenida por un Pokémon. Si el poseedor se enamora, el enemigo también lo hace.');
INSERT INTO public.recurso VALUES (209, 'Diamond Bottle', 'Botella de diamante', NULL, 'A diamond-patterned bottle that’s small, light, and even comes with a cup. The detachable strap makes it handy for walking around with.', 'Una botella con diseño de diamantes que es pequeña, liviana e incluso viene con una taza. La correa desmontable lo hace útil para caminar.');
INSERT INTO public.recurso VALUES (210, 'Diamond Pattern Cup', 'Copa con patrón de diamantes', NULL, 'A cup that’s as good for using at home as on a picnic. It’s light, sturdy, and stacks well, so it’s a cinch to pack up and carry around.', 'Una taza que es tan buena para usar en casa como en un picnic. Es liviano, resistente y se apila bien, por lo que es muy fácil de empacar y transportar.');
INSERT INTO public.recurso VALUES (211, 'Diamond Tablecloth', 'mantel de diamantes', NULL, 'A tablecloth with a fashionable diamond pattern. It’s great at repelling water and mold, and stains and smudges wipe right off.', 'Un mantel con un moderno diseño de rombos. Es excelente para repeler el agua y el moho, y las manchas y manchas se limpian de inmediato.');
INSERT INTO public.recurso VALUES (212, 'Diancite', 'Diancita', 'CI01', 'Enables Diancie to Mega Evolve during battle.', 'Permite a Diancie megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (213, 'Digger Drill', 'Taladro excavador', NULL, 'A single-use drill to bore a hole in the wall for your Secret Base.', 'Un taladro de un solo uso para hacer un agujero en la pared para tu base secreta.');
INSERT INTO public.recurso VALUES (214, 'Diglett Dirt', 'Suciedad Diglett', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (215, 'Dire Hit', 'Golpe terrible', 'CI03', 'Raises critical-hit ratio of a Pokémon in battle.', 'Aumenta la tasa de golpes críticos de un Pokémon en la batalla.');
INSERT INTO public.recurso VALUES (216, 'Dire Hit 2', 'Golpe terrible 2', 'CI03', 'Raises a Pokémon''s critical-hit ratio in battle.', 'Aumenta la proporción de golpes críticos de un Pokémon en la batalla.');
INSERT INTO public.recurso VALUES (217, 'Dire Hit 3', 'Golpe terrible 3', 'CI03', 'Greatly raises a Pokémon''s critical-hit ratio in battle.', 'Aumenta enormemente la proporción de golpes críticos de un Pokémon en la batalla.');
INSERT INTO public.recurso VALUES (218, 'Direshroom', 'Hongo funesto', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (219, 'Discount Coupon', 'Cupón de descuento', 'CI02', 'This special coupon allows you to buy items at a discount when you are shopping at a boutique.', 'Este cupón especial le permite comprar artículos con descuento cuando compra en una boutique.');
INSERT INTO public.recurso VALUES (220, 'Discovery Slate', 'Pizarra de descubrimiento', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Discovery Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puede sentir una fuerte conexión entre él y Discovery Room en Ramanas Park.');
INSERT INTO public.recurso VALUES (221, 'Distortion Slate', 'Pizarra de distorsión', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Distortion Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y Distortion Room en Ramanas Park.');
INSERT INTO public.recurso VALUES (222, 'Ditto Goo', 'Ídem Goo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (223, 'Dive Ball', 'Bola de Buceo', 'CI06', 'A somewhat different Poké Ball that works especially well on Pokémon that live underwater.', 'Una Poké Ball algo diferente que funciona especialmente bien en Pokémon que viven bajo el agua.');
INSERT INTO public.recurso VALUES (224, 'DNA Splicers', 'Empalmadores de ADN', 'CI02', 'A splicer that fuses Kyurem and a certain Pokémon. They are said to have been one in the beginning.', 'Un splicer que fusiona a Kyurem y cierto Pokémon. Se dice que fueron uno al principio.');
INSERT INTO public.recurso VALUES (225, 'Dome Fossil', 'Fósil de cúpula', 'CI02', 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a shell.', 'Un fósil de un antiguo Pokémon que vivía en el mar. Parece ser parte de un caparazón.');
INSERT INTO public.recurso VALUES (226, 'Dondozo Whisker', 'Bigote Dondozo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (227, 'Doppel Bonnets', 'Capós dobles', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (228, 'Douse Drive', 'Apague la unidad', 'CI01', 'Changes Techno Blast to a Water-type move when held by Genesect.', 'Cambia Techno Blast a un movimiento de tipo Agua cuando lo sostiene Genesect.');
INSERT INTO public.recurso VALUES (229, 'Draco Plate', 'Plato Draco', 'CI01', 'Increases power of Dragon-type moves. Changes Arceus'' type to Dragon.', 'Aumenta el poder de los movimientos de tipo Dragón. Cambia el tipo de Arceus a Dragón.');
INSERT INTO public.recurso VALUES (230, 'Dragon Fang', 'dientes de Dragon', 'CI01', 'Increases the power of Dragon-type moves.', 'Aumenta el poder de los movimientos de tipo Dragón.');
INSERT INTO public.recurso VALUES (231, 'Dragon Gem', 'Gema de dragón', 'CI01', 'Increases the power of a Dragon-type move only once.', 'Aumenta el poder de un movimiento de tipo Dragón solo una vez.');
INSERT INTO public.recurso VALUES (232, 'Dragon Memory', 'Memoria del dragón', 'CI01', 'Changes Silvally and its move Multi-Attack to Dragon type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Dragón.');
INSERT INTO public.recurso VALUES (233, 'Dragon Scale', 'Escala de dragón', 'CI02', 'Evolves Seadra when traded holding the item.', 'Evoluciona a Seadra cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (234, 'Dragon Tera Shard', 'Fragmento de Tera Dragón', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (235, 'Dragonium Z', 'Dragonio Z', 'CI01', 'Allows the use of Devastating Drake, the Dragon type Z-Move.', 'Permite el uso de Devastating Drake, el Z-Move de tipo Dragón.');
INSERT INTO public.recurso VALUES (236, 'Dratini Scales', 'Escamas Dratini', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (237, 'Dread Plate', 'Plato aterrador', 'CI01', 'Increases power of Dark-type moves. Changes Arceus'' type to Dark.', 'Aumenta el poder de los movimientos de tipo oscuro. Cambia el tipo de Arceus a Oscuro.');
INSERT INTO public.recurso VALUES (238, 'Dream Ball', 'Bola de Sueño', 'CI06', 'A special Poké Ball that appears out of nowhere in a bag at the Entree Forest. It can catch any Pokémon.', 'Una Pokébola especial que aparece de la nada en una bolsa en Entree Forest. Puede atrapar a cualquier Pokémon.');
INSERT INTO public.recurso VALUES (239, 'Dreepy Powder', 'Polvo somnoliento', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (240, 'Drifloon Gas', 'Gas de lluvia', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (241, 'Dropped Item', 'Artículo descartado', 'CI01', 'The Xtransceiver found at the Nimbasa City amusement park. It seems it belongs to a boy.', 'El Xtransceiver encontrado en el parque de atracciones Nimbasa City. Parece que pertenece a un niño.');
INSERT INTO public.recurso VALUES (242, 'Drowzee Fur', 'Piel de drowzee', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (243, 'Dubious Disc', 'disco dudoso', 'CI02', 'Evolves Porygon2 when traded holding the item.', 'Evoluciona a Porygon2 cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (244, 'Dunsparce Scales', 'Escamas de Dunsparce', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (245, 'Durin Berry', 'Baya durin', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (246, 'Dusk Ball', 'Bola de Ocaso', 'CI06', 'A somewhat different Poké Ball that makes it easier to catch wild Pokémon at night or in dark places like caves.', 'Una Poké Ball algo diferente que facilita la captura de Pokémon salvajes por la noche o en lugares oscuros como cuevas.');
INSERT INTO public.recurso VALUES (247, 'Dusk Stone', 'Piedra de Ocaso', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (248, 'Dynamax Candy', 'Caramelo Dinamax', 'CI05', 'Raises Dynamax Level.', 'Eleva el nivel de Dynamax.');
INSERT INTO public.recurso VALUES (249, 'Dynite Ore', 'Mineral de dinita', 'CI02', 'Mysterious ore that can be obtained in the Max Lair. Something good will happen if you give it to a collector in the Crown Tundra.', 'Mineral misterioso que se puede obtener en Max Lair. Algo bueno sucederá si se lo das a un coleccionista en Crown Tundra.');
INSERT INTO public.recurso VALUES (250, 'Earth Plate', 'Placa de tierra', 'CI01', 'Increases power of Ground-type moves. Changes Arceus'' type to Ground.', 'Aumenta el poder de los movimientos de tipo Tierra. Cambia el tipo de Arceus a Tierra.');
INSERT INTO public.recurso VALUES (251, 'Eevee Cup', 'Copa Eevee', NULL, 'A cup for big-time Pokémon fans. Kids will happily drink out of it, making it a boon to parents.', 'Una taza para los grandes fanáticos de Pokémon. Los niños beberán felizmente, lo que lo convierte en una bendición para los padres.');
INSERT INTO public.recurso VALUES (252, 'Eevee Fur', 'Piel de Eevee', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (253, 'Eevium Z', 'Eevium Z', 'CI01', 'Allows Eevee to upgrade Last Resort to a Z-Move, Extreme Evoboost.', 'Permite a Eevee actualizar Last Resort a un Z-Move, Extreme Evoboost.');
INSERT INTO public.recurso VALUES (254, 'Egg', 'Huevo', NULL, 'An ingredient with a touch of saltiness. It’s full of nutrients and can be enjoyed with all sorts of seasonings.', 'Un ingrediente con un toque de sal. Está lleno de nutrientes y se puede disfrutar con todo tipo de condimentos.');
INSERT INTO public.recurso VALUES (255, 'Eiscue Down', 'Eiscue abajo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (256, 'Eject Button', 'Botón de expulsión', 'CI01', 'If the holder is hit by an attack, it will switch with another Pokémon in your party.', 'Si el portador es golpeado por un ataque, cambiará con otro Pokémon en tu grupo.');
INSERT INTO public.recurso VALUES (257, 'Eject Pack', 'Expulsar paquete', 'CI01', 'The Pokémon switches out if its stats are lowered.', 'El Pokémon cambia si sus estadísticas se reducen.');
INSERT INTO public.recurso VALUES (258, 'Electirizer', 'electrizante', 'CI02', 'Evolves Electabuzz when traded holding the item.', 'Evoluciona a Electabuzz cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (259, 'Electric Gem', 'Gema eléctrica', 'CI01', 'Increases the power of an Electric-type move only once.', 'Aumenta la potencia de un movimiento de tipo eléctrico solo una vez.');
INSERT INTO public.recurso VALUES (260, 'Electric Memory', 'Memoria eléctrica', 'CI01', 'Changes Silvally and its move Multi-Attack to Electric type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Eléctrico.');
INSERT INTO public.recurso VALUES (261, 'Electric Seed', 'Semilla eléctrica', 'CI01', 'An item to be held by a Pokémon. It boosts Defense on Electric Terrain. It can only be used once.', 'Un objeto para ser sostenido por un Pokémon. Aumenta la Defensa en Terreno Eléctrico. Solo se puede usar una vez.');
INSERT INTO public.recurso VALUES (262, 'Electric Tera Shard', 'Fragmento de Tera eléctrico', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (263, 'Electrium Z', 'Electrio Z', 'CI01', 'Allows the use of Gigavolt Havoc, the Electric type Z-Move.', 'Permite el uso de Gigavolt Havoc, el tipo eléctrico Z-Move.');
INSERT INTO public.recurso VALUES (264, 'Elevator Key', 'Llave del ascensor', 'CI01', 'A card key that activates the elevator in Lysandre Labs. It is emblazoned with Team Flare''s logo.', 'Una llave de tarjeta que activa el ascensor en Lysandre Labs. Está adornado con el logotipo de Team Flare.');
INSERT INTO public.recurso VALUES (265, 'Elixir', 'Elixir', 'CI05', 'It restores the PP of all the moves learned by the targeted Pokémon by 10 points each.', 'Restaura el PP de todos los movimientos aprendidos por el Pokémon objetivo en 10 puntos cada uno.');
INSERT INTO public.recurso VALUES (266, 'Energy Powder', 'Polvo de energía', 'CI05', 'Restores 60 HP but lowers Friendship.', 'Restaura 60 HP pero reduce la amistad.');
INSERT INTO public.recurso VALUES (267, 'Energy Root', 'Raíz de energía', 'CI05', 'Restores 120 HP but lowers Friendship.', 'Restaura 120 HP pero reduce la amistad.');
INSERT INTO public.recurso VALUES (268, 'Enigma Berry', 'Baya Enigma', 'CI04', 'If held by a Pokémon, it restores its HP if it is hit by any supereffective attack.', 'Si está en manos de un Pokémon, restaura su HP si es golpeado por cualquier ataque supereficaz.');
INSERT INTO public.recurso VALUES (269, 'Escape Rope', 'Cuerda de escape', 'CI02', 'A long, durable rope. Use it to escape instantly from a cave or a dungeon.', 'Una cuerda larga y duradera. Úsalo para escapar instantáneamente de una cueva o mazmorra.');
INSERT INTO public.recurso VALUES (270, 'Ether', 'Éter', 'CI05', 'It restores the PP of a Pokémon''s selected move by a maximum of 10 points.', 'Restaura el PP del movimiento seleccionado de un Pokémon por un máximo de 10 puntos.');
INSERT INTO public.recurso VALUES (271, 'Everstone', 'Piedra Eterna', 'CI01', 'An item to be held by a Pokémon. The Pokémon holding this peculiar stone is prevented from evolving.', 'Un objeto para ser sostenido por un Pokémon. El Pokémon que porta esta peculiar piedra no puede evolucionar.');
INSERT INTO public.recurso VALUES (272, 'Eviolite', 'eviolita', 'CI01', 'A mysterious evolutionary lump. When held, it raises the Defense and Sp. Def of a Pokémon that can still evolve.', 'Un misterioso bulto evolutivo. Cuando se mantiene, aumenta la Defensa y Sp. Def de un Pokémon que todavía puede evolucionar.');
INSERT INTO public.recurso VALUES (273, 'Exercise Ball', 'Pelota de ejercicio', NULL, 'A big ball designed for exercising. It can work as a seat if you get tired, too.', 'Una gran pelota diseñada para hacer ejercicio. También puede funcionar como asiento si te cansas.');
INSERT INTO public.recurso VALUES (274, 'Exp. Candy L', 'Exp. Caramelo L', 'CI05', NULL, NULL);
INSERT INTO public.recurso VALUES (275, 'Exp. Candy M', 'Exp. caramelo m', 'CI05', NULL, NULL);
INSERT INTO public.recurso VALUES (276, 'Exp. Candy S', 'Exp. Dulces', 'CI05', NULL, NULL);
INSERT INTO public.recurso VALUES (277, 'Exp. Candy XL', 'Exp. Caramelo XL', 'CI05', 'Increases the Pokémon''s Exp points by 30,000.', 'Incrementa los puntos Exp del Pokémon en 30,000.');
INSERT INTO public.recurso VALUES (278, 'Exp. Candy XS', 'Exp. Caramelo XS', 'CI05', NULL, NULL);
INSERT INTO public.recurso VALUES (279, 'Exp. Share', 'Exp. Compartir', 'CI01', 'An item to be held by a Pokémon. The holder gets a share of a battle''s Exp. Points without battling.', 'Un objeto para ser sostenido por un Pokémon. El poseedor obtiene una parte de la EXP de una batalla. Puntos sin batallar.');
INSERT INTO public.recurso VALUES (280, 'Expert Belt', 'Cinturón experto', 'CI01', 'Increases the power of super-effective moves.', 'Aumenta el poder de los movimientos súper efectivos.');
INSERT INTO public.recurso VALUES (281, 'Fairium Z', 'Fairium Z', 'CI01', 'Allows the use of Twinkle Tackle, the Fairy type Z-Move.', 'Permite el uso de Twinkle Tackle, el Z-Move tipo hada.');
INSERT INTO public.recurso VALUES (282, 'Fairy Gem', 'Gema de hadas', 'CI02', 'Increases the power of a Fairy-type move only once.', 'Aumenta el poder de un movimiento de tipo Hada solo una vez.');
INSERT INTO public.recurso VALUES (283, 'Fairy Memory', 'Memoria de hadas', 'CI01', 'Changes Silvally and its move Multi-Attack to Fairy type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Hada.');
INSERT INTO public.recurso VALUES (284, 'Fairy Tera Shard', 'Fragmento de Hada Tera', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (285, 'Falinks Sweat', 'Sudor Falinks', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (286, 'Fancy Apple', 'Manzana elegante', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. An apple chosen above others. It has spectacular form and a brilliant sheen.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Una manzana elegida por encima de otras. Tiene una forma espectacular y un brillo brillante.');
INSERT INTO public.recurso VALUES (287, 'Fast Ball', 'Bola Rapida', 'CI06', 'A Poké Ball that makes it easier to catch Pokémon which are quick to run away.', 'Una Poké Ball que facilita la captura de Pokémon que huyen rápidamente.');
INSERT INTO public.recurso VALUES (288, 'Feather Ball', 'Bola de plumas', 'CI06', NULL, NULL);
INSERT INTO public.recurso VALUES (289, 'Festival Ticket', 'Boleto de fiesta', 'CI02', 'A ticket that allows you to host a mission in Festival Plaza.', 'Un boleto que te permite albergar una misión en Festival Plaza.');
INSERT INTO public.recurso VALUES (290, 'Fidough Fur', 'Piel de fidough', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (291, 'Fighting Gem', 'Gema de lucha', 'CI01', 'Increases the power of a Fighting-type move only once.', 'Aumenta el poder de un movimiento de tipo Lucha solo una vez.');
INSERT INTO public.recurso VALUES (292, 'Fighting Memory', 'Memoria de lucha', 'CI01', 'Changes Silvally and its move Multi-Attack to Fighting type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Lucha.');
INSERT INTO public.recurso VALUES (293, 'Fighting Tera Shard', 'Fragmento de lucha contra Tera', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (294, 'Fightinium Z', 'Fightinio Z', 'CI01', 'Allows the use of All-Out Pummeling, the Fighting type Z-Move.', 'Permite el uso de All-Out Pummeling, el Z-Move de tipo Fighting.');
INSERT INTO public.recurso VALUES (295, 'Figy Berry', 'Baya de higo', 'CI04', 'Restores HP if it''s low, but may cause confusion.', 'Restaura HP si es bajo, pero puede causar confusión.');
INSERT INTO public.recurso VALUES (296, 'Fine Remedy', 'Buen remedio', 'CI05', NULL, NULL);
INSERT INTO public.recurso VALUES (297, 'Finizen Mucus', 'moco finizen', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (298, 'Finneon Scales', 'Escamas de neón', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (299, 'Fire Gem', 'Gema de fuego', 'CI01', 'Increases the power of a Fire-type move only once.', 'Aumenta la potencia de un movimiento de tipo Fuego solo una vez.');
INSERT INTO public.recurso VALUES (300, 'Fire Memory', 'Memoria de fuego', 'CI01', 'Changes Silvally and its move Multi-Attack to Fire type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Fuego.');
INSERT INTO public.recurso VALUES (301, 'Fire Pattern Cup', 'Copa de patrón de fuego', NULL, 'A cup that’s as good for using at home as on a picnic. It’s light, sturdy, and stacks well, so it’s a cinch to pack up and carry around.', 'Una taza que es tan buena para usar en casa como en un picnic. Es liviano, resistente y se apila bien, por lo que es muy fácil de empacar y transportar.');
INSERT INTO public.recurso VALUES (302, 'Fire Stone', 'Piedra de fuego', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (303, 'Fire Tera Shard', 'Fragmento de Tera de fuego', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (304, 'Firium Z', 'Firio Z', 'CI01', 'Allows the use of Inferno Overdrive, the Fire type Z-Move.', 'Permite el uso de Inferno Overdrive, el Z-Move tipo Fuego.');
INSERT INTO public.recurso VALUES (305, 'Fist Plate', 'placa de puño', 'CI01', 'Increases power of Fighting-type moves. Changes Arceus'' type to Fighting.', 'Aumenta el poder de los movimientos de tipo Lucha. Cambia el tipo de Arceus a Lucha.');
INSERT INTO public.recurso VALUES (306, 'Flabébé Pollen', 'Polen Flabebe', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (307, 'Flame Orb', 'Orbe de llamas', 'CI01', 'An item to be held by a Pokémon. It is a bizarre orb that inflicts a burn on the holder in battle.', 'Un objeto para ser sostenido por un Pokémon. Es un orbe extraño que inflige una quemadura en el portador en la batalla.');
INSERT INTO public.recurso VALUES (308, 'Flame Plate', 'Placa de llama', 'CI01', 'Increases power of Fire-type moves. Changes Arceus'' type to Fire.', 'Aumenta el poder de los movimientos de tipo Fuego. Cambia el tipo de Arceus a Fuego.');
INSERT INTO public.recurso VALUES (309, 'Flamigo Down', 'flamenco abajo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (310, 'Fletchling Feather', 'Pluma de polluelo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (311, 'Flittle Down', 'Volar hacia abajo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (312, 'Float Stone', 'Piedra flotante', 'CI01', 'A very light stone. It reduces the weight of a Pokémon when held.', 'Una piedra muy ligera. Reduce el peso de un Pokémon cuando se sostiene.');
INSERT INTO public.recurso VALUES (313, 'Flower Pattern Cup', 'Taza con estampado de flores', NULL, 'A cup for kids to use at picnics. It’s made of light but strong material. It’s stackable, which makes it handy for carrying around.', 'Una taza para que los niños la usen en los picnics. Está hecho de un material ligero pero resistente. Es apilable, lo que lo hace práctico para transportar.');
INSERT INTO public.recurso VALUES (314, 'Flower Sweet', 'flor dulce', 'CI01', 'Evolves Milcery into Flower Flavor Alcremie.', 'Evoluciona Milcery en Flower Flavor Alcremie.');
INSERT INTO public.recurso VALUES (315, 'Fluffy Tail', 'Cola esponjosa', 'CI02', 'An item that attracts Pokémon. Use it to flee from any battle with a wild Pokémon.', 'Un objeto que atrae Pokémon. Úsalo para huir de cualquier batalla con un Pokémon salvaje.');
INSERT INTO public.recurso VALUES (316, 'Flying Gem', 'Gema voladora', 'CI01', 'Increases the power of a Flying-type move only once.', 'Aumenta la potencia de un movimiento de tipo Volador solo una vez.');
INSERT INTO public.recurso VALUES (317, 'Flying Memory', 'Memoria voladora', 'CI01', 'Changes Silvally and its move Multi-Attack to Flying type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Volador.');
INSERT INTO public.recurso VALUES (318, 'Flying Tera Shard', 'Fragmento de Tera volador', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (319, 'Flyinium Z', 'Flyinio Z', 'CI01', 'Allows the use of Supersonic Skystrike, the Flying type Z-Move.', 'Permite el uso de Supersonic Skystrike, el Z-Move de tipo volador.');
INSERT INTO public.recurso VALUES (320, 'Focus Band', 'Banda de enfoque', 'CI01', 'An item to be held by a Pokémon. The holder may endure a potential KO attack, leaving it with just 1 HP.', 'Un objeto para ser sostenido por un Pokémon. El titular puede soportar un posible ataque KO, dejándolo con solo 1 HP.');
INSERT INTO public.recurso VALUES (321, 'Focus Sash', 'Faja de enfoque', 'CI01', 'An item to be held by a Pokémon. If it has full HP, the holder will endure one potential KO attack, leaving 1 HP.', 'Un objeto para ser sostenido por un Pokémon. Si tiene HP completo, el poseedor soportará un posible ataque KO, dejando 1 HP.');
INSERT INTO public.recurso VALUES (322, 'Fomantis Leaf', 'Hoja Fomantis', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (323, 'Foongus Spores', 'Esporas Foongus', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (324, 'Fossilized Bird', 'Pájaro fosilizado', 'CI02', 'The fossil of an ancient Pokémon that once soared through the sky. What it looked like is a mystery.', 'El fósil de un antiguo Pokémon que una vez voló por los cielos. Lo que parecía es un misterio.');
INSERT INTO public.recurso VALUES (325, 'Fossilized Dino', 'dinosaurio fosilizado', 'CI02', 'The fossil of an ancient Pokémon that once lived in the sea. What it looked like is a mystery.', 'El fósil de un antiguo Pokémon que una vez vivió en el mar. Lo que parecía es un misterio.');
INSERT INTO public.recurso VALUES (326, 'Fossilized Drake', 'Draco fosilizado', 'CI02', 'The fossil of an ancient Pokémon that once roamed the land. What it looked like is a mystery.', 'El fósil de un antiguo Pokémon que una vez vagó por la tierra. Lo que parecía es un misterio.');
INSERT INTO public.recurso VALUES (327, 'Fossilized Fish', 'Pescado fosilizado', 'CI02', 'The fossil of an ancient Pokémon that once lived in the sea. What it looked like is a mystery.', 'El fósil de un antiguo Pokémon que una vez vivió en el mar. Lo que parecía es un misterio.');
INSERT INTO public.recurso VALUES (328, 'Fresh Cream', 'Crema fresca', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. Add some whipped cream to a spicy curry to give it some sweetness.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Agregue un poco de crema batida a un curry picante para darle un poco de dulzura.');
INSERT INTO public.recurso VALUES (329, 'Fresh Water', 'Agua dulce', 'CI05', 'Restores 30 HP.', 'Restaura 30 HP.');
INSERT INTO public.recurso VALUES (330, 'Fried Fillet', 'Filete Frito', NULL, 'When used in a sandwich, this very salty and bitter ingredient is at its best paired with sour seasonings.', 'Cuando se usa en un sándwich, este ingrediente muy salado y amargo se combina mejor con condimentos ácidos.');
INSERT INTO public.recurso VALUES (331, 'Fried Food', 'Comida frita', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. It’s been a while since it was fried, so it’s gotten greasy.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Ha pasado un tiempo desde que se fríe, por lo que se ha puesto grasoso.');
INSERT INTO public.recurso VALUES (332, 'Friend Ball', 'Bola Amiga', 'CI06', 'A Poké Ball that makes caught Pokémon more friendly.', 'Una Poké Ball que hace que los Pokémon capturados sean más amistosos.');
INSERT INTO public.recurso VALUES (333, 'Frigibax Scales', 'Balanzas Frigibax', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (334, 'Fruit Bunch', 'racimo de frutas', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. The syrupy fruits give off a strong tropical feel.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Las frutas almibaradas emiten una fuerte sensación tropical.');
INSERT INTO public.recurso VALUES (335, 'Full Heal', 'Totalmente curado', 'CI05', 'A spray-type medicine. It heals all the status problems of a single Pokémon.', 'Un medicamento tipo spray. Cura todos los problemas de estado de un solo Pokémon.');
INSERT INTO public.recurso VALUES (336, 'Full Incense', 'Incienso Completo', 'CI01', 'Holder always attacks last. Breeding Snorlax produces Munchlax when held.', 'El titular siempre ataca en último lugar. La cría de Snorlax produce Munchlax cuando se sostiene.');
INSERT INTO public.recurso VALUES (337, 'Full Restore', 'Restauración completa', 'CI05', 'A medicine that fully restores the HP and heals any status problems of a single Pokémon.', 'Una medicina que restaura completamente el HP y cura cualquier problema de estado de un solo Pokémon.');
INSERT INTO public.recurso VALUES (338, 'Galarica Cuff', 'Brazalete galárica', 'CI02', 'Evolves Galarian Slowpoke into Galarian Slowbro.', 'Evoluciona Galarian Slowpoke en Galarian Slowbro.');
INSERT INTO public.recurso VALUES (339, 'Galarica Twig', 'Ramita galárica', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (340, 'Galarica Wreath', 'Corona Galarrica', 'CI02', 'Evolves Galarian Slowpoke into Galarian Slowking.', 'Evoluciona Galarian Slowpoke en Galarian Slowking.');
INSERT INTO public.recurso VALUES (341, 'Galladite', 'galadita', 'CI01', 'Enables Gallade to Mega Evolve during battle.', 'Permite a Gallade Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (342, 'Ganlon Berry', 'Baya de Ganlón', 'CI04', 'Raises Defense when HP is low.', 'Aumenta la defensa cuando HP es bajo.');
INSERT INTO public.recurso VALUES (343, 'Garchompite', 'garchompita', 'CI01', 'Enables Garchomp to Mega Evolve during battle.', 'Permite que Garchomp megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (344, 'Gardevoirite', 'Gardevoirita', 'CI01', 'Enables Gardevoir to Mega Evolve during battle.', 'Permite que Gardevoir megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (345, 'Gastly Gas', 'gas gastoso', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (346, 'Gengarite', 'gengarita', 'CI01', 'Enables Gengar to Mega Evolve during battle.', 'Permite a Gengar Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (347, 'Genius Wing', 'Ala de genio', 'CI05', 'Increases Special Attack EVs by 1.', 'Aumenta los EV de los ataques especiales en 1.');
INSERT INTO public.recurso VALUES (348, 'Genome Slate', 'Pizarra del genoma', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Genome Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y la Sala del Genoma en el Parque Ramanas.');
INSERT INTO public.recurso VALUES (349, 'Gentle Mint', 'Menta Amable', 'CI03', 'Changes the Pokémon''s stats to match the Gentle nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Amable.');
INSERT INTO public.recurso VALUES (350, 'Ghost Gem', 'Gema fantasma', 'CI01', 'Increases the power of a Ghost-type move only once.', 'Aumenta el poder de un movimiento de tipo Fantasma solo una vez.');
INSERT INTO public.recurso VALUES (351, 'Ghost Memory', 'Memoria fantasma', 'CI01', 'Changes Silvally and its move Multi-Attack to Ghost type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Fantasma.');
INSERT INTO public.recurso VALUES (352, 'Ghost Tera Shard', 'Fragmento de Tera fantasma', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (353, 'Ghostium Z', 'Fantasma Z', 'CI01', 'Allows the use of Never-Ending Nightmare, the Ghost type Z-Move.', 'Permite el uso de Never-Ending Nightmare, el Z-Move tipo Fantasma.');
INSERT INTO public.recurso VALUES (354, 'Gible Scales', 'Balanzas gibles', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (355, 'Gigantamix', 'Gigantamix', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. A mysterious spice. Even a tiny sprinkle is sure to make a curry gigantic.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Una especia misteriosa. Incluso una pequeña pizca seguramente hará que un curry sea gigantesco.');
INSERT INTO public.recurso VALUES (356, 'Gigaton Ball', 'Bola de Gigaton', 'CI06', NULL, NULL);
INSERT INTO public.recurso VALUES (357, 'Gimmighoul Coin', 'Moneda Gimmighoul', NULL, 'Material accidentally dropped by a Pokémon. It seems that Gimmighoul treasure and hoard these.', 'Material dejado caer accidentalmente por un Pokémon. Parece que Gimmighoul los atesora y acumula.');
INSERT INTO public.recurso VALUES (358, 'Girafarig Fur', 'Piel de jirafarig', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (359, 'Glalitite', 'Glalitita', 'CI01', 'Enables Glalie to Mega Evolve during battle.', 'Permite a Glalie megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (360, 'Glimmet Crystal', 'Cristal de destello', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (361, 'Gold Bottle', 'botella de oro', NULL, 'A popular option among hikers. It’s made with titanium, so it doesn’t rust even if it’s used to hold drinks with high sodium content.', 'Una opción popular entre los excursionistas. Está fabricado con titanio, por lo que no se oxida aunque se utilice para contener bebidas con alto contenido de sodio.');
INSERT INTO public.recurso VALUES (362, 'Gold Bottle Cap', 'Tapa de botella de oro', 'CI02', 'Maximizes all of a Pokémon''s IV stats in Hyper Training.', 'Maximiza todas las estadísticas IV de un Pokémon en Hyper Training.');
INSERT INTO public.recurso VALUES (363, 'Gold Cup', 'Copa de Oro', NULL, 'A popular option among hikers. It’s made with titanium, so it doesn’t rust even if it’s used to hold drinks with high sodium content.', 'Una opción popular entre los excursionistas. Está fabricado con titanio, por lo que no se oxida aunque se utilice para contener bebidas con alto contenido de sodio.');
INSERT INTO public.recurso VALUES (364, 'Gold Leaf', 'Hoja de oro', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (365, 'Gold Pick', 'Púa de oro', NULL, 'A golden pick that oozes class. Using it on a sandwich lends an extravagant air that’ll make you want to eat up, even if you don’t love the fillings.', 'Una púa dorada que rezuma clase. Usarlo en un sándwich le da un aire extravagante que te hará querer comer, incluso si no te gustan los rellenos.');
INSERT INTO public.recurso VALUES (366, 'Golden Nanab Berry', 'Baya dorada de Nanab', 'CI04', 'Drastically calms a Pokémon in battle, in Let''s Go Pikachu/Eevee.', 'Calma drásticamente a un Pokémon en batalla, en Let''s Go Pikachu/Eevee.');
INSERT INTO public.recurso VALUES (367, 'Golden Pinap Berry', 'Baya de piña dorada', 'CI04', 'Drastically increases chance of getting items when a Pokémon is caught, in Pokémon Let''s Go.', 'Aumenta drásticamente la posibilidad de obtener elementos cuando se atrapa un Pokémon, en Pokémon Let''s Go.');
INSERT INTO public.recurso VALUES (368, 'Golden Razz Berry', 'Baya Razz Dorada', 'CI04', 'Makes a Pokémon easier to catch in Pokémon Let''s Go.', 'Hace que un Pokémon sea más fácil de atrapar en Pokémon Let''s Go.');
INSERT INTO public.recurso VALUES (369, 'Gooey Mulch', 'Mantillo pegajoso', 'CI02', 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.', 'Un fertilizante para esparcir en suelos blandos en regiones donde se cultivan bayas. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (370, 'Goomy Goo', 'pegajoso pegajoso', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (371, 'Gothita Eyelash', 'Pestañas Gothita', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (372, 'Grain Cake', 'Pastel de cereales', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (373, 'Grass Gem', 'Gema de hierba', 'CI01', 'Increases the power of a Grass-type move only once.', 'Aumenta el poder de un movimiento de tipo Hierba solo una vez.');
INSERT INTO public.recurso VALUES (374, 'Grass Memory', 'Memoria de hierba', 'CI01', 'Changes Silvally and its move Multi-Attack to Grass type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Hierba.');
INSERT INTO public.recurso VALUES (375, 'Grass Tera Shard', 'Fragmento de Tera de hierba', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (376, 'Grassium Z', 'Grassium Z', 'CI01', 'Allows the use of Bloom Doom, the Grass type Z-Move.', 'Permite el uso de Bloom Doom, el Z-Move tipo Hierba.');
INSERT INTO public.recurso VALUES (377, 'Grassy Seed', 'Semilla herbosa', 'CI01', 'An item to be held by a Pokémon. It boosts Defense on Grassy Terrain. It can only be used once.', 'Un objeto para ser sostenido por un Pokémon. Aumenta la defensa en terreno herboso. Solo se puede usar una vez.');
INSERT INTO public.recurso VALUES (378, 'Great Ball', 'Super Bola', 'CI06', 'A good, high-performance Ball that provides a higher Pokémon catch rate than a standard Poké Ball.', 'Una buena bola de alto rendimiento que proporciona una mayor tasa de captura de Pokémon que una Poké Ball estándar.');
INSERT INTO public.recurso VALUES (379, 'Greavard Wax', 'Cera de Greavard', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (380, 'Green Apricorn', 'albaricoque verde', 'CI02', 'A green Apricorn. It has a mysterious, aromatic scent.', 'Un albaricoque verde. Tiene un olor misterioso y aromático.');
INSERT INTO public.recurso VALUES (381, 'Green Bell Pepper', 'Pimiento verde', NULL, 'An ingredient with some bitterness. When sliced, it adds a nice accent to a sandwich.', 'Un ingrediente con algo de amargor. Cuando se rebana, agrega un agradable acento a un sándwich.');
INSERT INTO public.recurso VALUES (382, 'Green Dish', 'plato verde', NULL, 'A dish for picnics. Comes in plenty of colors to choose from based on the food or the mood. The green variety is quite popular.', 'Un plato para picnics. Viene en muchos colores para elegir según la comida o el estado de ánimo. La variedad verde es bastante popular.');
INSERT INTO public.recurso VALUES (383, 'Green Poké Ball Pick', 'Púa de Poké Ball Verde', NULL, 'A sandwich pick with a simple green Poké Ball design. Often used by Trainers who picked a Grass-type Pokémon for their first partner.', 'Una selección de sándwich con un diseño simple de Poké Ball verde. A menudo lo usan Entrenadores que eligieron un Pokémon de tipo Planta como su primer compañero.');
INSERT INTO public.recurso VALUES (384, 'Green Scarf', 'Bufanda Verde', 'CI02', 'Raises holder''s Smart aspect in a Contest.', 'Aumenta el aspecto Inteligente del poseedor en un Concurso.');
INSERT INTO public.recurso VALUES (385, 'Green Shard', 'Fragmento verde', 'CI02', 'A small green shard. It appears to be from some sort of implement made long ago.', 'Un pequeño fragmento verde. Parece ser de algún tipo de implemento hecho hace mucho tiempo.');
INSERT INTO public.recurso VALUES (386, 'Grepa Berry', 'agarrar baya', 'CI04', 'Increases Friendship but lowers Special Defense EVs.', 'Aumenta la amistad pero reduce los EV de defensa especial.');
INSERT INTO public.recurso VALUES (387, 'Grimer Toxin', 'Toxina más sombría', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (388, 'Grip Claw', 'Garra de agarre', 'CI01', 'A Pokémon held item that extends the duration of multiturn attacks like Bind and Wrap.', 'Un objeto de Pokémon que extiende la duración de los ataques de varios turnos como Bind and Wrap.');
INSERT INTO public.recurso VALUES (389, 'Griseous Core', 'Núcleo grisáceo', 'CI01', NULL, NULL);
INSERT INTO public.recurso VALUES (390, 'Griseous Orb', 'Orbe grisáceo', 'CI01', 'Increases the power of Dragon- and Ghost-type moves when held by Giratina, and changes it to Origin Forme.', 'Aumenta el poder de los movimientos de tipo Dragón y Fantasma cuando Giratina los sujeta y los cambia a Forma de origen.');
INSERT INTO public.recurso VALUES (391, 'Grit Dust', 'polvo de arena', 'CI01', NULL, NULL);
INSERT INTO public.recurso VALUES (392, 'Grit Gravel', 'grava de arena', 'CI01', NULL, NULL);
INSERT INTO public.recurso VALUES (393, 'Grit Pebble', 'Guijarro de arena', 'CI01', NULL, NULL);
INSERT INTO public.recurso VALUES (394, 'Grit Rock', 'Roca de arena', 'CI01', NULL, NULL);
INSERT INTO public.recurso VALUES (395, 'Ground Gem', 'Gema de tierra', 'CI01', 'Increases the power of a Ground-type move only once.', 'Aumenta la potencia de un movimiento de tipo Tierra solo una vez.');
INSERT INTO public.recurso VALUES (396, 'Ground Memory', 'Memoria de tierra', 'CI01', 'Changes Silvally and its move Multi-Attack to Ground type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Tierra.');
INSERT INTO public.recurso VALUES (397, 'Ground Tera Shard', 'Fragmento de Tera molido', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (398, 'Groundium Z', 'Groundio Z', 'CI01', 'Allows the use of Tectonic Rage, the Ground type Z-Move.', 'Permite el uso de Tectonic Rage, el Z-Move de tipo Tierra.');
INSERT INTO public.recurso VALUES (399, 'Growlithe Fur', 'Pelaje de Growlithe', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (400, 'Growth Mulch', 'mantillo de crecimiento', 'CI02', 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.', 'Un fertilizante para esparcir en suelos blandos en regiones donde se cultivan bayas. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (401, 'Grubby Hanky', 'pañuelo sucio', 'CI01', 'A handkerchief dropped by a regular at Café Warehouse. It smells faintly like a Pokémon.', 'Un pañuelo dejado caer por un habitual en Café Warehouse. Huele un poco a Pokémon.');
INSERT INTO public.recurso VALUES (402, 'Guard Spec.', 'Especificaciones de la Guardia', 'CI03', 'Prevents stat reduction for five turns.', 'Evita la reducción de estadísticas durante cinco turnos.');
INSERT INTO public.recurso VALUES (403, 'Gulpin Mucus', 'Mucosidad de trago', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (404, 'Gyaradosite', 'Gyaradosita', 'CI01', 'Enables Gyarados to Mega Evolve during battle.', 'Permite a Gyarados Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (405, 'Haban Berry', 'Haban Berry', 'CI04', 'Weakens a supereffective Dragon-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Dragón contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (406, 'Ham', 'jamón', NULL, 'A very salty ingredient—and that very saltiness is what makes it such a nice companion to veggies.', 'Un ingrediente muy salado, y esa misma salinidad es lo que lo convierte en un buen compañero para las verduras.');
INSERT INTO public.recurso VALUES (407, 'Hamburger', 'Hamburguesa', NULL, 'This very salty ingredient is the thing to add if you want to make your sandwich truly filling.', 'Este ingrediente muy salado es lo que debe agregar si desea que su sándwich sea realmente abundante.');
INSERT INTO public.recurso VALUES (408, 'Happiny Dust', 'polvo feliz', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (409, 'Hard Stone', 'Piedra dura', 'CI01', 'Increases the power of Rock-type moves.', 'Aumenta el poder de los movimientos de tipo Roca.');
INSERT INTO public.recurso VALUES (410, 'Hasty Mint', 'Menta Activa', 'CI03', 'Changes the Pokémon''s stats to match the Hasty nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Activa.');
INSERT INTO public.recurso VALUES (411, 'Hatenna Dust', 'Polvo de Hatenna', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (412, 'Hawlucha Down', 'Hawlucha Abajo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (413, 'Heal Ball', 'Bola Sana', 'CI06', 'A remedial Poké Ball that restores the caught Pokémon''s HP and eliminates any status problem.', 'Una Poké Ball reparadora que restaura el HP del Pokémon capturado y elimina cualquier problema de estado.');
INSERT INTO public.recurso VALUES (414, 'Heal Powder', 'Polvo curativo', 'CI05', 'Heals all status problems, but lowers Friendship.', 'Cura todos los problemas de estado, pero reduce la amistad.');
INSERT INTO public.recurso VALUES (415, 'Health Candy', 'Caramelo de salud', 'CI05', 'Increases a Pokémon''s HP stat by 1.', 'Aumenta la estadística de HP de un Pokémon en 1.');
INSERT INTO public.recurso VALUES (416, 'Health Candy L', 'Salud Caramelo L', 'CI05', 'Increases a Pokémon''s HP stat.', 'Aumenta la estadística de HP de un Pokémon.');
INSERT INTO public.recurso VALUES (417, 'Health Candy XL', 'Caramelo Saludable XL', 'CI05', 'Increases a Pokémon''s HP stat.', 'Aumenta la estadística de HP de un Pokémon.');
INSERT INTO public.recurso VALUES (418, 'Health Wing', 'Ala de salud', 'CI05', 'Increases HP EVs by 1.', 'Aumenta los EV de HP en 1.');
INSERT INTO public.recurso VALUES (419, 'Heart Scale', 'Escala de corazón', 'CI02', 'A pretty, heart-shaped scale that is extremely rare. It glows faintly in the colors of the rainbow.', 'Una bonita escama en forma de corazón que es extremadamente rara. Brilla débilmente con los colores del arcoíris.');
INSERT INTO public.recurso VALUES (420, 'Hearty Grains', 'Granos abundantes', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (421, 'Heat Rock', 'Roca de calor', 'CI01', 'A Pokémon held item that extends the duration of the move Sunny Day used by the holder.', 'Un objeto Pokémon que se extiende la duración del movimiento Sunny Day utilizado por el poseedor.');
INSERT INTO public.recurso VALUES (422, 'Heavy Ball', 'Bola Pesada', 'CI06', 'A Poké Ball for catching very heavy Pokémon.', 'Una Poké Ball para atrapar Pokémon muy pesados.');
INSERT INTO public.recurso VALUES (423, 'Heavy-Duty Boots', 'Botas de servicio pesado', 'CI01', 'Protects the holder from traps set on the battlefield.', 'Protege al portador de las trampas colocadas en el campo de batalla.');
INSERT INTO public.recurso VALUES (424, 'Helix Fossil', 'Hélice fósil', 'CI02', 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a seashell.', 'Un fósil de un antiguo Pokémon que vivía en el mar. Parece ser parte de una concha marina.');
INSERT INTO public.recurso VALUES (425, 'Heracronite', 'heracronita', 'CI01', 'Enables Heracross to Mega Evolve during battle.', 'Permite que Heracross megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (426, 'Heracross Claw', 'Garra Heracross', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (427, 'Herbed Sausage', 'Salchicha De Hierbas', NULL, 'A very salty and bitter ingredient. The balance between the potent saltiness and the herbs’ bitterness make this sausage a pleasure.', 'Un ingrediente muy salado y amargo. El equilibrio entre el potente sabor salado y el amargor de las hierbas hacen de esta salchicha un placer.');
INSERT INTO public.recurso VALUES (428, 'Heroic Sword Pick', 'Púa de espada heroica', NULL, 'A pick made to be the coolest. Once you’ve eaten, you can pretend you’re a hero of legend. Souvenir shops at tourist spots sell these for some reason.', 'Una elección hecha para ser la más cool. Una vez que hayas comido, puedes fingir que eres un héroe de leyenda. Las tiendas de recuerdos en los lugares turísticos los venden por alguna razón.');
INSERT INTO public.recurso VALUES (429, 'Hi-tech Earbuds', 'Auriculares de alta tecnología', 'CI01', 'Strange earbuds that allow you to freely control the volume of various sounds.', 'Auriculares extraños que te permiten controlar libremente el volumen de varios sonidos.');
INSERT INTO public.recurso VALUES (430, 'Hippopotas Sand', 'Arena de hipopótamos', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (431, 'HM01', 'HM01', 'CI07', 'Teaches the move Cut.', 'Enseña el movimiento Cortar.');
INSERT INTO public.recurso VALUES (432, 'HM02', 'HM02', 'CI07', 'Teaches the move Fly.', 'Enseña el movimiento Volar.');
INSERT INTO public.recurso VALUES (433, 'HM03', 'HM03', 'CI07', 'Teaches the move Surf.', 'Enseña el movimiento Surf.');
INSERT INTO public.recurso VALUES (434, 'HM04', 'HM04', 'CI07', 'Teaches the move Strength.', 'Enseña el movimiento Fuerza.');
INSERT INTO public.recurso VALUES (435, 'HM05', 'HM05', 'CI07', 'Teaches the move Flash/Defog/Whirlpool/Waterfall.', 'Enseña el movimiento Destello/Desempañar/Remolino/Cascada.');
INSERT INTO public.recurso VALUES (436, 'HM06', 'HM06', 'CI07', 'Teaches the move Whirlpool/Rock Smash/Dive.', 'Enseña el movimiento Whirlpool/Rock Smash/Dive.');
INSERT INTO public.recurso VALUES (437, 'HM07', 'HM07', 'CI07', 'Teaches the move Waterfall.', 'Enseña el movimiento Cascada.');
INSERT INTO public.recurso VALUES (438, 'HM08', 'HM08', 'CI07', 'Teaches the move Dive/Rock Climb.', 'Enseña el movimiento Dive/Rock Climb.');
INSERT INTO public.recurso VALUES (439, 'Hometown Muffin', 'Muffin de la ciudad natal', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (440, 'Hondew Berry', 'Baya Hondew', 'CI04', 'Increases Friendship but lowers Special Attack EVs.', 'Aumenta la amistad pero reduce los EV de los ataques especiales.');
INSERT INTO public.recurso VALUES (441, 'Honey', 'Miel', 'CI02', 'A sweet honey with a lush aroma that attracts wild Pokémon when it is used in grass, caves, or on special trees.', 'Una miel dulce con un aroma exuberante que atrae a Pokémon salvajes cuando se usa en hierba, cuevas o árboles especiales.');
INSERT INTO public.recurso VALUES (442, 'Honey Cake', 'Pastel de miel', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (443, 'Honor Of Kalos', 'honor de kalos', 'CI01', 'A precious symbol that is awarded only to an individual who has done great things for the Kalos region.', 'Un símbolo precioso que se otorga solo a una persona que ha hecho grandes cosas por la región de Kalos.');
INSERT INTO public.recurso VALUES (444, 'Hopo Berry', 'Atrapar bayas', 'CI02', 'A Berry that can be fed to a Pokémon to restore its PP. If a wild Pokémon eats one of these Berries, that Pokémon’s reactions will be dulled.', 'Una baya que se puede alimentar a un Pokémon para restaurar su PP. Si un Pokémon salvaje se come una de estas bayas, las reacciones de ese Pokémon se apagarán.');
INSERT INTO public.recurso VALUES (445, 'Hoppip Leaf', 'hoja de lúpulo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (446, 'Horseradish', 'Rábano picante', NULL, 'A very spicy condiment. Its distinctive sharp sizzle in your sinuses makes it a good match for rich fillings.', 'Un condimento muy picante. Su distintivo chisporroteo agudo en los senos paranasales lo convierte en una buena combinación para rellenos abundantes.');
INSERT INTO public.recurso VALUES (447, 'Houndoominite', 'hounominita', 'CI01', 'Enables Houndoom to Mega Evolve during battle.', 'Permite a Houndoom megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (448, 'Houndour Fang', 'Colmillo de sabueso', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (449, 'HP Up', 'HP arriba', 'CI05', 'Increases HP EVs by 10.', 'Aumenta los EV de HP en 10.');
INSERT INTO public.recurso VALUES (450, 'Hyper Potion', 'Híper poción', 'CI05', 'Restores 120 HP.', 'Restaura 120 HP.');
INSERT INTO public.recurso VALUES (451, 'Iapapa Berry', 'Baya de Iapapa', 'CI04', 'Restores HP if it''s low, but may cause confusion.', 'Restaura HP si es bajo, pero puede causar confusión.');
INSERT INTO public.recurso VALUES (452, 'Ice Gem', 'Gema de hielo', 'CI01', 'Increases the power of an Ice-type move only once.', 'Aumenta el poder de un movimiento de tipo Hielo solo una vez.');
INSERT INTO public.recurso VALUES (453, 'Ice Heal', 'Curación de hielo', 'CI05', 'A spray-type medicine. It defrosts a Pokémon that has been frozen solid.', 'Un medicamento tipo spray. Descongela un Pokémon que se ha congelado completamente.');
INSERT INTO public.recurso VALUES (454, 'Ice Memory', 'Memoria de hielo', 'CI01', 'Changes Silvally and its move Multi-Attack to Ice type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Hielo.');
INSERT INTO public.recurso VALUES (455, 'Ice Stone', 'Piedra de hielo', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (456, 'Ice Tera Shard', 'Fragmento de tera de hielo', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (457, 'Iceroot Carrot', 'Zanahoria Iceroot', 'CI02', 'Produce that the King of Bountiful Harvests’ beloved steed likes to eat. It grew in a field covered in snow.', 'Productos que le gusta comer al amado corcel del Rey de las Cosechas Abundantes. Creció en un campo cubierto de nieve.');
INSERT INTO public.recurso VALUES (458, 'Icicle Plate', 'Placa de carámbano', 'CI01', 'Increases power of Ice-type moves. Changes Arceus'' type to Ice.', 'Aumenta el poder de los movimientos tipo hielo. Cambia el tipo de Arceus a Hielo.');
INSERT INTO public.recurso VALUES (459, 'Icium Z', 'Icio Z', 'CI01', 'Allows the use of Subzero Slammer, the Ice type Z-Move.', 'Permite el uso de Subzero Slammer, el Z-Move tipo hielo.');
INSERT INTO public.recurso VALUES (460, 'Icy Rock', 'roca helada', 'CI01', 'A Pokémon held item that extends the duration of the move Hail used by the holder.', 'Un objeto Pokémon que prolonga la duración del movimiento Hail utilizado por el poseedor.');
INSERT INTO public.recurso VALUES (461, 'Igglybuff Fluff', 'Pelusa Igglybuff', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (462, 'Impidimp Hair', 'Pelo Impidimp', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (463, 'Impish Mint', 'Menta Agitada', 'CI03', 'Changes the Pokémon''s stats to match the Impish nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Agitada.');
INSERT INTO public.recurso VALUES (464, 'Incinium Z', 'Incinio Z', 'CI01', 'Allows Incineroar to upgrade Darkest Lariat to a Z-Move, Malicious Moonsault.', 'Permite a Incineroar actualizar Darkest Lariat a un Z-Move, Malicious Moonsault.');
INSERT INTO public.recurso VALUES (465, 'Indeedee Fur', 'piel de verdad', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (466, 'Insect Plate', 'Plato de insectos', 'CI01', 'Increases power of Bug-type moves. Changes Arceus'' type to Bug.', 'Aumenta el poder de los movimientos tipo Bug. Cambia el tipo de Arceus a Bicho.');
INSERT INTO public.recurso VALUES (467, 'Instant Noodles', 'Fideos instantáneos', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. It has a junk-food sort of taste, but it goes well with curry.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Tiene un sabor a comida chatarra, pero va bien con el curry.');
INSERT INTO public.recurso VALUES (468, 'Intriguing Stone', 'Piedra intrigante', 'CI01', 'A rather curious stone that might appear to be valuable to some. It''s all in the eye of the beholder.', 'Una piedra bastante curiosa que podría parecer valiosa para algunos. Todo está en el ojo del espectador.');
INSERT INTO public.recurso VALUES (469, 'Iron', 'Hierro', 'CI05', 'Increases Defense EVs by 10.', 'Aumenta los EV de Defensa en 10.');
INSERT INTO public.recurso VALUES (470, 'Iron Ball', 'bola de hierro', 'CI01', 'A Pokémon held item that cuts Speed. It makes Flying-type and levitating holders susceptible to Ground moves.', 'Un objeto Pokémon sostenido que reduce la velocidad. Hace que los portadores de tipo volador y levitantes sean susceptibles a los movimientos de tierra.');
INSERT INTO public.recurso VALUES (471, 'Iron Barktongue', 'Lengua de corteza de hierro', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (472, 'Iron Chunk', 'Trozo de hierro', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (473, 'Iron Plate', 'Placa de hierro', 'CI01', 'Increases power of Steel-type moves. Changes Arceus'' type to Steel.', 'Aumenta el poder de los movimientos de tipo Acero. Cambia el tipo de Arceus a Acero.');
INSERT INTO public.recurso VALUES (474, 'Item Drop', 'Caída de artículo', 'CI03', 'When used, it causes an ally Pokémon to drop a held item.', 'Cuando se usa, hace que un Pokémon aliado suelte un objeto retenido.');
INSERT INTO public.recurso VALUES (475, 'Item Urge', 'Artículo urgente', 'CI03', 'When used, it causes an ally Pokémon to use its held item.', 'Cuando se usa, hace que un Pokémon aliado use su objeto retenido.');
INSERT INTO public.recurso VALUES (476, 'Jaboca Berry', 'Baya de jaboca', 'CI04', 'If held by a Pokémon and a physical attack lands, the attacker also takes damage.', 'Si lo sostiene un Pokémon y cae un ataque físico, el atacante también recibe daño.');
INSERT INTO public.recurso VALUES (477, 'Jalapeño', 'Jalapeño', NULL, 'A very spicy ingredient—so spicy as to leave no room for ambivalence about it. You either like it or you don’t.', 'Un ingrediente muy picante, tan picante que no deja lugar a la ambivalencia al respecto. O te gusta o no te gusta.');
INSERT INTO public.recurso VALUES (478, 'Jam', 'Confitura', NULL, 'A condiment that’s very sweet and likewise very sour. Take care when adding it to sandwiches, as the sweet side can overwhelm.', 'Un condimento que es muy dulce y también muy ácido. Tenga cuidado al agregarlo a los sándwiches, ya que el lado dulce puede abrumar.');
INSERT INTO public.recurso VALUES (479, 'Jet Ball', 'Bola de chorro', 'CI06', NULL, NULL);
INSERT INTO public.recurso VALUES (480, 'Johto Slate', 'Lista de gestión', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Johto Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y el Johto Room en Ramanas Park.');
INSERT INTO public.recurso VALUES (481, 'Jolly Mint', 'Menta Alegre', 'CI03', 'Changes the Pokémon''s stats to match the Jolly nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Alegre.');
INSERT INTO public.recurso VALUES (482, 'Jubilife Muffin', 'Panecillo de Jubileo', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (483, 'Kangaskhanite', 'Kangaskhanitas', 'CI01', 'Enables Kangaskhan to Mega Evolve during battle.', 'Permite que Kangaskhan megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (484, 'Kanto Slate', 'Pizarra Kanto', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Kanto Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y la Sala Kanto en el Parque Ramanas.');
INSERT INTO public.recurso VALUES (485, 'Kasib Berry', 'Baya Kasib', 'CI04', 'Weakens a supereffective Ghost-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Fantasma contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (486, 'Kebia Berry', 'Baya de Kebia', 'CI04', 'Weakens a supereffective Poison-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Veneno contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (487, 'Kee Berry', 'Kee Berry', 'CI04', 'If held by a Pokémon, this Berry will increase the holder''s Defense if it''s hit with a physical move.', 'Si la sostiene un Pokémon, esta baya aumentará la defensa del poseedor si es golpeada con un movimiento físico.');
INSERT INTO public.recurso VALUES (488, 'Kelpsy Berry', 'Baya Kelpsia', 'CI04', 'Increases Friendship but lowers Attack EVs.', 'Aumenta la amistad pero reduce los EV de ataque.');
INSERT INTO public.recurso VALUES (489, 'Ketchup', 'Salsa de tomate', NULL, 'A condiment with very salty and tart flavor. While a number of other ingredients go into its signature flavor, the noble tomato is its heart and soul.', 'Un condimento de sabor muy salado y ácido. Mientras que una serie de otros ingredientes forman parte de su sabor característico, el noble tomate es su corazón y alma.');
INSERT INTO public.recurso VALUES (490, 'King’s Leaf', 'hoja del rey', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (491, 'King''s Rock', 'roca del rey', 'CI01', 'May cause opponent to flinch. Evolves Poliwhirl and Slowpoke when traded holding the item.', 'Puede hacer que el oponente se estremezca. Evoluciona a Poliwhirl y Slowpoke cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (492, 'Kiwi', 'kiwi', NULL, 'A very tart ingredient that has a light touch of sweetness as well. It goes well with rich ingredients.', 'Un ingrediente muy ácido que también tiene un ligero toque de dulzura. Va bien con ingredientes ricos.');
INSERT INTO public.recurso VALUES (493, 'Klawf Claw', 'Garra de Klawf', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (494, 'Klawf Stick', 'Palo Klawf', NULL, 'A very sweet and salty ingredient. It’s a nutritious processed food made with a concentrate derived from shed Klawf shells.', 'Un ingrediente muy dulce y salado. Es un alimento procesado nutritivo elaborado con un concentrado derivado de las conchas de Klawf mudadas.');
INSERT INTO public.recurso VALUES (495, 'Klefki Key', 'Llave Klefki', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (496, 'Kofu’s Wallet', 'Cartera de Kofu', NULL, 'A wallet that was left behind by Kofu, the Gym Leader at the Cascarrafa Gym. You’re to deliver it to him at the market in Porto Marinada.', 'Una billetera que dejó Kofu, el Líder de Gimnasio en el Gimnasio Cascarrafa. Debes entregárselo en el mercado de Porto Marinada.');
INSERT INTO public.recurso VALUES (497, 'Komala Claw', 'pero garra', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (498, 'Kommonium Z', 'Comunión Z', 'CI01', 'Allows Kommo-o to upgrade Clanging Scales to a Z-Move, Clangorous Soulblaze.', 'Permite a Kommo-o actualizar Clanging Scales a un Z-Move, Clangorous Soulblaze.');
INSERT INTO public.recurso VALUES (499, 'Koraidon’s Poké Ball', 'Pokébola de Koraidon', NULL, 'A Poké Ball that can hold the mysterious Pokémon known as Koraidon. A boy named Arven gave it to you.', 'Una Poké Ball que puede albergar al misterioso Pokémon conocido como Koraidon. Un chico llamado Arven te lo dio.');
INSERT INTO public.recurso VALUES (500, 'Kricketot Shell', 'Concha Kricketot', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (501, 'Lagging Tail', 'cola rezagada', 'CI01', 'Holder always attacks last.', 'El titular siempre ataca en último lugar.');
INSERT INTO public.recurso VALUES (502, 'Lansat Berry', 'Baya liberada', 'CI04', 'Increases critical-hit ratio when HP is low.', 'Aumenta la proporción de golpes críticos cuando HP es bajo.');
INSERT INTO public.recurso VALUES (503, 'Large Leek', 'puerro grande', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. Whether this is the kind of vegetable stalk that Farfetch’d like is unknown.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Se desconoce si este es el tipo de tallo vegetal que le gustaría a Farfetch.');
INSERT INTO public.recurso VALUES (504, 'Larvesta Fuzz', 'Larvesta pelusa', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (505, 'Larvitar Claw', 'Garra de Larvitar', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (506, 'Latiasite', 'latiasita', 'CI01', 'Enables Latias to Mega Evolve during battle.', 'Permite a Latias megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (507, 'Latiosite', 'latiosita', 'CI01', 'Enables Latios to Mega Evolve during battle.', 'Permite a Latios megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (508, 'Lava Cookie', 'galleta de lava', 'CI05', 'Heals all major status conditions.', 'Cura todas las principales condiciones de estado.');
INSERT INTO public.recurso VALUES (509, 'Lax Incense', 'Incienso Laxo', 'CI01', 'Lowers the opponent''s accuracy. Breeding Wobbuffet produces Wynaut when held.', 'Reduce la precisión del oponente. La cría de Wobbuffet produce Wynaut cuando se mantiene.');
INSERT INTO public.recurso VALUES (510, 'Lax Mint', 'Menta Floja', 'CI03', 'Changes the Pokémon''s stats to match the Lax nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Floja.');
INSERT INTO public.recurso VALUES (511, 'Leaden Ball', 'Bola de Plomo', 'CI06', NULL, NULL);
INSERT INTO public.recurso VALUES (512, 'Leader’s Crest', 'Cresta de líder', NULL, 'A shard of what appears to be an old blade of some sort. It is held only by Bisharp that head up a group of Pawniard.', 'Un fragmento de lo que parece ser una hoja vieja de algún tipo. Solo está en manos de Bisharp que encabezan un grupo de Pawniard.');
INSERT INTO public.recurso VALUES (513, 'Leaf Letter', 'Carta de la hoja', 'CI02', 'A letter written on a leaf. Something is written using Eevee''s footprints.', 'Una carta escrita en una hoja. Algo está escrito usando las huellas de Eevee.');
INSERT INTO public.recurso VALUES (514, 'Leaf Stone', 'Piedra hoja', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (515, 'Leafy Tablecloth', 'mantel frondoso', NULL, 'A botanically themed tablecloth featuring Grass-type Pokémon. Can you find the Pokémon that doesn’t quite fit in?', 'Un mantel de temática botánica con Pokémon de tipo Planta. ¿Puedes encontrar el Pokémon que no encaja del todo?');
INSERT INTO public.recurso VALUES (516, 'Lechonk Hair', 'Pelo Lechonk', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (517, 'Leek', 'Puerro', 'CI01', 'Increases critical-hit ratio when held by Farfetch''d.', 'Aumenta la proporción de golpes críticos cuando está en manos de Farfetch''d.');
INSERT INTO public.recurso VALUES (518, 'Leftovers', 'Sobras', 'CI01', 'An item to be held by a Pokémon. The holder''s HP is gradually restored during battle.', 'Un objeto para ser sostenido por un Pokémon. El HP del titular se restaura gradualmente durante la batalla.');
INSERT INTO public.recurso VALUES (519, 'Legend Plate', 'Placa de leyenda', 'CI01', NULL, NULL);
INSERT INTO public.recurso VALUES (520, 'Lemonade', 'Limonada', 'CI05', 'Restores 70 HP.', 'Restaura 70 HP.');
INSERT INTO public.recurso VALUES (521, 'Leppa Berry', 'Baya de lepa', 'CI04', 'If held by a Pokémon, it restores a move''s PP by 10.', 'Si está en manos de un Pokémon, restaura los PP de un movimiento en 10.');
INSERT INTO public.recurso VALUES (522, 'Lettuce', 'Lechuga', NULL, 'This bitter-tasting ingredient is simple and straightforward—just add it to all kinds of other ingredients for a delightfully crunchy time.', 'Este ingrediente de sabor amargo es simple y directo: solo agréguelo a todo tipo de otros ingredientes para obtener un momento deliciosamente crujiente.');
INSERT INTO public.recurso VALUES (523, 'Level Ball', 'Bola de Nivel', 'CI06', 'A Poké Ball for catching Pokémon that are a lower level than your own.', 'Una Poké Ball para capturar Pokémon de un nivel inferior al tuyo.');
INSERT INTO public.recurso VALUES (524, 'Liechi Berry', 'Baya de Liechi', 'CI04', 'Raises Attack when HP is low.', 'Aumenta el ataque cuando el HP es bajo.');
INSERT INTO public.recurso VALUES (525, 'Life Orb', 'Orbe de vida', 'CI01', 'Increases the power of moves, but loses HP each turn.', 'Aumenta el poder de los movimientos, pero pierde HP cada turno.');
INSERT INTO public.recurso VALUES (526, 'Light Ball', 'Bola liviana', 'CI01', 'An item to be held by PIKACHU. It is a puzzling orb that raises the Attack and Sp. Atk stat.', 'Un artículo para ser sostenido por PIKACHU. Es un orbe desconcertante que eleva el Ataque y la Sp. Estadística de atk.');
INSERT INTO public.recurso VALUES (527, 'Light Clay', 'Arcilla clara', 'CI01', 'A Pokémon held item that extends the duration of barrier moves like Light Screen and Reflect used by the holder.', 'Un objeto Pokémon que extiende la duración de los movimientos de barrera como Pantalla de Luz y Reflejo usados ​​por el poseedor.');
INSERT INTO public.recurso VALUES (528, 'Lilac Tablecloth', 'Mantel Lila', NULL, 'A light purple tablecloth. It’s smooth and pleasant to the touch, and dishes can be placed on it with hardly a sound.', 'Un mantel violeta claro. Es suave y agradable al tacto, y se pueden colocar platos sobre él sin apenas ruido.');
INSERT INTO public.recurso VALUES (529, 'Linking Cord', 'Cordón de enlace', 'CI02', 'A string exuding a mysterious energy that makes you feel a strange sense of connection. It’s loved by certain Pokémon.', 'Una cuerda que exuda una energía misteriosa que te hace sentir una extraña sensación de conexión. Es amado por ciertos Pokémon.');
INSERT INTO public.recurso VALUES (530, 'Litleo Tuft', 'Mechón de litleo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (531, 'Loaded Dice', 'Dado cargado', 'CI01', 'Makes multi-strike moves more likely to hit more times.', 'Hace que los movimientos de múltiples golpes tengan más probabilidades de golpear más veces.');
INSERT INTO public.recurso VALUES (532, 'Lone Earring', 'Pendiente solitario', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (533, 'Lonely Mint', 'menta solitaria', 'CI03', 'Changes the Pokémon''s stats to match the Lonely nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza solitaria.');
INSERT INTO public.recurso VALUES (534, 'Looker Ticket', 'Boleto de espectador', 'CI01', 'A ticket that was handmade by Looker. It''s decorated with a liberal amount of glittery paint.', 'Un billete hecho a mano por Looker. Está decorado con una generosa cantidad de pintura brillante.');
INSERT INTO public.recurso VALUES (535, 'Lopunnite', 'lopuntino', 'CI01', 'Enables Lopunny to Mega Evolve during battle.', 'Permite a Lopunny megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (536, 'Lost Satchel', 'Cartera perdida', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (537, 'Love Ball', 'Bola de Amor', 'CI06', 'Poké Ball for catching Pokémon that are the opposite gender of your Pokémon.', 'Poké Ball para capturar Pokémon del sexo opuesto al tuyo.');
INSERT INTO public.recurso VALUES (538, 'Love Sweet', 'Dulce Amor', 'CI01', 'Evolves Milcery into Heart Flavor Alcremie.', 'Evoluciona Milcery en Heart Flavor Alcremie.');
INSERT INTO public.recurso VALUES (539, 'Lucarionite', 'Lucarionita', 'CI01', 'Enables Lucario to Mega Evolve during battle.', 'Permite a Lucario Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (540, 'Luck Incense', 'Incienso de la suerte', 'CI01', 'Doubles prize money if held. Breeding Chansey or Blissey produces Happiny when held.', 'Se duplica el dinero del premio si se tiene. Criar Chansey o Blissey produce Happiny cuando se sostiene.');
INSERT INTO public.recurso VALUES (541, 'Lucky Egg', 'Huevo afortunado', 'CI01', 'An item to be held by a Pokémon. It is an egg filled with happiness that earns extra Exp. Points in battle.', 'Un objeto para ser sostenido por un Pokémon. Es un huevo lleno de felicidad que gana Exp extra. Puntos en batalla.');
INSERT INTO public.recurso VALUES (542, 'Lucky Punch', 'Golpe de suerte', 'CI01', 'Increases critical-hit ratio when held by Chansey.', 'Aumenta la proporción de golpes críticos cuando lo sostiene Chansey.');
INSERT INTO public.recurso VALUES (543, 'Lum Berry', 'Baya Lum', 'CI04', 'If held by a Pokémon, it recovers from any status problem.', 'Si lo sostiene un Pokémon, se recupera de cualquier problema de estado.');
INSERT INTO public.recurso VALUES (544, 'Luminous Moss', 'musgo luminoso', 'CI01', 'Raises Special Defense if hit by a Water-type move.', 'Aumenta la defensa especial si es golpeado por un movimiento de tipo agua.');
INSERT INTO public.recurso VALUES (545, 'Lumiose Galette', 'Pastel Lumiosa', 'CI05', 'Heals all major status conditions.', 'Cura todas las principales condiciones de estado.');
INSERT INTO public.recurso VALUES (546, 'Lunalium Z', 'Lunalio Z', 'CI01', 'Allows Lunala to upgrade Moongeist Beam to a Z-Move, Menacing Moonraze Maelstrom.', 'Permite a Lunala actualizar Moongeist Beam a Z-Move, Menacing Moonraze Maelstrom.');
INSERT INTO public.recurso VALUES (547, 'Lure', 'Señuelo', 'CI02', 'Attracts Pokémon in the wild.', 'Atrae Pokémon en estado salvaje.');
INSERT INTO public.recurso VALUES (548, 'Lure Ball', 'bola Anzuelo', 'CI06', 'A Poké Ball for catching Pokémon hooked by a Rod when fishing.', 'Una Poké Ball para atrapar Pokémon enganchados con una Caña al pescar.');
INSERT INTO public.recurso VALUES (549, 'Lustrous Globe', 'Globo brillante', 'CI01', NULL, NULL);
INSERT INTO public.recurso VALUES (550, 'Lustrous Orb', 'Orbe lustroso', 'CI01', 'Increases the power of Dragon- and Water-type moves when held by Palkia.', 'Aumenta el poder de los movimientos de tipo Dragón y Agua cuando Palkia lo sostiene.');
INSERT INTO public.recurso VALUES (551, 'Luvdisc Scales', 'Balanzas Luvdisc', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (552, 'Luxury Ball', 'Bola de Lujo', 'CI06', 'A comfortable Poké Ball that makes a caught wild Pokémon quickly grow friendly.', 'Una cómoda Poké Ball que hace que un Pokémon salvaje atrapado se vuelva amistoso rápidamente.');
INSERT INTO public.recurso VALUES (553, 'Lycanium Z', 'Licanio Z', 'CI01', 'Allows Lycanroc to upgrade Stone Edge to a Z-Move, Splintered Stormshards.', 'Permite a Lycanroc actualizar Stone Edge a un Z-Move, Splintered Stormshards.');
INSERT INTO public.recurso VALUES (554, 'Macho Brace', 'Macho Brace', 'CI01', 'An item to be held by a Pokémon. It is a stiff and heavy brace that promotes strong growth but lowers Speed.', 'Un objeto para ser sostenido por un Pokémon. Es un aparato ortopédico rígido y pesado que promueve un fuerte crecimiento pero reduce la velocidad.');
INSERT INTO public.recurso VALUES (555, 'Magical Heart Pick', 'Pico de corazón mágico', NULL, 'A pick shaped after a magic wand. Perhaps the real magic is the food maker’s wish for a delicious dish.', 'Un pico con forma de varita mágica. Quizás la verdadera magia es el deseo del fabricante de alimentos por un plato delicioso.');
INSERT INTO public.recurso VALUES (556, 'Magical Star Pick', 'Pico de estrella mágica', NULL, 'A pick shaped after a magic wand. Perhaps the real magic is the food maker’s wish for a delicious dish.', 'Un pico con forma de varita mágica. Quizás la verdadera magia es el deseo del fabricante de alimentos por un plato delicioso.');
INSERT INTO public.recurso VALUES (557, 'Magikarp Scales', 'Escamas Magikarp', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (558, 'Magmarizer', 'magmarizador', 'CI02', 'Evolves Magmar when traded holding the item.', 'Evoluciona a Magmar cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (559, 'Magnemite Screw', 'Tornillo Magnemita', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (560, 'Magnet', 'Imán', 'CI01', 'Increases the power of Electric-type moves.', 'Aumenta la potencia de los movimientos de tipo eléctrico.');
INSERT INTO public.recurso VALUES (561, 'Mago Berry', 'Baya de mago', 'CI04', 'Restores HP if it''s low, but may cause confusion.', 'Restaura HP si es bajo, pero puede causar confusión.');
INSERT INTO public.recurso VALUES (562, 'Magost Berry', 'Baya de Magost', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (563, 'Makuhita Sweat', 'sudor makuhita', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (564, 'Malicious Armor', 'Armadura maliciosa', 'CI02', 'Evolves Charcadet into Ceruledge.', 'Evoluciona a Charcadet en Ceruledge.');
INSERT INTO public.recurso VALUES (565, 'Manectite', 'puños', 'CI01', 'Enables Manectric to Mega Evolve during battle.', 'Permite a Manectric megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (566, 'Mankey Fur', 'piel de mankey', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (567, 'Maranga Berry', 'baya rosa', 'CI04', 'If held by a Pokémon, this Berry will increase the holder''s Sp. Def if it''s hit with a special move.', 'Si está en manos de un Pokémon, esta baya aumentará la Sp del poseedor. Def si es golpeado con un movimiento especial.');
INSERT INTO public.recurso VALUES (568, 'Marble', 'Mármol', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (569, 'Mareanie Spike', 'espiga mareanie', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (570, 'Mareep Wool', 'Lana Mareep', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (571, 'Marill Ball', 'bola marill', NULL, 'A Marill-themed ball. It’s soft and springy. Make sure you haven’t mistaken a real Marill for this ball before throwing.', 'Un baile con el tema de Marill. Es suave y elástico. Asegúrate de no haber confundido una Marill real con esta pelota antes de lanzarla.');
INSERT INTO public.recurso VALUES (572, 'Marmalade', 'Mermelada', NULL, 'A condiment with sour and bitter notes. It’s surprisingly useful, as it makes a nice counterpoint to oilier foods.', 'Un condimento con notas ácidas y amargas. Es sorprendentemente útil, ya que hace un buen contrapunto a los alimentos más grasos.');
INSERT INTO public.recurso VALUES (573, 'Marsh Balm', 'bálsamo de pantano', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (574, 'Marshadium Z', 'Marshadium Z', 'CI01', 'Allows Marshadow to upgrade Spectral Thief to a Z-Move, Soul-Stealing 7-Star Strike.', 'Permite a Marshadow actualizar Spectral Thief a un Z-Move, Soul-Stealing 7-Star Strike.');
INSERT INTO public.recurso VALUES (575, 'Maschiff Fang', 'Colmillo Maschiff', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (576, 'Master Ball', 'Bola Maestra', 'CI06', 'The best Ball with the ultimate level of performance. It will catch any wild Pokémon without fail.', 'La mejor pelota con el máximo nivel de rendimiento. Atrapa a cualquier Pokémon salvaje sin falta.');
INSERT INTO public.recurso VALUES (577, 'Mawilite', 'Vamos', 'CI01', 'Enables Mawile to Mega Evolve during battle.', 'Permite a Mawile megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (578, 'Max Elixir', 'Max Elixir', 'CI05', 'It fully restores the PP of all the moves learned by the targeted Pokémon.', 'Restaura completamente el PP de todos los movimientos aprendidos por el Pokémon objetivo.');
INSERT INTO public.recurso VALUES (579, 'Max Ether', 'Éter máximo', 'CI05', 'It fully restores the PP of a single selected move that has been learned by the target Pokémon.', 'Restaura completamente el PP de un solo movimiento seleccionado que ha sido aprendido por el Pokémon objetivo.');
INSERT INTO public.recurso VALUES (580, 'Max Honey', 'Max miel', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (581, 'Max Lure', 'señuelo máximo', 'CI02', 'Attracts Pokémon in the wild.', 'Atrae Pokémon en estado salvaje.');
INSERT INTO public.recurso VALUES (582, 'Max Mushrooms', 'Champiñones máximos', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (583, 'Max Potion', 'pocion maxima', 'CI05', 'Fully restores HP.', 'Restaura completamente HP.');
INSERT INTO public.recurso VALUES (584, 'Max Repel', 'Rechazo máximo', 'CI02', 'An item that prevents weak wild Pokémon from appearing for 250 steps after its use.', 'Un elemento que evita que aparezcan Pokémon salvajes débiles durante 250 pasos después de su uso.');
INSERT INTO public.recurso VALUES (585, 'Max Revive', 'máximo revivir', 'CI05', 'A medicine that revives a fainted Pokémon. It fully restores the Pokémon''s HP.', 'Una medicina que revive a un Pokémon desmayado. Restaura completamente el HP del Pokémon.');
INSERT INTO public.recurso VALUES (586, 'Mayonnaise', 'Mayonesa', NULL, 'A condiment that packs a very tart punch yet pairs well with various ingredients.', 'Un condimento que contiene un golpe muy ácido pero que combina bien con varios ingredientes.');
INSERT INTO public.recurso VALUES (587, 'Meadow Plate', 'Plato de pradera', 'CI01', 'Increases power of Grass-type moves. Changes Arceus'' type to Grass.', 'Aumenta el poder de los movimientos tipo hierba. Cambia el tipo de Arceus a Hierba.');
INSERT INTO public.recurso VALUES (588, 'Medichamite', 'medicamita', 'CI01', 'Enables Medicham to Mega Evolve during battle.', 'Permite que Medicham megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (589, 'Medicinal Leek', 'Puerro Medicinal', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (590, 'Meditite Sweat', 'sudor meditativo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (591, 'Mental Herb', 'Hierba mental', 'CI01', 'An item to be held by a Pokémon. It snaps the holder out of infatuation. It can be used only once.', 'Un objeto para ser sostenido por un Pokémon. Saca al titular del enamoramiento. Se puede usar una sola vez.');
INSERT INTO public.recurso VALUES (592, 'Meowth Fur', 'Piel de maullido', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (593, 'Metagrossite', 'Metagrosita', 'CI01', 'Enables Metagross to Mega Evolve during battle.', 'Permite a Metagross megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (594, 'Metal Coat', 'Capa de metal', 'CI01', 'Increases the power of Steel-type moves. Evolves Onix and Scyther when traded holding the item.', 'Aumenta el poder de los movimientos de tipo Acero. Evoluciona a Onix y Scyther cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (595, 'Metal Powder', 'polvo metalico', 'CI01', 'Increases Defense when held by Ditto.', 'Aumenta la defensa cuando lo sostiene Ditto.');
INSERT INTO public.recurso VALUES (596, 'Metronome', 'Metrónomo', 'CI01', 'Increases the power of moves used consecutively.', 'Aumenta el poder de los movimientos usados ​​consecutivamente.');
INSERT INTO public.recurso VALUES (597, 'Mewnium Z', 'Mewnio Z', 'CI01', 'Allows Mew to upgrade Psychic to a Z-Move, Genesis Supernova.', 'Le permite a Mew actualizar Psychic a un Z-Move, Genesis Supernova.');
INSERT INTO public.recurso VALUES (598, 'Mewtwonite X', 'Mewtwonita X', 'CI01', 'Enables Mewtwo to Mega Evolve during battle.', 'Permite a Mewtwo Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (599, 'Mewtwonite Y', 'Mewtwonita Y', 'CI01', 'Enables Mewtwo to Mega Evolve during battle.', 'Permite a Mewtwo Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (600, 'Micle Berry', 'Micle Berry', 'CI04', 'Increases a move''s accuracy when HP is low.', 'Aumenta la precisión de un movimiento cuando HP es bajo.');
INSERT INTO public.recurso VALUES (601, 'Mighty Candy', 'caramelo poderoso', 'CI05', 'Increases a Pokémon''s Attack stat by 1.', 'Aumenta la estadística de ataque de un Pokémon en 1.');
INSERT INTO public.recurso VALUES (602, 'Mighty Candy L', 'Poderoso Caramelo L', 'CI05', 'Increases a Pokémon''s Attack stat.', 'Aumenta la estadística de ataque de un Pokémon.');
INSERT INTO public.recurso VALUES (603, 'Mighty Candy XL', 'Caramelo Poderoso XL', 'CI05', 'Increases a Pokémon''s Attack stat.', 'Aumenta la estadística de ataque de un Pokémon.');
INSERT INTO public.recurso VALUES (604, 'Mild Mint', 'Menta Afable', 'CI03', 'Changes the Pokémon''s stats to match the Mild nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Afable.');
INSERT INTO public.recurso VALUES (605, 'Mimikium Z', 'Mimikium Z', 'CI01', 'Allows Mimikyu to upgrade Play Rough to a Z-Move, Let''s Snuggle Forever.', 'Permite a Mimikyu actualizar Play Rough a Z-Move, Let''s Snuggle Forever.');
INSERT INTO public.recurso VALUES (606, 'Mimikyu Scrap', 'Chatarra de Mimikyu', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (607, 'Mind Plate', 'Placa mental', 'CI01', 'Increases power of Psychic-type moves. Changes Arceus'' type to Psychic.', 'Aumenta el poder de los movimientos de tipo psíquico. Cambia el tipo de Arceus a Psíquico.');
INSERT INTO public.recurso VALUES (608, 'Mint Tablecloth', 'mantel menta', NULL, 'A light mint-colored tablecloth. It’s smooth and pleasant to the touch, and dishes can be placed on it with hardly a sound.', 'Un mantel de color menta claro. Es suave y agradable al tacto, y se pueden colocar platos sobre él sin apenas ruido.');
INSERT INTO public.recurso VALUES (609, 'Miracle Seed', 'Semilla milagrosa', 'CI01', 'Increases the power of Grass-type moves.', 'Aumenta el poder de los movimientos de tipo Hierba.');
INSERT INTO public.recurso VALUES (610, 'Miraidon’s Poké Ball', 'Pokébola de Miraidon', NULL, 'A Poké Ball that can hold the mysterious Pokémon known as Miraidon. A boy named Arven gave it to you.', 'Una Poké Ball que puede albergar al misterioso Pokémon conocido como Miraidon. Un chico llamado Arven te lo dio.');
INSERT INTO public.recurso VALUES (611, 'Mirror Herb', 'Hierba espejo', 'CI01', 'Copies an opponent''s stat increases when consumed.', 'Copia los aumentos de estadísticas de un oponente cuando se consume.');
INSERT INTO public.recurso VALUES (612, 'Misdreavus Tears', 'Lágrimas de Misdreavus', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (613, 'Misty Seed', 'Semilla brumosa', 'CI01', 'An item to be held by a Pokémon. It boosts Sp. Def on Misty Terrain. It can only be used once.', 'Un objeto para ser sostenido por un Pokémon. Potencia la Sp. Def en Misty Terrain. Solo se puede usar una vez.');
INSERT INTO public.recurso VALUES (614, 'Mixed Mushrooms', 'Setas mixtas', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. The chewy texture of the mushrooms transforms any dish they’re added to.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. La textura masticable de los champiñones transforma cualquier plato al que se agreguen.');
INSERT INTO public.recurso VALUES (615, 'Modest Mint', 'Menta modesta', 'CI03', 'Changes the Pokémon''s stats to match the Modest nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Modesta.');
INSERT INTO public.recurso VALUES (616, 'Monstrous Tablecloth', 'Mantel monstruoso', NULL, 'A tablecloth designed by the Pewter Museum of Science. The academic air of the pattern is a big hit with kids and adults alike.', 'Un mantel diseñado por el Pewter Museum of Science. El aire académico del patrón es un gran éxito entre niños y adultos por igual.');
INSERT INTO public.recurso VALUES (617, 'Moomoo Cheese', 'Queso Moomoo', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. Melted cheese can really give a curry some richness.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. El queso derretido realmente puede darle algo de riqueza al curry.');
INSERT INTO public.recurso VALUES (618, 'Moomoo Milk', 'Leche Moomoo', 'CI05', 'Milk with a very high nutrition content. It restores the HP of one Pokémon by 100 points.', 'Leche con un contenido nutricional muy alto. Restaura el HP de un Pokémon por 100 puntos.');
INSERT INTO public.recurso VALUES (619, 'Moon Ball', 'Bola Luna', 'CI06', 'A Poké Ball for catching Pokémon that evolve using the Moon Stone.', 'Una Poké Ball para capturar Pokémon que evolucionan con la Piedra Luna.');
INSERT INTO public.recurso VALUES (620, 'Moon Stone', 'Piedra Lunar', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (621, 'Mudbray Mud', 'Barro Mudbray', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (622, 'Murkrow Bauble', 'Adorno Murkrow', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (623, 'Muscle Band', 'Banda muscular', 'CI01', 'Increases the power of Physical-category moves.', 'Aumenta el poder de los movimientos de categoría física.');
INSERT INTO public.recurso VALUES (624, 'Muscle Wing', 'Ala musculosa', 'CI05', 'Increases Attack EVs by 1.', 'Aumenta los EV de ataque en 1.');
INSERT INTO public.recurso VALUES (625, 'Mushroom Cake', 'Pastel De Champiñones', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (626, 'Mustard', 'Mostaza', NULL, 'A very spicy condiment that’s indispensable when bread is on the table. It pairs tremendously with ketchup.', 'Un condimento muy picante que es indispensable cuando hay pan en la mesa. Combina tremendamente con el ketchup.');
INSERT INTO public.recurso VALUES (627, 'Mysterious Shard L', 'Fragmento misterioso L', NULL, 'A large shard that emanates an enigmatic power. Inside the shard, you can see a pattern that looks like Ramanas roses.', 'Un gran fragmento que emana un poder enigmático. Dentro del fragmento, puedes ver un patrón que se parece a las rosas de Ramanas.');
INSERT INTO public.recurso VALUES (628, 'Mysterious Shard S', 'Fragmento misterioso S', NULL, 'A small shard that emanates an enigmatic power. Inside the shard, you can see a pattern that looks like Ramanas roses.', 'Un pequeño fragmento que emana un poder enigmático. Dentro del fragmento, puedes ver un patrón que se parece a las rosas de Ramanas.');
INSERT INTO public.recurso VALUES (629, 'Mystic Water', 'Agua mística', 'CI01', 'Increases the power of Water-type moves.', 'Aumenta el poder de los movimientos de tipo agua.');
INSERT INTO public.recurso VALUES (630, 'Nacli Salt', 'sal nacli', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (631, 'Naive Mint', 'Menta Ingenua', 'CI03', 'Changes the Pokémon''s stats to match the Naive nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Ingenua.');
INSERT INTO public.recurso VALUES (632, 'Nanab Berry', 'Baya Nanab', 'CI04', 'A Berry to be used in cooking. Calms a Pokémon in battle, in Let''s Go Pikachu/Eevee.', 'Una baya para ser utilizada en la cocina. Calma a un Pokémon en batalla, en Let''s Go Pikachu/Eevee.');
INSERT INTO public.recurso VALUES (633, 'Naughty Mint', 'Menta Pícara', 'CI03', 'Changes the Pokémon''s stats to match the Naughty nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Pícara.');
INSERT INTO public.recurso VALUES (634, 'Nest Ball', 'Bola Nido', 'CI06', 'A somewhat different Poké Ball that works especially well on weaker Pokémon in the wild.', 'Una Poké Ball algo diferente que funciona especialmente bien en Pokémon más débiles en estado salvaje.');
INSERT INTO public.recurso VALUES (635, 'Net Ball', 'Bola de Red', 'CI06', 'A somewhat different Poké Ball that works especially well on Water- and Bug-type Pokémon.', 'Una Poké Ball algo diferente que funciona especialmente bien en Pokémon de tipo Agua y Bicho.');
INSERT INTO public.recurso VALUES (636, 'Never-Melt Ice', 'Hielo que nunca se derrite', 'CI01', 'Increases the power of Ice-type moves.', 'Aumenta el poder de los movimientos tipo hielo.');
INSERT INTO public.recurso VALUES (637, 'Noibat Fur', 'Piel de Noibat', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (638, 'Nomel Berry', 'Baya Nomel', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (639, 'Noodles', 'Fideos', NULL, 'A nice salty ingredient. It’s unclear how well these boiled noodles will serve as a sandwich filling.', 'Un buen ingrediente salado. No está claro qué tan bien servirán estos fideos hervidos como relleno de sándwich.');
INSERT INTO public.recurso VALUES (640, 'Normal Gem', 'Gema normal', 'CI01', 'Increases the power of a Normal-type move only once.', 'Aumenta el poder de un movimiento de tipo Normal solo una vez.');
INSERT INTO public.recurso VALUES (641, 'Normal Tera Shard', 'Fragmento de Tera normal', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (642, 'Normalium Z', 'Normalium Z', 'CI01', 'Allows the use of Breakneck Blitz, the Normal type Z-Move.', 'Permite el uso de Breakneck Blitz, el Z-Move de tipo Normal.');
INSERT INTO public.recurso VALUES (643, 'Nugget', 'Pepita', 'CI02', 'A nugget of pure gold that gives off a lustrous gleam. It can be sold at a high price to shops.', 'Una pepita de oro puro que desprende un brillo lustroso. Se puede vender a un precio alto en las tiendas.');
INSERT INTO public.recurso VALUES (644, 'Numel Lava', 'Nombre Lava', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (645, 'Nymble Claw', 'Garra Nymble', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (646, 'Occa Berry', 'Baya de Oca', 'CI04', 'Weakens a supereffective Fire-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Fuego contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (647, 'Oceanic Slate', 'Pizarra Oceánica', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Oceanic Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y el Oceanic Room en Ramanas Park.');
INSERT INTO public.recurso VALUES (648, 'Odd Incense', 'Incienso impar', 'CI01', 'Increases the power of Psychic-type moves. Breeding Mr. Mime produces Mime Jr. when held.', 'Aumenta el poder de los movimientos de tipo psíquico. Criar a Mr. Mime produce a Mime Jr. cuando se sostiene.');
INSERT INTO public.recurso VALUES (649, 'Odd Keystone', 'Piedra angular impar', 'CI02', 'A vital item that is needed to keep a stone tower from collapsing. Voices can be heard from it occasionally.', 'Un elemento vital que se necesita para evitar que una torre de piedra se derrumbe. De vez en cuando se pueden escuchar voces.');
INSERT INTO public.recurso VALUES (650, 'Old Amber', 'Viejo ámbar', 'CI02', 'A piece of amber that contains the genetic material of an ancient Pokémon. It is clear with a reddish tint.', 'Una pieza de ámbar que contiene el material genético de un antiguo Pokémon. Es transparente con un tinte rojizo.');
INSERT INTO public.recurso VALUES (651, 'Old Gateau', 'Viejo pastel', 'CI05', 'Heals all major status conditions.', 'Cura todas las principales condiciones de estado.');
INSERT INTO public.recurso VALUES (652, 'Olive Oil', 'Aceite de oliva', NULL, 'A condiment offering faint notes of sour and bitter flavors. The most prized varieties are the ones Smoliv love the smell of—such oils’ quality is assured.', 'Un condimento que ofrece ligeras notas de sabores agrios y amargos. Las variedades más preciadas son aquellas cuyo olor le encanta a Smoliv: la calidad de estos aceites está asegurada.');
INSERT INTO public.recurso VALUES (653, 'Onion', 'Cebolla', NULL, 'This spicy veggie is indispensable to many sandwiches. It goes well with rich ingredients.', 'Esta verdura picante es indispensable para muchos sándwiches. Va bien con ingredientes ricos.');
INSERT INTO public.recurso VALUES (654, 'Oran Berry', 'Baya de Orán', 'CI04', 'If held by a Pokémon, it heals the user by just 10 HP.', 'Si lo sostiene un Pokémon, cura al usuario en solo 10 HP.');
INSERT INTO public.recurso VALUES (655, 'Orange Dish', 'plato naranja', NULL, 'A dish for picnics. Comes in plenty of colors to choose from based on the food or the mood. The orange variety is the most popular of all.', 'Un plato para picnics. Viene en muchos colores para elegir según la comida o el estado de ánimo. La variedad naranja es la más popular de todas.');
INSERT INTO public.recurso VALUES (656, 'Oranguru Fur', 'Piel de oranguru', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (657, 'Oricorio Feather', 'Pluma de oricorio', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (658, 'Origin Ball', 'Bola de origen', 'CI06', NULL, NULL);
INSERT INTO public.recurso VALUES (659, 'Origin Ore', 'Mineral de origen', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (660, 'Orthworm Tarnish', 'Deslustre de orthworm', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (661, 'Oval Charm', 'Dije ovalado', 'CI02', 'An oval charm said to increase the chance of Pokémon Eggs being found at the Day Care.', 'Un amuleto ovalado que se dice que aumenta la posibilidad de que se encuentren Huevos Pokémon en la Guardería.');
INSERT INTO public.recurso VALUES (662, 'Oval Stone', 'Piedra ovalada', 'CI02', 'Evolves Happiny when held.', 'Evoluciona Happiny cuando se sostiene.');
INSERT INTO public.recurso VALUES (663, 'Pachirisu Fur', 'Piel de pachirisu', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (664, 'Pack of Potatoes', 'Paquete de Patatas', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. Potatoes help mellow out a spicy taste, to make a dish more mild.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Las patatas ayudan a suavizar el sabor picante, para hacer un plato más suave.');
INSERT INTO public.recurso VALUES (665, 'Packaged Curry', 'curry envasado', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. Using packaged curry helps make sure there are no slipups when cooking.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. El uso de curry envasado ayuda a garantizar que no haya errores al cocinar.');
INSERT INTO public.recurso VALUES (666, 'Pamtre Berry', 'Baya de Pamtre', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (667, 'Paralyze Heal', 'Paralizar Curar', 'CI05', 'A spray-type medicine. It eliminates paralysis from a single Pokémon.', 'Un medicamento tipo spray. Elimina la parálisis de un solo Pokémon.');
INSERT INTO public.recurso VALUES (668, 'Parasol Pick', 'Púa de sombrilla', NULL, 'Some complain that the parasol part of this pick is hard to hold on to, so your fingers get messy. Still, it’s fun to twirl this all around after you’ve eaten.', 'Algunos se quejan de que la parte de la sombrilla de esta púa es difícil de sujetar, por lo que los dedos se ensucian. Aún así, es divertido girar todo esto después de haber comido.');
INSERT INTO public.recurso VALUES (669, 'Park Ball', 'Bola de Parque', 'CI06', 'A special Poké Ball for the Pal Park.', 'Una Poké Ball especial para Pal Park.');
INSERT INTO public.recurso VALUES (670, 'Party Sparkler Pick', 'Púa de bengala de fiesta', NULL, 'This pick features a small sparkler that goes off automatically. It’s used at parties or for guests of honor. It leaves an oddly appealing aroma once it’s burned out.', 'Esta púa cuenta con una pequeña bengala que se apaga automáticamente. Se utiliza en fiestas o para invitados de honor. Deja un aroma extrañamente atractivo una vez que se quema.');
INSERT INTO public.recurso VALUES (671, 'Pass Orb', 'Pasar orbe', 'CI01', 'A mysterious orb containing the power of the Unova region, to be used when generating Pass Power.', 'Un orbe misterioso que contiene el poder de la región de Teselia, para ser usado al generar Pass Power.');
INSERT INTO public.recurso VALUES (672, 'Passho Berry', 'Baya Passho', 'CI04', 'Weakens a supereffective Water-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo agua contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (673, 'Passimian Fur', 'Piel de Passimian', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (674, 'Pasta', 'Pasta', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. These flour noodles make for a surprisingly good match with curry.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Estos fideos de harina combinan sorprendentemente bien con el curry.');
INSERT INTO public.recurso VALUES (675, 'Pawmi Fur', 'Piel de Pawmi', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (676, 'Pawniard Blade', 'Hoja de empeño', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (677, 'Payapa Berry', 'Paz fuera Berry', 'CI04', 'Weakens a supereffective Psychic-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Psíquico contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (678, 'Peach Tablecloth', 'Mantel de melocotón', NULL, 'A light peach-colored tablecloth. It’s smooth and pleasant to the touch, and dishes can be placed on it with hardly a sound.', 'Un mantel de color melocotón claro. Es suave y agradable al tacto, y se pueden colocar platos sobre él sin apenas ruido.');
INSERT INTO public.recurso VALUES (679, 'Peanut Butter', 'Mantequilla de maní', NULL, 'A very sweet condiment. People in Paldea seem to favor the sweet varieties over the unsweetened.', 'Un condimento muy dulce. La gente de Paldea parece preferir las variedades dulces a las sin azúcar.');
INSERT INTO public.recurso VALUES (680, 'Pearl', 'Perla', 'CI02', 'A somewhat-small pearl that sparkles in a pretty silver color. It can be sold cheaply to shops.', 'Una perla algo pequeña que brilla en un bonito color plateado. Se puede vender barato a las tiendas.');
INSERT INTO public.recurso VALUES (681, 'Pearl String', 'Cadena de perlas', 'CI02', 'Very large pearls that sparkle in a pretty silver color. A maniac will buy them for a high price.', 'Perlas muy grandes que brillan en un bonito color plateado. Un maníaco los comprará por un alto precio.');
INSERT INTO public.recurso VALUES (682, 'Peat Block', 'bloque de turba', 'CI02', 'A block of muddy material that can be used as fuel for burning when it is dried. It’s loved by a certain Pokémon.', 'Un bloque de material fangoso que puede usarse como combustible para quemar cuando se seca. Es amado por cierto Pokémon.');
INSERT INTO public.recurso VALUES (683, 'Pecha Berry', 'Baya Pecha', 'CI04', 'If held by a Pokémon, it recovers from poison.', 'Si lo sostiene un Pokémon, se recupera del veneno.');
INSERT INTO public.recurso VALUES (684, 'Pep-Up Plant', 'Planta estimulante', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (685, 'Pepper', 'Pimienta', NULL, 'A seasoning packing very spicy flavor. It goes nicely with oilier foods and works especially well when you add just a pinch for a hint of flavor.', 'Un condimento de embalaje de sabor muy picante. Combina muy bien con alimentos más grasos y funciona especialmente bien cuando agrega solo una pizca para darle un toque de sabor.');
INSERT INTO public.recurso VALUES (686, 'Permit', 'Permiso', 'CI02', 'A permit that is needed to enter the Nature Preserve. Not many know about it.', 'Un permiso que se necesita para ingresar a la Reserva Natural. No muchos lo saben.');
INSERT INTO public.recurso VALUES (687, 'Persim Berry', 'Baya de caqui', 'CI04', 'If held by a Pokémon, it recovers from confusion.', 'Si lo sostiene un Pokémon, se recupera de la confusión.');
INSERT INTO public.recurso VALUES (688, 'Petaya Berry', 'Baya de petaya', 'CI04', 'Raises Special Attack when HP is low.', 'Aumenta el ataque especial cuando HP es bajo.');
INSERT INTO public.recurso VALUES (689, 'Petilil Leaf', 'Hoja de petilil', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (690, 'Pewter Crunchies', 'Crujientes de peltre', 'CI05', 'Heals all major status conditions.', 'Cura todas las principales condiciones de estado.');
INSERT INTO public.recurso VALUES (691, 'Phanpy Nail', 'Uñas Fantásticas', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (692, 'Pichu Fur', 'Piel de Pichu', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (693, 'Pickle', 'Pepinillo', NULL, 'This very sour ingredient is made by pickling veggies in a flavorful brine made from spices and vinegar.', 'Este ingrediente muy ácido se prepara encurtiendo verduras en una salmuera sabrosa hecha de especias y vinagre.');
INSERT INTO public.recurso VALUES (694, 'Picnic Set', 'juego de pícnic', NULL, 'A roomy basket packed with all sorts of things for use when enjoying picnicking with your Pokémon.', 'Una canasta espaciosa repleta de todo tipo de cosas para usar cuando disfrutas de un picnic con tus Pokémon.');
INSERT INTO public.recurso VALUES (695, 'Pidgeotite', 'Pidgeotita', 'CI01', 'Enables Pidgeot to Mega Evolve during battle.', 'Permite a Pidgeot megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (696, 'Pika-Pika Pick', 'Púa Pika-Pika', NULL, 'A Pick-achu, as it were, sporting Pikachu’s usual expression. It’s easy to grab by the ears, which is part of why it’s so popular.', 'Un Pick-achu, por así decirlo, luciendo la expresión habitual de Pikachu. Es fácil de agarrar por las orejas, lo cual es parte de por qué es tan popular.');
INSERT INTO public.recurso VALUES (697, 'Pikachu Cup', 'Copa Pikachu', NULL, 'A cup for big-time Pokémon fans. Kids will happily drink out of it, making it a boon to parents.', 'Una taza para los grandes fanáticos de Pokémon. Los niños beberán felizmente, lo que lo convierte en una bendición para los padres.');
INSERT INTO public.recurso VALUES (698, 'Pikanium Z', 'Picanio Z', 'CI01', 'Allows Pikachu to upgrade Volt Tackle to a Z-Move, Catastropika.', 'Permite a Pikachu actualizar Volt Tackle a un Z-Move, Catastropika.');
INSERT INTO public.recurso VALUES (699, 'Pikashunium Z', 'Sr. Pikashunium', 'CI01', 'Allows Pikachu in a cap to upgrade Thunderbolt to a Z-Move, 10,000,000 Volt Thunderbolt.', 'Permite a Pikachu en un límite actualizar Thunderbolt a un Z-Move, 10,000,000 Volt Thunderbolt.');
INSERT INTO public.recurso VALUES (700, 'Pinap Berry', 'Baya de piña', 'CI04', 'A Berry to be used in cooking. Increases chances of getting items when a Pokémon is caught, in Pokémon Let''s Go.', 'Una baya para ser utilizada en la cocina. Aumenta las posibilidades de conseguir objetos cuando se atrapa un Pokémon, en Pokémon Let''s Go.');
INSERT INTO public.recurso VALUES (701, 'Pincurchin Spines', 'Espinas de Pincurchin', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (702, 'Pineapple', 'Piña', NULL, 'This very tart ingredient is a fruit of southern lands, and its color and texture are a thrill. It’s been cut into chunks to be easily manageable.', 'Este ingrediente muy ácido es un fruto de las tierras del sur, y su color y textura son una emoción. Se ha cortado en trozos para que sea fácil de manejar.');
INSERT INTO public.recurso VALUES (703, 'Pineco Husk', 'Recuerda Pineco', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (704, 'Pink Apricorn', 'albaricoque rosa', 'CI02', 'A pink Apricorn. It has a nice, sweet scent.', 'Un albaricoque rosa. Tiene un olor agradable y dulce.');
INSERT INTO public.recurso VALUES (705, 'Pink Bottle', 'botella rosa', NULL, 'A go-to bottle widely used for drinks at picnics. Its simple design and portability make it popular among all sorts of people.', 'Una botella de referencia muy utilizada para bebidas en picnics. Su diseño simple y portabilidad lo hacen popular entre todo tipo de personas.');
INSERT INTO public.recurso VALUES (706, 'Pink Cup', 'Copa rosa', NULL, 'A cup sold with the Pink Bottle. The two don’t stack, so they’re tough to pack—but they look good, so they’re popular with those who like to post picnic photos.', 'Una taza vendida con la botella rosa. Los dos no se apilan, por lo que son difíciles de empacar, pero se ven bien, por lo que son populares entre quienes les gusta publicar fotos de picnic.');
INSERT INTO public.recurso VALUES (707, 'Pink Nectar', 'néctar rosa', 'CI01', 'The flower nectar obtained at the flowering shrubs on Royal Avenue. It changes the form of certain species of Pokémon.', 'El néctar de flores obtenido en los arbustos en flor en Royal Avenue. Cambia la forma de ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (708, 'Pink Scarf', 'Pañuelo rosa', 'CI02', 'Raises holder''s Cute aspect in a Contest.', 'Aumenta el aspecto Lindo del poseedor en un Concurso.');
INSERT INTO public.recurso VALUES (709, 'Pink Tablecloth', 'Mantel Rosa', NULL, 'A simple pink tablecloth. It’s smooth and pleasant to the touch, and dishes can be placed on it with hardly a sound.', 'Un simple mantel rosa. Es suave y agradable al tacto, y se pueden colocar platos sobre él sin apenas ruido.');
INSERT INTO public.recurso VALUES (710, 'Pinsirite', 'tu pensaras', 'CI01', 'Enables Pinsir to Mega Evolve during battle.', 'Permite a Pinsir megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (711, 'Pixie Plate', 'Placa de duendecillo', 'CI01', 'Increases power of Fairy-type moves. Changes Arceus'' type to Fairy.', 'Aumenta el poder de los movimientos de tipo Hada. Cambia el tipo de Arceus a Hada.');
INSERT INTO public.recurso VALUES (712, 'Plaid Tablecloth (B)', 'Mantel a cuadros (B)', NULL, 'A sturdy tablecloth made of thick fabric. The gentle blue plaid gives a table a crisp look.', 'Un mantel resistente hecho de tela gruesa. La suave tela escocesa azul le da a la mesa un aspecto nítido.');
INSERT INTO public.recurso VALUES (713, 'Plaid Tablecloth (R)', 'Mantel a cuadros (R)', NULL, 'A sturdy tablecloth made of thick fabric. The quietly composed red plaid gives the table some flair.', 'Un mantel resistente hecho de tela gruesa. La tela escocesa roja tranquilamente compuesta le da a la mesa algo de estilo.');
INSERT INTO public.recurso VALUES (714, 'Plaid Tablecloth (Y)', 'Mantel a cuadros (Y)', NULL, 'A sturdy tablecloth made of thick fabric. The cheery yellow plaid brightens up a table.', 'Un mantel resistente hecho de tela gruesa. La alegre tela escocesa amarilla ilumina una mesa.');
INSERT INTO public.recurso VALUES (715, 'Plasma Card', 'Tarjeta Plasma', 'CI01', 'A card key needed to enter the password inside the Plasma Frigate.', 'Se necesita una clave de tarjeta para ingresar la contraseña dentro de la fragata de plasma.');
INSERT INTO public.recurso VALUES (716, 'Plume Fossil', 'Penacho fósil', 'CI02', 'A fossil of an ancient Pokémon that flew in the sky in ancient times. It appears to be part of its wing.', 'Un fósil de un antiguo Pokémon que volaba en el cielo en la antigüedad. Parece ser parte de su ala.');
INSERT INTO public.recurso VALUES (717, 'Plump Beans', 'Frijoles Regordetes', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (718, 'Poison Barb', 'lengüeta de veneno', 'CI01', 'Increases the power of Poison-type moves.', 'Aumenta el poder de los movimientos de tipo Veneno.');
INSERT INTO public.recurso VALUES (719, 'Poison Gem', 'Gema de veneno', 'CI01', 'Increases the power of a Poison-type move only once.', 'Aumenta el poder de un movimiento de tipo Veneno solo una vez.');
INSERT INTO public.recurso VALUES (720, 'Poison Memory', 'Memoria de veneno', 'CI01', 'Changes Silvally and its move Multi-Attack to Poison type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Veneno.');
INSERT INTO public.recurso VALUES (721, 'Poison Tera Shard', 'Fragmento de Tera Venenoso', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (722, 'Poisonium Z', 'Veneno Z', 'CI01', 'Allows the use of Acid Downpour, the Poison type Z-Move.', 'Permite el uso de Acid Downpour, el tipo de veneno Z-Move.');
INSERT INTO public.recurso VALUES (723, 'Poké Ball', 'Pokebola', 'CI06', 'A device for catching wild Pokémon. It is thrown like a ball at the target. It is designed as a capsule system.', 'Un dispositivo para atrapar Pokémon salvajes. Se lanza como una pelota al blanco. Está diseñado como un sistema de cápsulas.');
INSERT INTO public.recurso VALUES (724, 'Poké Doll', 'Pokemuñeca', 'CI02', 'A doll that attracts Pokémon. Use it to flee from any battle with a wild Pokémon.', 'Una muñeca que atrae Pokémon. Úsalo para huir de cualquier batalla con un Pokémon salvaje.');
INSERT INTO public.recurso VALUES (725, 'Poké Toy', 'Poké Juguete', 'CI02', 'An item that attracts Pokémon. Use it to flee from any battle with a wild Pokémon.', 'Un objeto que atrae Pokémon. Úsalo para huir de cualquier batalla con un Pokémon salvaje.');
INSERT INTO public.recurso VALUES (726, 'Polished Mud Ball', 'Bola de barro pulido', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (727, 'Polka-Dot Bottle', 'Botella de lunares', NULL, 'A polka-dot-patterned bottle that’s small, light, and even comes with a cup. The detachable strap makes it handy for walking around with.', 'Una botella con estampado de lunares que es pequeña, liviana e incluso viene con una taza. La correa desmontable lo hace útil para caminar.');
INSERT INTO public.recurso VALUES (728, 'Polka-Dot Cup', 'Copa de lunares', NULL, 'A cup for kids to use at picnics. It’s made of light but strong material. It’s stackable, which makes it handy for carrying around.', 'Una taza para que los niños la usen en los picnics. Está hecho de un material ligero pero resistente. Es apilable, lo que lo hace práctico para transportar.');
INSERT INTO public.recurso VALUES (729, 'Polka-Dot Tablecloth', 'Mantel de Lunares', NULL, 'A tablecloth with a fashionable polka-dot pattern. It’s great at repelling water and mold, and stains and smudges wipe right off.', 'Un mantel con un moderno estampado de lunares. Es excelente para repeler el agua y el moho, y las manchas y manchas se limpian de inmediato.');
INSERT INTO public.recurso VALUES (730, 'Pomeg Berry', 'Baya de pepita', 'CI04', 'Increases Friendship but lowers HP EVs.', 'Aumenta la amistad pero reduce los HP EV.');
INSERT INTO public.recurso VALUES (731, 'Pop Pod', 'Cápsula pop', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (732, 'Potato Salad', 'Ensalada de papas', NULL, 'This very tart ingredient—a soft salad that’s all about potatoes—pairs tremendously well with bread.', 'Este ingrediente muy agrio, una ensalada suave que tiene que ver con las papas, combina muy bien con el pan.');
INSERT INTO public.recurso VALUES (733, 'Potato Tortilla', 'tortilla de patata', NULL, 'A very salty ingredient and a popular dish in Paldea. It’s undeniably filling.', 'Un ingrediente muy salado y un plato popular en Paldea. Es innegablemente abundante.');
INSERT INTO public.recurso VALUES (734, 'Potion', 'Poción', 'CI05', 'Restores 20 HP.', 'Restaura 20 HP.');
INSERT INTO public.recurso VALUES (735, 'Power Anklet', 'Tobillera de poder', 'CI01', 'A Pokémon held item that promotes Speed gain on leveling, but reduces the Speed stat.', 'Un objeto de Pokémon que promueve la ganancia de velocidad al subir de nivel, pero reduce la estadística de velocidad.');
INSERT INTO public.recurso VALUES (736, 'Power Band', 'Banda de poder', 'CI01', 'A Pokémon held item that promotes Sp. Def gain on leveling, but reduces the Speed stat.', 'Un objeto Pokémon sostenido que promueve Sp. Ganancia de defensa al subir de nivel, pero reduce la estadística de velocidad.');
INSERT INTO public.recurso VALUES (737, 'Power Belt', 'cinturón de poder', 'CI01', 'A Pokémon held item that promotes Defense gain on leveling, but reduces the Speed stat.', 'Un objeto de Pokémon que promueve la ganancia de Defensa al subir de nivel, pero reduce la estadística de Velocidad.');
INSERT INTO public.recurso VALUES (738, 'Power Bracer', 'Brazal de poder', 'CI01', 'A Pokémon held item that promotes Attack gain on leveling, but reduces the Speed stat.', 'Un objeto de Pokémon que promueve la ganancia de Ataque al subir de nivel, pero reduce la estadística de Velocidad.');
INSERT INTO public.recurso VALUES (739, 'Power Herb', 'Hierba de poder', 'CI01', 'A single-use item to be held by a Pokémon. It allows the immediate use of a move that charges on the first turn.', 'Un artículo de un solo uso para ser sostenido por un Pokémon. Permite el uso inmediato de un movimiento que carga en el primer turno.');
INSERT INTO public.recurso VALUES (740, 'Power Lens', 'Lente de poder', 'CI01', 'A Pokémon held item that promotes Sp. Atk gain on leveling, but reduces the Speed stat.', 'Un objeto Pokémon sostenido que promueve Sp. El ATK se gana al subir de nivel, pero reduce la estadística de Velocidad.');
INSERT INTO public.recurso VALUES (741, 'Power Plant Pass', 'Pase de planta de energía', 'CI01', 'This pass serves as an ID card for gaining access to the power plant that lies along Route 13.', 'Este pase sirve como tarjeta de identificación para acceder a la planta de energía que se encuentra a lo largo de la ruta 13.');
INSERT INTO public.recurso VALUES (742, 'Power Weight', 'Peso de potencia', 'CI01', 'A Pokémon held item that promotes HP gain on leveling, but reduces the Speed stat.', 'Un objeto de Pokémon que promueve la ganancia de HP al subir de nivel, pero reduce la estadística de velocidad.');
INSERT INTO public.recurso VALUES (743, 'PP Max', 'PP máx.', 'CI05', 'It maximally raises the top PP of a selected move that has been learned by the target Pokémon.', 'Aumenta al máximo el PP superior de un movimiento seleccionado que ha sido aprendido por el Pokémon objetivo.');
INSERT INTO public.recurso VALUES (744, 'PP Up', 'PP arriba', 'CI05', 'It slightly raises the maximum PP of a selected move that has been learned by the target Pokémon.', 'Aumenta ligeramente el PP máximo de un movimiento seleccionado que ha sido aprendido por el Pokémon objetivo.');
INSERT INTO public.recurso VALUES (745, 'Precooked Burger', 'Hamburguesa Precocinada', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. If you’re unsure about what to cook, you can’t go wrong with some burger.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Si no está seguro de qué cocinar, no puede equivocarse con una hamburguesa.');
INSERT INTO public.recurso VALUES (746, 'Premier Ball', 'Bola de Honor', 'CI06', 'A somewhat rare Poké Ball that has been specially made to commemorate an event of some sort.', 'Una Pokébola algo rara que se ha creado especialmente para conmemorar un evento de algún tipo.');
INSERT INTO public.recurso VALUES (747, 'Pretty Wing', 'Bonito ala', 'CI02', 'Though this feather is beautiful, it''s just a regular feather and has no effect on Pokémon.', 'Aunque esta pluma es hermosa, es solo una pluma normal y no tiene efecto en Pokémon.');
INSERT INTO public.recurso VALUES (748, 'Primarium Z', 'Z primaria', 'CI01', 'Allows Primarina to upgrade Sparkling Aria to a Z-Move, Oceanic Operetta.', 'Permite a Primarina actualizar Sparkling Aria a un Z-Move, Oceanic Operetta.');
INSERT INTO public.recurso VALUES (749, 'Prism Scale', 'Escala de prisma', 'CI02', 'Evolves Feebas when traded holding the item.', 'Evoluciona a Feebas cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (750, 'Prison Bottle', 'Botella de prisión', 'CI01', 'Transforms Hoopa Confined to Hoopa Unbound.', 'Transforma a Hoopa confinada en Hoopa desatada.');
INSERT INTO public.recurso VALUES (751, 'Prof''s Letter', 'Carta del profesor', 'CI01', 'A letter that Professor Sycamore wrote to your mother. A faint but pleasant perfume seems to cling to the paper.', 'Una carta que el profesor Sycamore le escribió a tu madre. Un leve pero agradable perfume parece adherirse al papel.');
INSERT INTO public.recurso VALUES (752, 'Prosciutto', 'Jamón', NULL, 'This ingredient is very salty like regular ham, but the difference is prosciutto is not cooked after it is cured, giving it a fun freshness.', 'Este ingrediente es muy salado como el jamón normal, pero la diferencia es que el prosciutto no se cocina después de curarse, lo que le da una frescura divertida.');
INSERT INTO public.recurso VALUES (753, 'Protective Pads', 'Almohadillas protectoras', 'CI01', 'An item to be held by a Pokémon. These pads protect the holder from effects caused by making direct contact with the target.', 'Un objeto para ser sostenido por un Pokémon. Estas almohadillas protegen al portador de los efectos causados ​​por el contacto directo con el objetivo.');
INSERT INTO public.recurso VALUES (754, 'Protector', 'Protector', 'CI02', 'Evolves Rhydon when traded holding the item.', 'Evoluciona a Rhydon cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (755, 'Protein', 'Proteína', 'CI05', 'Increases Attack EVs by 10.', 'Aumenta los EV de ataque en 10.');
INSERT INTO public.recurso VALUES (756, 'Psychic Gem', 'Gema psíquica', 'CI01', 'Increases the power of a Psychic-type move only once.', 'Aumenta el poder de un movimiento de tipo psíquico solo una vez.');
INSERT INTO public.recurso VALUES (757, 'Psychic Memory', 'Memoria psíquica', 'CI01', 'Changes Silvally and its move Multi-Attack to Psychic type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Psíquico.');
INSERT INTO public.recurso VALUES (758, 'Psychic Seed', 'Semilla psíquica', 'CI01', 'An item to be held by a Pokémon. It boosts Sp. Def on Psychic Terrain. It can only be used once.', 'Un objeto para ser sostenido por un Pokémon. Potencia la Sp. Def en terreno psíquico. Solo se puede usar una vez.');
INSERT INTO public.recurso VALUES (759, 'Psychic Tera Shard', 'Fragmento de Tera psíquico', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (760, 'Psychium Z', 'Psiquio Z', 'CI01', 'Allows the use of Shattered Psyche, the Psychic type Z-Move.', 'Permite el uso de Shattered Psyche, el Z-Move de tipo psíquico.');
INSERT INTO public.recurso VALUES (761, 'Psyduck Down', 'Psyduck abajo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (762, 'Punching Glove', 'Guante de boxeo', NULL, 'An item to be held by a Pokémon. This protective glove boosts the power of the holder’s punching moves and prevents direct contact with targets.', 'Un objeto para ser sostenido por un Pokémon. Este guante protector aumenta la potencia de los golpes del portador y evita el contacto directo con los objetivos.');
INSERT INTO public.recurso VALUES (763, 'Pungent Root', 'Raíz picante', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. Though carelessly picked, these herbs can add a fragrant accent to a dish.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Aunque se recogieron con descuido, estas hierbas pueden agregar un acento fragante a un plato.');
INSERT INTO public.recurso VALUES (764, 'Pure Incense', 'Incienso Puro', 'CI01', 'Descreases the likelihood of meeting wild Pokémon. Breeding Chimecho produces Chingling when held.', 'Disminuye la probabilidad de encontrarse con Pokémon salvajes. Criar Chimecho produce Chingling cuando se sostiene.');
INSERT INTO public.recurso VALUES (765, 'Purple Nectar', 'néctar púrpura', 'CI01', 'A flower nectar obtained at Poni Meadow. It changes the form of certain species of Pokémon.', 'Un néctar de flores obtenido en Poni Meadow. Cambia la forma de ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (766, 'Qualot Berry', 'Baya Qualot', 'CI04', 'Increases Friendship but lowers Defense EVs.', 'Aumenta la amistad pero reduce los EV de defensa.');
INSERT INTO public.recurso VALUES (767, 'Quick Ball', 'Bola Rápida', 'CI06', 'A somewhat different Poké Ball that provides a better catch rate if it is used at the start of a wild encounter.', 'Una Pokébola algo diferente que proporciona una mejor tasa de captura si se usa al comienzo de un encuentro salvaje.');
INSERT INTO public.recurso VALUES (768, 'Quick Candy', 'Caramelo Rápido', 'CI05', 'Increases a Pokémon''s Speed stat by 1.', 'Aumenta la estadística de Velocidad de un Pokémon en 1.');
INSERT INTO public.recurso VALUES (769, 'Quick Candy L', 'Caramelo Rápido L', 'CI05', 'Increases a Pokémon''s Speed stat.', 'Aumenta la estadística de velocidad de un Pokémon.');
INSERT INTO public.recurso VALUES (770, 'Quick Candy XL', 'Quick Candy XL', 'CI05', 'Increases a Pokémon''s Speed stat.', 'Aumenta la estadística de velocidad de un Pokémon.');
INSERT INTO public.recurso VALUES (771, 'Quick Claw', 'Garra Rápida', 'CI01', 'An item to be held by a Pokémon. A light, sharp claw that lets the bearer move first occasionally.', 'Un objeto para ser sostenido por un Pokémon. Una garra ligera y afilada que permite que el portador se mueva primero de vez en cuando.');
INSERT INTO public.recurso VALUES (772, 'Quick Powder', 'Polvo Rápido', 'CI01', 'Increases Speed when held by Ditto.', 'Aumenta la velocidad cuando lo sostiene Ditto.');
INSERT INTO public.recurso VALUES (773, 'Quiet Mint', 'Menta Mansa', 'CI03', 'Changes the Pokémon''s stats to match the Quiet nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Mansa.');
INSERT INTO public.recurso VALUES (774, 'Qwilfish Spines', 'Espinas de Qwilfish', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (775, 'Rabuta Berry', 'Rabuta Berry', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (776, 'Rage Candy Bar', 'Barra de caramelo de rabia', 'CI05', 'Heals all major status conditions.', 'Cura todas las principales condiciones de estado.');
INSERT INTO public.recurso VALUES (777, 'Rainbow Slate', 'pizarra arcoiris', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Rainbow Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y el Rainbow Room en Ramanas Park.');
INSERT INTO public.recurso VALUES (778, 'Ralts Dust', 'Polvo de Ralts', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (779, 'Rare Bone', 'Hueso raro', 'CI02', 'A bone that is extremely valuable for Pokémon archeology. It can be sold for a high price to shops.', 'Un hueso extremadamente valioso para la arqueología Pokémon. Se puede vender a un precio alto en las tiendas.');
INSERT INTO public.recurso VALUES (780, 'Rare Candy', 'Dulces raros', 'CI05', 'A candy that is packed with energy. It raises the level of a single Pokémon by one.', 'Un caramelo lleno de energía. Aumenta el nivel de un solo Pokémon en uno.');
INSERT INTO public.recurso VALUES (781, 'Rash Mint', 'Menta Alocada', 'CI03', 'Changes the Pokémon''s stats to match the Rash nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Alocada.');
INSERT INTO public.recurso VALUES (782, 'Rawst Berry', 'Baya más cruda', 'CI04', 'If held by a Pokémon, it recovers from a burn.', 'Si lo sostiene un Pokémon, se recupera de una quemadura.');
INSERT INTO public.recurso VALUES (783, 'Razor Claw', 'Garra de afeitar', 'CI01', 'Increases critical-hit ratio. Evolves Sneasel when held at night.', 'Aumenta la proporción de golpes críticos. Evoluciona a Sneasel cuando se sostiene por la noche.');
INSERT INTO public.recurso VALUES (784, 'Razor Fang', 'Colmillo de navaja', 'CI01', 'May cause opponent to flinch. Evolves Gligar when held at night.', 'Puede hacer que el oponente se estremezca. Evoluciona a Gligar cuando se sostiene por la noche.');
INSERT INTO public.recurso VALUES (785, 'Razz Berry', 'Baya Razz', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (786, 'Reaper Cloth', 'Paño de segador', 'CI02', 'Evolves Dusclops when traded holding the item.', 'Evoluciona a Dusclops cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (787, 'Red Apricorn', 'albaricoque rojo', 'CI02', 'A red Apricorn. It assails your nostrils.', 'Un albaricoque rojo. Asalta tus fosas nasales.');
INSERT INTO public.recurso VALUES (788, 'Red Bell Pepper', 'Pimiento rojo', NULL, 'An ingredient with some bitterness—but its bitter notes and overall flavor are pleasantly mild compared to its green cousin.', 'Un ingrediente con algo de amargura, pero sus notas amargas y su sabor general son agradablemente suaves en comparación con su primo verde.');
INSERT INTO public.recurso VALUES (789, 'Red Card', 'Tarjeta roja', 'CI01', 'A card with a mysterious power. When the holder is struck by a foe, the attacker is removed from battle.', 'Una carta con un poder misterioso. Cuando el poseedor es golpeado por un enemigo, el atacante es retirado de la batalla.');
INSERT INTO public.recurso VALUES (790, 'Red Dish', 'plato rojo', NULL, 'A dish for picnics. Comes in plenty of colors to choose from based on the food or the mood. The red variety never fails to sell well.', 'Un plato para picnics. Viene en muchos colores para elegir según la comida o el estado de ánimo. La variedad roja nunca deja de venderse bien.');
INSERT INTO public.recurso VALUES (791, 'Red-Flag Pick', 'Selección de bandera roja', NULL, 'This pick flies a red flag that lends an air of adventure. The flag itself is made of card stock, so it’ll fly proudly even with no wind.', 'Esta selección enarbola una bandera roja que le da un aire de aventura. La bandera en sí está hecha de cartulina, por lo que ondeará con orgullo incluso sin viento.');
INSERT INTO public.recurso VALUES (792, 'Red Flute', 'flauta roja', 'CI02', 'A toy flute made from red glass. A maniac will buy it for a high price.', 'Una flauta de juguete hecha de cristal rojo. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (793, 'Red Nectar', 'néctar rojo', 'CI01', 'A flower nectar obtained at Ula''ula Meadow. It changes the form of certain species of Pokémon.', 'Un néctar de flores obtenido en Ula''ula Meadow. Cambia la forma de ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (794, 'Red Onion', 'Cebolla roja', NULL, 'An ingredient with some sweetness to it. Its spiciness and fragrance are milder than those of other onions, making it a pleasant bite.', 'Un ingrediente con algo de dulzura. Su picante y su fragancia son más suaves que las de otras cebollas, lo que la convierte en un bocado agradable.');
INSERT INTO public.recurso VALUES (795, 'Red Poké Ball Pick', 'Púa de Pokébola roja', NULL, 'A sandwich pick with a simple red Poké Ball design. Often used by Trainers who picked a Fire-type Pokémon for their first partner.', 'Una selección de sándwich con un diseño simple de Poké Ball rojo. A menudo lo usan Entrenadores que eligieron un Pokémon de tipo Fuego como su primer compañero.');
INSERT INTO public.recurso VALUES (796, 'Red Scarf', 'Bufanda roja', 'CI02', 'Raises holder''s Cool aspect in a Contest.', 'Aumenta el aspecto Genial del poseedor en un Concurso.');
INSERT INTO public.recurso VALUES (797, 'Red Shard', 'Fragmento rojo', 'CI02', 'A small red shard. It appears to be from some sort of implement made long ago.', 'Un pequeño fragmento rojo. Parece ser de algún tipo de implemento hecho hace mucho tiempo.');
INSERT INTO public.recurso VALUES (798, 'Relaxed Mint', 'Menta Plácida', 'CI03', 'Changes the Pokémon''s stats to match the Relaxed nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Plácida.');
INSERT INTO public.recurso VALUES (799, 'Relic Band', 'Banda de reliquia', 'CI02', 'A bracelet made in a civilization about 3,000 years ago. A maniac will buy it for a high price.', 'Una pulsera hecha en una civilización hace unos 3.000 años. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (800, 'Relic Copper', 'Cobre reliquia', 'CI02', 'A copper coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.', 'Una moneda de cobre utilizada en una civilización hace unos 3.000 años. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (801, 'Relic Crown', 'Corona reliquia', 'CI02', 'A crown made in a civilization about 3,000 years ago. A maniac will buy it for a high price.', 'Una corona hecha en una civilización hace unos 3.000 años. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (802, 'Relic Gold', 'reliquia de oro', 'CI02', 'A gold coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.', 'Una moneda de oro utilizada en una civilización hace unos 3.000 años. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (803, 'Relic Silver', 'Reliquia de plata', 'CI02', 'A silver coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.', 'Una moneda de plata utilizada en una civilización hace unos 3.000 años. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (804, 'Relic Statue', 'Estatua reliquia', 'CI02', 'A stone figure made in a civilization about 3,000 years ago. A maniac will buy it for a high price.', 'Una figura de piedra hecha en una civilización hace unos 3.000 años. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (805, 'Relic Vase', 'florero reliquia', 'CI02', 'A vase made in a civilization about 3,000 years ago. A maniac will buy it for a high price.', 'Un jarrón hecho en una civilización hace unos 3.000 años. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (806, 'Rellor Mud', 'Barro Rellor', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (807, 'Remedy', 'Recurso', 'CI05', NULL, NULL);
INSERT INTO public.recurso VALUES (808, 'Repeat Ball', 'Bola de repetición', 'CI06', 'A somewhat different Poké Ball that works especially well on Pokémon species that were previously caught.', 'Una Poké Ball algo diferente que funciona especialmente bien en especies de Pokémon que fueron capturadas previamente.');
INSERT INTO public.recurso VALUES (809, 'Repel', 'Repeler', 'CI02', 'An item that prevents weak wild Pokémon from appearing for 100 steps after its use.', 'Un elemento que evita que aparezcan Pokémon salvajes débiles durante 100 pasos después de su uso.');
INSERT INTO public.recurso VALUES (810, 'Reset Urge', 'Restablecer impulso', 'CI03', 'When used, it restores any stat changes of an ally Pokémon.', 'Cuando se usa, restaura cualquier cambio en las estadísticas de un Pokémon aliado.');
INSERT INTO public.recurso VALUES (811, 'Resist Wing', 'Ala de resistencia', 'CI05', 'Increases Defense EVs by 1.', 'Aumenta los EV de Defensa en 1.');
INSERT INTO public.recurso VALUES (812, 'Reveal Glass', 'Revelar vidrio', 'CI02', 'A looking glass that reveals the truth. It''s a mysterious glass that returns a Pokémon to its original shape.', 'Un espejo que revela la verdad. Es un cristal misterioso que devuelve a un Pokémon a su forma original.');
INSERT INTO public.recurso VALUES (813, 'Revival Herb', 'Hierba de avivamiento', 'CI05', 'Revives a Pokémon to max HP, but lowers Friendship.', 'Revive un Pokémon al máximo de HP, pero reduce la amistad.');
INSERT INTO public.recurso VALUES (814, 'Revive', 'Reanimar', 'CI05', 'A medicine that revives a fainted Pokémon. It restores half the Pokémon''s maximum HP.', 'Una medicina que revive a un Pokémon desmayado. Restaura la mitad del HP máximo del Pokémon.');
INSERT INTO public.recurso VALUES (815, 'Ribbon Sweet', 'cinta dulce', 'CI01', 'Evolves Milcery into Ribbon Flavor Alcremie.', 'Evoluciona Milcery en Ribbon Flavor Alcremie.');
INSERT INTO public.recurso VALUES (816, 'Rice', 'Arroz', NULL, 'An ingredient with a touch of sweetness. It’s unclear how well this cooked rice will serve as a sandwich filling.', 'Un ingrediente con un toque de dulzura. No está claro qué tan bien servirá este arroz cocido como relleno de sándwich.');
INSERT INTO public.recurso VALUES (817, 'Rindo Berry', 'Baya que ríe', 'CI04', 'Weakens a supereffective Grass-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Planta contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (818, 'Ring Target', 'Anillo de destino', 'CI01', 'Moves that would otherwise have no effect will land on the Pokémon that holds it.', 'Los movimientos que de otro modo no tendrían efecto aterrizarán en el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (819, 'Riolu Fur', 'Piel Riolu', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (820, 'Rock Gem', 'Gema de roca', 'CI01', 'Increases the power of a Rock-type move only once.', 'Aumenta el poder de un movimiento de tipo Roca solo una vez.');
INSERT INTO public.recurso VALUES (821, 'Rock Incense', 'Incienso de roca', 'CI01', 'Increases the power of Rock-type moves. Breeding Sudowoodo produces Bonsly when held.', 'Aumenta el poder de los movimientos de tipo Roca. La cría de Sudowoodo produce Bonsly cuando se lleva a cabo.');
INSERT INTO public.recurso VALUES (822, 'Rock Memory', 'Memoria de roca', 'CI01', 'Changes Silvally and its move Multi-Attack to Rock type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Roca.');
INSERT INTO public.recurso VALUES (823, 'Rock Tera Shard', 'Fragmento de roca Tera', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (824, 'Rockium Z', 'Rockio Z', 'CI01', 'Allows the use of Continental Crush, the Rock type Z-Move.', 'Permite el uso de Continental Crush, el tipo Rock Z-Move.');
INSERT INTO public.recurso VALUES (825, 'Rockruff Rock', 'roca roca', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (826, 'Rocky Helmet', 'Casco rocoso', 'CI01', 'If the holder of this item takes damage, the attacker will also be damaged upon contact.', 'Si el poseedor de este artículo recibe daño, el atacante también recibirá daño al contacto.');
INSERT INTO public.recurso VALUES (827, 'Roller Skates', 'Patines', 'CI02', 'Attaches roller skates to the bottom of your shoes, allowing you to glide quickly around and perform tricks.', 'Sujeta patines a la suela de tus zapatos, lo que te permite deslizarte rápidamente y realizar trucos.');
INSERT INTO public.recurso VALUES (828, 'Rolycoly Coal', 'Carbón Rolycoly', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (829, 'Rookidee Feather', 'Pluma de rookidee', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (830, 'Room Service', 'Servicio de habitaciones', 'CI01', 'Lowers the Pokémon''s speed during Trick Room.', 'Reduce la velocidad del Pokémon durante Trick Room.');
INSERT INTO public.recurso VALUES (831, 'Root Fossil', 'Fósil de raíz', 'CI02', 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a plant root.', 'Un fósil de un antiguo Pokémon que vivía en el mar. Parece ser parte de la raíz de una planta.');
INSERT INTO public.recurso VALUES (832, 'Rose Incense', 'incienso rosa', 'CI01', 'Increases the power of Grass-type moves. Breeding Roselia or Roserade produces Budew when held.', 'Aumenta el poder de los movimientos de tipo Hierba. La cría de Roselia o Roserade produce Budew cuando se sostiene.');
INSERT INTO public.recurso VALUES (833, 'Roseli Berry', 'bayas de jamaica', 'CI04', 'If held by a Pokémon, this Berry will lessen the damage taken from one supereffective Fairy-type attack.', 'Si la sostiene un Pokémon, esta baya disminuirá el daño recibido de un ataque supereficaz de tipo hada.');
INSERT INTO public.recurso VALUES (834, 'Roto Bargain', 'ganga rotativa', 'CI03', 'Reduces the prices of products at Poké Marts by half.', 'Reduce a la mitad los precios de los productos en Poké Marts.');
INSERT INTO public.recurso VALUES (835, 'Roto Boost', 'Impulso rotativo', 'CI03', 'Raises all stats of your battling Pokémon.', 'Aumenta todas las estadísticas de tus Pokémon luchadores.');
INSERT INTO public.recurso VALUES (836, 'Roto Catch', 'Captura giratoria', 'CI03', 'Increases the chance to catch Pokémon a lot.', 'Aumenta mucho la posibilidad de atrapar Pokémon.');
INSERT INTO public.recurso VALUES (837, 'Roto Encounter', 'Encuentro en el lago', 'CI03', 'Increases the chance of encountering high-level wild Pokémon a lot for a certain period of time.', 'Aumenta la posibilidad de encontrar muchos Pokémon salvajes de alto nivel durante un cierto período de tiempo.');
INSERT INTO public.recurso VALUES (838, 'Roto Exp. Points', 'Roto Exp. Puntos', 'CI03', 'Increases the Exp. Points your Pokémon receive after battle a little.', 'Aumenta la Exp. Puntos que reciben tus Pokémon después de la batalla un poco.');
INSERT INTO public.recurso VALUES (839, 'Roto Friendship', 'Roto Amistad', 'CI03', 'Helps Pokémon in your party grow friendly faster.', 'Ayuda a los Pokémon de tu grupo a volverse amigos más rápido.');
INSERT INTO public.recurso VALUES (840, 'Roto Hatch', 'escotilla rotatoria', 'CI03', 'Helps Eggs hatch faster.', 'Ayuda a que los huevos eclosionen más rápido.');
INSERT INTO public.recurso VALUES (841, 'Roto HP Restore', 'Restauración interna de HP', 'CI03', 'Fully restores the HP of your battling Pokémon.', 'Restaura completamente el HP de tus Pokémon que luchan.');
INSERT INTO public.recurso VALUES (842, 'Roto PP Restore', 'Restauración Roto PP', 'CI03', 'Fully restores the PP of your battling Pokémon.', 'Restaura completamente el PP de tus Pokémon en combate.');
INSERT INTO public.recurso VALUES (843, 'Roto Prize Money', 'Dinero del premio Roto', 'CI03', 'Triples the prize money you receive after battle.', 'Triplica el dinero del premio que recibes después de la batalla.');
INSERT INTO public.recurso VALUES (844, 'Roto Stealth', 'Roto sigilo', 'CI03', 'Prevents you from encountering wild Pokémon for a certain period of time.', 'Evita que te encuentres con Pokémon salvajes durante un cierto período de tiempo.');
INSERT INTO public.recurso VALUES (845, 'Rotom Phone', 'teléfono roto', NULL, 'The latest model of smartphone. A Pokémon called Rotom lives within it, and it can be used to run all sorts of handy apps.', 'El último modelo de teléfono inteligente. Un Pokémon llamado Rotom vive dentro de él y se puede usar para ejecutar todo tipo de aplicaciones útiles.');
INSERT INTO public.recurso VALUES (846, 'Rotom Sparks', 'chispas rotas', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (847, 'Rowap Berry', 'Baya de remo', 'CI04', 'If held by a Pokémon and a special attack lands, the attacker also takes damage.', 'Si lo sostiene un Pokémon y cae un ataque especial, el atacante también recibe daño.');
INSERT INTO public.recurso VALUES (848, 'Rufflet Feather', 'Pluma con volantes', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (849, 'Sablenite', 'sablenita', 'CI01', 'Enables Sableye to Mega Evolve during battle.', 'Permite a Sableye megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (850, 'Sableye Gem', 'Gema de ojo de sablée', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (851, 'Sachet', 'Bolsita', 'CI02', 'Evolves Spritzee when traded holding the item.', 'Evoluciona a Spritzee cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (852, 'Sacred Ash', 'Ceniza sagrada', 'CI05', 'It revives all fainted Pokémon. In doing so, it also fully restores their HP.', 'Revive a todos los Pokémon desmayados. Al hacerlo, también restaura completamente su HP.');
INSERT INTO public.recurso VALUES (853, 'Safari Ball', 'Bola Safari', 'CI06', 'A special Poké Ball that is used only in the Great Marsh. It is decorated in a camouflage pattern.', 'Una Pokébola especial que solo se usa en el Gran Pantano. Está decorado con un patrón de camuflaje.');
INSERT INTO public.recurso VALUES (854, 'Safety Goggles', 'Gafas protectoras', 'CI01', 'Prevents damage from weather and powder.', 'Evita daños por la intemperie y el polvo.');
INSERT INTO public.recurso VALUES (855, 'Salac Berry', 'Baya Salac', 'CI04', 'Raises Speed when HP is low.', 'Aumenta la velocidad cuando HP es bajo.');
INSERT INTO public.recurso VALUES (856, 'Salad Mix', 'Mezcla de ensalada', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. The assortment of vegetables looks quite appealing and healthy.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. El surtido de verduras se ve bastante atractivo y saludable.');
INSERT INTO public.recurso VALUES (857, 'Salamencite', 'salamencita', 'CI01', 'Enables Salamence to Mega Evolve during battle.', 'Permite a Salamence megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (858, 'Salandit Gas', 'Salandit Gas', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (859, 'Salt', 'Sal', NULL, 'A very salty seasoning, unsurprisingly. People quite like the grains of salt that can be gathered from the footprints of particularly jagged Naclstack.', 'Un condimento muy salado, como era de esperar. A la gente le gustan mucho los granos de sal que se pueden extraer de las huellas de Naclstack particularmente irregular.');
INSERT INTO public.recurso VALUES (860, 'Salt Cake', 'Pastel de sal', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (861, 'Salty Herba Mystica', 'Herba Mystica salada', NULL, 'One of the condiments spoken of as legends. Its mellow saltiness is said to be tremendously effective when it comes to promoting health.', 'Uno de los condimentos de los que se habla como leyendas. Se dice que su suave sabor salado es tremendamente efectivo cuando se trata de promover la salud.');
INSERT INTO public.recurso VALUES (862, 'Sand Radish', 'Rábano de arena', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (863, 'Sandile Claw', 'Garra de sándalo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (864, 'Sandwich', 'Sándwich', NULL, 'A dish made by sandwiching vegetables, meat, or other ingredients between two pieces of bread. It makes a fantastic meal when out on a picnic.', 'Plato que se prepara intercalando verduras, carne u otros ingredientes entre dos rebanadas de pan. Hace una comida fantástica cuando estás de picnic.');
INSERT INTO public.recurso VALUES (865, 'Sandygast Sand', 'Arena Sandygast', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (866, 'Sassy Mint', 'Menta Grosera', 'CI03', 'Changes the Pokémon''s stats to match the Sassy nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Grosera.');
INSERT INTO public.recurso VALUES (867, 'Sausages', 'Salchichas', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. These sausages should be boiled before eating.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Estas salchichas se deben hervir antes de comer.');
INSERT INTO public.recurso VALUES (868, 'Scarlet Book', 'Libro Escarlata', NULL, 'A record of the expedition that the author, Heath, went on within the Great Crater of Paldea. The book has the name “Sada” written on it in clumsy handwriting.', 'Un registro de la expedición que el autor, Heath, realizó dentro del Gran Cráter de Paldea. El libro tiene el nombre “Sada” escrito con letra torpe.');
INSERT INTO public.recurso VALUES (869, 'Scatter Bang', 'Explosión de dispersión', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (870, 'Scatterbug Powder', 'Polvo de bicho de dispersión', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (871, 'Sceptilite', 'esceptilita', 'CI01', 'Enables Sceptile to Mega Evolve during battle.', 'Permite que Sceptile megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (872, 'Scizorite', 'Escizorita', 'CI01', 'Enables Scizor to Mega Evolve during battle.', 'Permite a Scizor megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (873, 'Scope Lens', 'Lente de alcance', 'CI01', 'Increases critical-hit ratio.', 'Aumenta la proporción de golpes críticos.');
INSERT INTO public.recurso VALUES (874, 'Scroll of Darkness', 'Pergamino de la oscuridad', NULL, 'A peculiar scroll that can make a certain species of Pokémon evolve. Written upon it are the true secrets of the path of darkness.', 'Un pergamino peculiar que puede hacer evolucionar a ciertas especies de Pokémon. Escritos en él están los verdaderos secretos del camino de la oscuridad.');
INSERT INTO public.recurso VALUES (875, 'Scroll of Waters', 'Pergamino de las aguas', NULL, 'A peculiar scroll that can make a certain species of Pokémon evolve. Written upon it are the true secrets of the path of water.', 'Un pergamino peculiar que puede hacer evolucionar a ciertas especies de Pokémon. Escritos en él están los verdaderos secretos del camino del agua.');
INSERT INTO public.recurso VALUES (876, 'Scyther Claw', 'Garra de guadaña', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (877, 'Sea Incense', 'Incienso de mar', 'CI01', 'Increases the power of Water-type moves. Breeding Marill or Azumarill produces Azurill when held.', 'Aumenta el poder de los movimientos de tipo agua. Criar Marill o Azumarill produce Azurill cuando se sostiene.');
INSERT INTO public.recurso VALUES (878, 'Seed of Mastery', 'Semilla de Maestría', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (879, 'Serious Mint', 'Menta Seria', 'CI03', 'Changes the Pokémon''s stats to match a neutral nature.', 'Cambia las estadísticas del Pokémon para que coincidan con una naturaleza Seria.');
INSERT INTO public.recurso VALUES (880, 'Seviper Fang', 'Colmillo de víbora', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (881, 'Shaderoot Carrot', 'Zanahoria sombra', 'CI02', 'Produce that the King of Bountiful Harvests’ beloved steed likes to eat. It grew in a gloomy field.', 'Productos que le gusta comer al amado corcel del Rey de las Cosechas Abundantes. Creció en un campo sombrío.');
INSERT INTO public.recurso VALUES (882, 'Shalour Sable', 'Arena Shahour', 'CI05', 'Heals all major status conditions.', 'Cura todas las principales condiciones de estado.');
INSERT INTO public.recurso VALUES (883, 'Sharp Beak', 'Pico afilado', 'CI01', 'Increases the power of Flying-type moves.', 'Aumenta el poder de los movimientos de tipo volador.');
INSERT INTO public.recurso VALUES (884, 'Sharpedonite', 'Sharpedonita', 'CI01', 'Enables Sharpedo to Mega Evolve during battle.', 'Permite que Sharpedo megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (885, 'Shed Shell', 'Concha de cobertizo', 'CI01', 'A tough, discarded carapace to be held by a Pokémon. It enables the holder to switch with a waiting Pokémon in battle.', 'Un caparazón resistente y descartado para ser sostenido por un Pokémon. Permite al titular cambiar con un Pokémon en espera en la batalla.');
INSERT INTO public.recurso VALUES (886, 'Shell Bell', 'Campana de concha', 'CI01', 'An item to be held by a Pokémon. The holder''s HP is restored a little every time it inflicts damage.', 'Un objeto para ser sostenido por un Pokémon. El HP del titular se restaura un poco cada vez que inflige daño.');
INSERT INTO public.recurso VALUES (887, 'Shellder Pearl', 'Perla de Shellder', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (888, 'Shellos Mucus', 'Moco Shellos', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (889, 'Shinx Fang', 'Colmillo Shinx', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (890, 'Shiny Charm', 'encanto brillante', 'CI02', 'A shiny charm said to increase the chance of finding a Shiny Pokémon in the wild.', 'Un amuleto brillante que se dice que aumenta las posibilidades de encontrar un Pokémon brillante en la naturaleza.');
INSERT INTO public.recurso VALUES (891, 'Shiny Stone', 'Piedra brillante', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (892, 'Shoal Salt', 'sal de banco', 'CI02', 'Pure salt that can be discovered deep inside the Shoal Cave. A maniac will buy it for a high price.', 'Sal pura que se puede descubrir en el interior de la cueva Shoal. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (893, 'Shoal Shell', 'Concha de bajío', 'CI02', 'A pretty seashell that can be found deep inside the Shoal Cave. A maniac will buy it for a high price.', 'Una bonita concha marina que se puede encontrar en las profundidades de la cueva Shoal. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (894, 'Shock Drive', 'Impulsión de choque', 'CI01', 'Changes Techno Blast to an Electric-type move when held by Genesect.', 'Cambia Techno Blast a un movimiento de tipo eléctrico cuando lo sostiene Genesect.');
INSERT INTO public.recurso VALUES (895, 'Shroodle Ink', 'Tinta Shroodle', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (896, 'Shroomish Spores', 'Esporas de hongos', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (897, 'Shuca Berry', 'Baya Shuca', 'CI04', 'Weakens a supereffective Ground-type attack against the holding Pokémon.', 'Debilita un ataque de tipo Tierra supereficaz contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (898, 'Shuppet Scrap', 'chatarra', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (899, 'Silicobra Sand', 'Arena silicobra', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (900, 'Silk Scarf', 'Pañuelo de seda', 'CI01', 'Increases the power of Normal-type moves.', 'Aumenta el poder de los movimientos de tipo Normal.');
INSERT INTO public.recurso VALUES (901, 'Silver Bottle', 'botella de plata', NULL, 'A popular option among hikers. It’s made with titanium, so it doesn’t rust even if it’s used to hold drinks with high sodium content.', 'Una opción popular entre los excursionistas. Está fabricado con titanio, por lo que no se oxida aunque se utilice para contener bebidas con alto contenido de sodio.');
INSERT INTO public.recurso VALUES (902, 'Silver Cup', 'Copa de Plata', NULL, 'A popular option among hikers. It’s made with titanium, so it doesn’t rust even if it’s used to hold drinks with high sodium content.', 'Una opción popular entre los excursionistas. Está fabricado con titanio, por lo que no se oxida aunque se utilice para contener bebidas con alto contenido de sodio.');
INSERT INTO public.recurso VALUES (903, 'Silver Leaf', 'Hoja de plata', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (904, 'Silver Nanab Berry', 'Baya Nanab plateada', 'CI04', 'Greatly calms a Pokémon in battle, in Let''s Go Pikachu/Eevee.', 'Calma enormemente a un Pokémon en batalla, en Let''s Go Pikachu/Eevee.');
INSERT INTO public.recurso VALUES (905, 'Silver Pick', 'Púa de plata', NULL, 'A silver pick that oozes class. Using it on a sandwich lends an extravagant air that’ll make you want to eat up, even if you don’t love the fillings.', 'Una púa plateada que rezuma clase. Usarlo en un sándwich le da un aire extravagante que te hará querer comer, incluso si no te gustan los rellenos.');
INSERT INTO public.recurso VALUES (906, 'Silver Pinap Berry', 'Baya de piña plateada', 'CI04', 'Greatly increases chance of getting items when a Pokémon is caught, in Pokémon Let''s Go.', 'Aumenta en gran medida la posibilidad de obtener elementos cuando se captura un Pokémon, en Pokémon Let''s Go.');
INSERT INTO public.recurso VALUES (907, 'Silver Powder', 'polvo de plata', 'CI01', 'Increases the power of Bug-type moves.', 'Aumenta el poder de los movimientos tipo Bicho.');
INSERT INTO public.recurso VALUES (908, 'Silver Razz Berry', 'Baya Razz plateada', 'CI04', 'Makes a Pokémon easier to catch in Pokémon Let''s Go.', 'Hace que un Pokémon sea más fácil de atrapar en Pokémon Let''s Go.');
INSERT INTO public.recurso VALUES (909, 'Sinistea Chip', 'créelo chip', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (910, 'Sitrus Berry', 'Baya de sítrus', 'CI04', 'If held by a Pokémon, it heals the user''s HP a little.', 'Si está en manos de un Pokémon, cura un poco el HP del usuario.');
INSERT INTO public.recurso VALUES (911, 'Skiddo Leaf', 'hoja de patín', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (912, 'Skrelp Kelp', 'algas marinas', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (913, 'Skull Fossil', 'fósil de cráneo', 'CI02', 'A fossil from a prehistoric Pokémon that lived on the land. It appears to be part of a head.', 'Un fósil de un Pokémon prehistórico que vivió en la tierra. Parece ser parte de una cabeza.');
INSERT INTO public.recurso VALUES (914, 'Skwovet Fur', 'Piel Skwovet', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (915, 'Sky Plate', 'placa del cielo', 'CI01', 'Increases power of Flying-type moves. Changes Arceus'' type to Flying.', 'Aumenta el poder de los movimientos de tipo volador. Cambia el tipo de Arceus a Volador.');
INSERT INTO public.recurso VALUES (916, 'Sky Tumblestone', 'Piedra rodadora del cielo', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (917, 'Slakoth Fur', 'Piel de Slakoth', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (918, 'Slowbronite', 'Slowbronita', 'CI01', 'Enables Slowbro to Mega Evolve during battle.', 'Permite a Slowbro Mega Evolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (919, 'Slowpoke Claw', 'Garra lenta', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (920, 'Slowpoke Cup', 'Copa Slowpoke', NULL, 'A cup for big-time Pokémon fans. Kids will happily drink out of it, making it a boon to parents.', 'Una taza para los grandes fanáticos de Pokémon. Los niños beberán felizmente, lo que lo convierte en una bendición para los padres.');
INSERT INTO public.recurso VALUES (921, 'Small Bouquet', 'Pequeño Ramo', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (922, 'Smart Candy', 'Caramelo inteligente', 'CI05', 'Increases a Pokémon''s Special Attack stat by 1.', 'Aumenta la estadística de ataque especial de un Pokémon en 1.');
INSERT INTO public.recurso VALUES (923, 'Smart Candy L', 'Caramelo inteligente L', 'CI05', 'Increases a Pokémon''s Special Attack stat.', 'Aumenta la estadística de ataque especial de un Pokémon.');
INSERT INTO public.recurso VALUES (924, 'Smart Candy XL', 'Caramelo inteligente XL', 'CI05', 'Increases a Pokémon''s Special Attack stat.', 'Aumenta la estadística de ataque especial de un Pokémon.');
INSERT INTO public.recurso VALUES (925, 'Smiling Vee Pick', 'Selección en uve sonriente', NULL, 'A pick designed after Eevee, sporting the Pokémon’s smiling face. It’s easy to grab by the ears, which is part of why it’s so popular.', 'Una selección diseñada después de Eevee, luciendo la cara sonriente del Pokémon. Es fácil de agarrar por las orejas, lo cual es parte de por qué es tan popular.');
INSERT INTO public.recurso VALUES (926, 'Smoke Ball', 'Bola de humo', 'CI01', 'An item to be held by a Pokémon. It enables the holder to flee from any wild Pokémon without fail.', 'Un objeto para ser sostenido por un Pokémon. Permite al titular huir de cualquier Pokémon salvaje sin falta.');
INSERT INTO public.recurso VALUES (927, 'Smoke Bomb', 'Bomba de humo', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (928, 'Smoke-Poke Tail', 'Cola de humo', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. When a Slowpoke’s tail falls off, it grows back quickly.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Cuando la cola de un Slowpoke se cae, vuelve a crecer rápidamente.');
INSERT INTO public.recurso VALUES (929, 'Smoked Fillet', 'Filete Ahumado', NULL, 'A very salty and bitter ingredient with that unmistakable smoky flavor. It pairs exceptionally well with veggies.', 'Un ingrediente muy salado y amargo con ese inconfundible sabor ahumado. Combina excepcionalmente bien con verduras.');
INSERT INTO public.recurso VALUES (930, 'Smoliv Oil', 'Aceite Smoliv', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (931, 'Smooth Rock', 'Roca lisa', 'CI01', 'A Pokémon held item that extends the duration of the move Sandstorm used by the holder.', 'Un objeto Pokémon que se extiende la duración del movimiento Tormenta de arena utilizado por el poseedor.');
INSERT INTO public.recurso VALUES (932, 'Sneasel Claw', 'Garra de Sneasel', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (933, 'Snom Thread', 'Hilo de Snom', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (934, 'Snorlium Z', 'Snorlium Z', 'CI01', 'Allows Snorlax to upgrade Giga Impact to a Z-Move, Pulverizing Pancake.', 'Permite a Snorlax actualizar Giga Impact a Z-Move, Pulverizing Pancake.');
INSERT INTO public.recurso VALUES (935, 'Snorunt Fur', 'Piel de resoplido', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (936, 'Snover Berries', 'Bayas de Snover', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (937, 'Snowball', 'Bola de nieve', 'CI01', 'Raises Attack if hit by an Ice-type move.', 'Aumenta el Ataque si es golpeado por un movimiento de tipo Hielo.');
INSERT INTO public.recurso VALUES (938, 'Soda Pop', 'Gaseosa', 'CI05', 'Restores 50 HP.', 'Restaura 50 HP.');
INSERT INTO public.recurso VALUES (939, 'Soft Sand', 'Arena suave', 'CI01', 'Increases the power of Ground-type moves.', 'Aumenta el poder de los movimientos de tipo Tierra.');
INSERT INTO public.recurso VALUES (940, 'Solganium Z', 'Solganio Z', 'CI01', 'Allows Solgaleo to upgrade Sunsteel Strike to a Z-Move, Searing Sunraze Smash.', 'Permite a Solgaleo actualizar Sunsteel Strike a un Z-Move, Searing Sunraze Smash.');
INSERT INTO public.recurso VALUES (941, 'Sootfoot Root', 'Raíz de hollín', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (942, 'Soothe Bell', 'Campana calmante', 'CI01', 'An item to be held by a Pokémon. It is a bell with a comforting chime that calms the holder and makes it friendly.', 'Un objeto para ser sostenido por un Pokémon. Es una campana con un carillón reconfortante que tranquiliza al portador y lo hace amable.');
INSERT INTO public.recurso VALUES (943, 'Soul Dew', 'Rocío del alma', 'CI01', 'Increases the power of Psychic- and Dragon-type moves when held by Latios or Latias. Increases Sp.Atk/Sp.Def prior to Gen 7.', 'Aumenta el poder de los movimientos de tipo Psíquico y Dragón cuando los sostiene Latios o Latias. Aumenta Sp.Atk/Sp.Def antes de Gen 7.');
INSERT INTO public.recurso VALUES (944, 'Soul Slate', 'Pizarra del alma', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Soul Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y Soul Room en Ramanas Park.');
INSERT INTO public.recurso VALUES (945, 'Sour Herba Mystica', 'Herba Mystica agria', NULL, 'This surpassingly sour condiment is said to be super effective in helping the eater recover from exhaustion. Only a scant few people know it exists.', 'Se dice que este condimento sumamente amargo es súper efectivo para ayudar a quien lo come a recuperarse del agotamiento. Solo unas pocas personas saben que existe.');
INSERT INTO public.recurso VALUES (946, 'Spell Tag', 'Etiqueta de hechizo', 'CI01', 'Increases the power of Ghost-type moves.', 'Aumenta el poder de los movimientos de tipo Fantasma.');
INSERT INTO public.recurso VALUES (947, 'Spelon Berry', 'Baya de la cueva', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (948, 'Spice Mix', 'Mezcla de especias', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. There are over fifty spices contained within this ingredient’s hot flavor.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Hay más de cincuenta especias contenidas en el sabor picante de este ingrediente.');
INSERT INTO public.recurso VALUES (949, 'Spicy Herba Mystica', 'Hierba mística picante', NULL, 'The legendary condiment said to have the mightiest of all spicy flavors. It’s said that a single bite will kick the metabolism into high gear immediately.', 'El condimento legendario que se dice que tiene el más poderoso de todos los sabores picantes. Se dice que un solo bocado acelerará el metabolismo inmediatamente.');
INSERT INTO public.recurso VALUES (950, 'Spiritomb Fragment', 'Fragmento de Spiritomb', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (951, 'Splash Plate', 'Placa de salpicaduras', 'CI01', 'Increases power of Water-type moves. Changes Arceus'' type to Water.', 'Aumenta el poder de los movimientos de tipo agua. Cambia el tipo de Arceus a Agua.');
INSERT INTO public.recurso VALUES (952, 'Spoiled Apricorn', 'Albaricoque estropeado', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (953, 'Spoink Pearl', 'perla espeluznante', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (954, 'Spooky Plate', 'Plato espeluznante', 'CI01', 'Increases power of Ghost-type moves. Changes Arceus'' type to Ghost.', 'Aumenta el poder de los movimientos de tipo Fantasma. Cambia el tipo de Arceus a Fantasma.');
INSERT INTO public.recurso VALUES (955, 'Spooky Tablecloth', 'Mantel espeluznante', NULL, 'A pop-art-style tablecloth with Pokémon faces floating up from the deep nighttime blue. This is a must-have for fans of Ghost types.', 'Un mantel de estilo pop-art con caras de Pokémon flotando desde el azul profundo de la noche. Esto es imprescindible para los fanáticos de los tipos de fantasmas.');
INSERT INTO public.recurso VALUES (956, 'Sport Ball', 'Bola Deportiva', 'CI06', 'A special Poké Ball for the Bug-Catching Contest.', 'Una Pokébola especial para el concurso de captura de insectos.');
INSERT INTO public.recurso VALUES (957, 'Springy Mushroom', 'Hongo elástico', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (958, 'Sprinklotad', 'espolvoreado', 'CI02', 'A watering can shaped like a Lotad. It helps promote the healthy growth of any Berries planted in good, soft soil.', 'Una regadera con forma de Lotad. Ayuda a promover el crecimiento saludable de las bayas plantadas en un suelo bueno y suave.');
INSERT INTO public.recurso VALUES (959, 'Squall Slate', 'Pizarra de borrasca', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Squall Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y Squall Room en Ramanas Park.');
INSERT INTO public.recurso VALUES (960, 'Squawkabilly Feather', 'Pluma de graznido', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (961, 'Stable Mulch', 'mantillo estable', 'CI02', 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.', 'Un fertilizante para esparcir en suelos blandos en regiones donde se cultivan bayas. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (962, 'Stantler Hair', 'Cabello Stanler', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (963, 'Star Piece', 'Pieza estrella', 'CI02', 'A shard of a pretty gem that sparkles in a red color. It can be sold at a high price to shops.', 'Un fragmento de una hermosa gema que brilla en un color rojo. Se puede vender a un precio alto en las tiendas.');
INSERT INTO public.recurso VALUES (964, 'Star Sweet', 'dulce estrella', 'CI01', 'Evolves Milcery into Star Flavor Alcremie.', 'Evoluciona a Milcery en Star Flavor Alcremie.');
INSERT INTO public.recurso VALUES (965, 'Stardust', 'polvo de estrellas', 'CI02', 'Lovely, red-colored sand with a loose, silky feel. It can be sold at a high price to shops.', 'Preciosa arena de color rojo con un tacto suelto y sedoso. Se puede vender a un precio alto en las tiendas.');
INSERT INTO public.recurso VALUES (966, 'Starf Berry', 'Baya de estrella', 'CI04', 'Sharply raises a random stat when HP is low.', 'Aumenta bruscamente una estadística aleatoria cuando HP es bajo.');
INSERT INTO public.recurso VALUES (967, 'Starly Feather', 'Pluma estrellada', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (968, 'Stealth Spray', 'Aerosol sigiloso', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (969, 'Steel Bottle (B)', 'Botella de acero (G)', NULL, 'A go-to bottle sometimes used while camping. The stainless steel keeps the temperature inside steady, making it great for keeping drinks hot or cold.', 'Una botella de referencia que a veces se usa para acampar. El acero inoxidable mantiene constante la temperatura en el interior, lo que lo hace ideal para mantener las bebidas frías o calientes.');
INSERT INTO public.recurso VALUES (970, 'Steel Bottle (R)', 'Botella de acero (R)', NULL, 'A go-to bottle sometimes used while camping. The stainless steel keeps the temperature inside steady, making it great for keeping drinks hot or cold.', 'Una botella de referencia que a veces se usa para acampar. El acero inoxidable mantiene constante la temperatura en el interior, lo que lo hace ideal para mantener las bebidas frías o calientes.');
INSERT INTO public.recurso VALUES (971, 'Steel Bottle (Y)', 'Botella de acero (Y)', NULL, 'A go-to bottle sometimes used while camping. The stainless steel keeps the temperature inside steady, making it great for keeping drinks hot or cold.', 'Una botella de referencia que a veces se usa para acampar. El acero inoxidable mantiene constante la temperatura en el interior, lo que lo hace ideal para mantener las bebidas frías o calientes.');
INSERT INTO public.recurso VALUES (972, 'Steel Gem', 'Gema de acero', 'CI01', 'Increases the power of a Steel-type move only once.', 'Aumenta el poder de un movimiento de tipo Acero solo una vez.');
INSERT INTO public.recurso VALUES (973, 'Steel Memory', 'Memoria de acero', 'CI01', 'Changes Silvally and its move Multi-Attack to Steel type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Acero.');
INSERT INTO public.recurso VALUES (974, 'Steel Tera Shard', 'Fragmento de Tera de acero', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (975, 'Steelium Z', 'Steelio Z', 'CI01', 'Allows the use of Corkscrew Crash, the Steel type Z-Move.', 'Permite el uso de Sacacorchos Crash, el tipo Z-Move de acero.');
INSERT INTO public.recurso VALUES (976, 'Steelixite', 'Steelixita', 'CI01', 'Enables Steelix to Mega Evolve during battle.', 'Permite a Steelix megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (977, 'Sticky Barb', 'Púa pegajosa', 'CI01', 'A held item that damages the holder on every turn. It may latch on to foes and allies that touch the holder.', 'Un objeto retenido que daña al poseedor en cada turno. Puede aferrarse a los enemigos y aliados que tocan al portador.');
INSERT INTO public.recurso VALUES (978, 'Sticky Glob', 'Globo pegajoso', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (979, 'Stone Plate', 'placa de piedra', 'CI01', 'Increases power of Rock-type moves. Changes Arceus'' type to Rock.', 'Aumenta el poder de los movimientos tipo roca. Cambia el tipo de Arceus a Roca.');
INSERT INTO public.recurso VALUES (980, 'Stonjourner Stone', 'Piedra viajera pedregosa', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (981, 'Strange Ball', 'Bola Extraña', 'CI06', NULL, NULL);
INSERT INTO public.recurso VALUES (982, 'Strange Souvenir', 'Recuerdo extraño', 'CI02', 'An ornament depicting a Pokémon that is venerated as a protector in some region far from Kalos.', 'Un adorno que representa a un Pokémon venerado como protector en alguna región alejada de Kalos.');
INSERT INTO public.recurso VALUES (983, 'Stratospheric Slate', 'Pizarra estratosférica', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Stratospheric Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y la Sala Estratosférica en Ramanas Park.');
INSERT INTO public.recurso VALUES (984, 'Strawberry', 'Fresa', NULL, 'A very tart and sweet ingredient, popular for its ability to make a sandwich visually striking.', 'Un ingrediente muy agrio y dulce, popular por su capacidad para hacer un sándwich visualmente impactante.');
INSERT INTO public.recurso VALUES (985, 'Strawberry Sweet', 'dulce de fresa', 'CI01', 'Evolves Milcery into Strawberry Flavor Alcremie.', 'Evoluciona Milcery en Strawberry Flavor Alcremie.');
INSERT INTO public.recurso VALUES (986, 'Stretchy Spring', 'Resorte elástico', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (987, 'Striped Bottle', 'Botella Rayada', NULL, 'A striped bottle that’s small, light, and even comes with a cup. The detachable strap makes it handy for walking around with.', 'Una botella rayada que es pequeña, liviana e incluso viene con una taza. La correa desmontable lo hace útil para caminar.');
INSERT INTO public.recurso VALUES (988, 'Striped Cup', 'Copa rayada', NULL, 'A cup for kids to use at picnics. It’s made of light but strong material. It’s stackable, which makes it handy for carrying around.', 'Una taza para que los niños la usen en los picnics. Está hecho de un material ligero pero resistente. Es apilable, lo que lo hace práctico para transportar.');
INSERT INTO public.recurso VALUES (989, 'Striped Tablecloth', 'Mantel Rayas', NULL, 'A tablecloth with a fashionable striped pattern. It’s great at repelling water and mold, and stains and smudges wipe right off.', 'Un mantel con un patrón de rayas de moda. Es excelente para repeler el agua y el moho, y las manchas y manchas se limpian de inmediato.');
INSERT INTO public.recurso VALUES (990, 'Stunky Fur', 'Pelaje apestoso', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (991, 'Sun Stone', 'Piedra del sol', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (992, 'Sunkern Leaf', 'Hoja hundida', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (993, 'Sunrise Flower Pick', 'Pico de flor del amanecer', NULL, 'A flower pick designed to evoke a glorious sunrise. It’s part of a line of “sky-flower” picks. Using a few is guaranteed to boost that special picnic spirit.', 'Una selección de flores diseñada para evocar un amanecer glorioso. Es parte de una línea de selecciones sky-flower. El uso de algunos está garantizado para impulsar ese espíritu especial de picnic.');
INSERT INTO public.recurso VALUES (994, 'Sunset Flower Pick', 'Pico de flor al atardecer', NULL, 'A flower pick designed to evoke a blazing sunset. It’s part of a line of “sky-flower” picks. Using a few is guaranteed to boost that special picnic spirit.', 'Una selección de flores diseñada para evocar una puesta de sol resplandeciente. Es parte de una línea de selecciones sky-flower. El uso de algunos está garantizado para impulsar ese espíritu especial de picnic.');
INSERT INTO public.recurso VALUES (995, 'Super Lure', 'Súper señuelo', 'CI02', 'Attracts Pokémon in the wild.', 'Atrae Pokémon en estado salvaje.');
INSERT INTO public.recurso VALUES (996, 'Super Potion', 'Súper Poción', 'CI05', 'Restores 60 HP.', 'Restaura 60 HP.');
INSERT INTO public.recurso VALUES (997, 'Super Repel', 'Súper repelente', 'CI02', 'An item that prevents weak wild Pokémon from appearing for 200 steps after its use.', 'Un elemento que evita que aparezcan Pokémon salvajes débiles durante 200 pasos después de su uso.');
INSERT INTO public.recurso VALUES (998, 'Surskit Syrup', 'Jarabe de Surskit', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (999, 'Swablu Fluff', 'Pelusa Swablu', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1000, 'Swampertite', 'Swampertita', 'CI01', 'Enables Swampert to Mega Evolve during battle.', 'Permite a Swampert megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (1001, 'Swap Snack', 'Intercambio de refrigerio', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (1002, 'Sweet Apple', 'Manzana dulce', 'CI01', 'Evolves Applin into Appletun.', 'Evoluciona Applin en Appletun.');
INSERT INTO public.recurso VALUES (1003, 'Sweet Heart', 'Cariño', 'CI05', 'Very sweet chocolate. It restores the HP of one Pokémon by only 20 points.', 'Chocolate muy dulce. Restaura el HP de un Pokémon por solo 20 puntos.');
INSERT INTO public.recurso VALUES (1004, 'Sweet Herba Mystica', 'Hierba mística dulce', NULL, 'A legendary condiment told of only in books. Word has it that one taste of its sweet flavor stimulates the digestive system and cures a lack of appetite.', 'Un condimento legendario del que solo se habla en los libros. Se dice que probar su sabor dulce estimula el sistema digestivo y cura la falta de apetito.');
INSERT INTO public.recurso VALUES (1005, 'Swift Wing', 'Ala veloz', 'CI05', 'Increases Speed EVs by 1.', 'Aumenta los EV de velocidad en 1.');
INSERT INTO public.recurso VALUES (1006, 'Swordcap', 'espadachín', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (1007, 'Tadbulb Mucus', 'moco de renacuajo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1008, 'Tamato Berry', 'Baya de tomate', 'CI04', 'Increases Friendship but lowers Speed EVs.', 'Aumenta la amistad pero reduce los EV de velocidad.');
INSERT INTO public.recurso VALUES (1009, 'Tandemaus Fur', 'Piel de tándemaus', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1010, 'Tanga Berry', 'Baya Tanga', 'CI04', 'Weakens a supereffective Bug-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Bicho contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (1011, 'Tapunium Z', 'tapunio z', 'CI01', 'Allows the Tapus to upgrade Nature''s Madness to a Z-Move, Guardian of Alola.', 'Permite al Tapus actualizar Nature''s Madness a un Z-Move, Guardian of Alola.');
INSERT INTO public.recurso VALUES (1012, 'Tarountula Thread', 'Hilo de tarúntula', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1013, 'Tart Apple', 'Tarta de manzana', 'CI01', 'Evolves Applin into Flapple.', 'Evoluciona a Applin en Flapple.');
INSERT INTO public.recurso VALUES (1014, 'Tatsugiri Scales', 'Escamas Tatsugiri', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1015, 'Tauros Hair', 'Cabello Tauro', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1016, 'Tectonic Slate', 'Pizarra Tectónica', NULL, 'A slate overflowing with enigmatic energy. You can feel a strong connection between it and the Tectonic Room at Ramanas Park.', 'Una pizarra rebosante de enigmática energía. Puedes sentir una fuerte conexión entre él y la Sala Tectónica en el Parque Ramanas.');
INSERT INTO public.recurso VALUES (1017, 'Teddiursa Claw', 'Garra de teddiursa', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1018, 'Tera Orb', 'Orbe Tera', NULL, 'An orb that holds within it the power to crystallize. When it is charged with energy, it can be used to cause Pokémon to Terastallize.', 'Un orbe que contiene en su interior el poder de cristalizar. Cuando está cargado de energía, se puede usar para hacer que los Pokémon se terastalicen.');
INSERT INTO public.recurso VALUES (1019, 'Terrain Extender', 'Extensor de terreno', 'CI01', 'An item to be held by a Pokémon. It extends the duration of the terrain caused by the holder''s move or Ability.', 'Un objeto para ser sostenido por un Pokémon. Extiende la duración del terreno causado por el movimiento o Habilidad del poseedor.');
INSERT INTO public.recurso VALUES (1020, 'Thick Club', 'garrote grueso', 'CI01', 'Increases Attack when held by Cubone or Marowak.', 'Aumenta el ataque cuando lo sostiene Cubone o Marowak.');
INSERT INTO public.recurso VALUES (1021, 'Throat Spray', 'Aerosol para la garganta', 'CI01', 'Raises Sp. Atk when a sound-based move is used.', 'Eleva Sp. Atk cuando se usa un movimiento basado en sonido.');
INSERT INTO public.recurso VALUES (1022, 'Thunder Stone', 'tormenta de piedras', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (1023, 'Timer Ball', 'Bola de Tiempo', 'CI06', 'A somewhat different BALL that becomes progressively better the more turns there are in a battle.', 'Una PELOTA algo diferente que mejora progresivamente cuantos más turnos hay en una batalla.');
INSERT INTO public.recurso VALUES (1024, 'Timid Mint', 'Menta Miedosa', 'CI03', 'Changes the Pokémon''s stats to match the Timid nature.', 'Cambia las estadísticas del Pokémon para que coincidan con la naturaleza Miedosa.');
INSERT INTO public.recurso VALUES (1025, 'Tin of Beans', 'Lata de frijoles', 'CI02', 'One of the many ingredients that can be used for cooking at your camp. When simmered, the beans suffuse a dish with their mild flavor.', 'Uno de los muchos ingredientes que se pueden usar para cocinar en tu campamento. Cuando se cuecen a fuego lento, los frijoles impregnan un plato con su sabor suave.');
INSERT INTO public.recurso VALUES (1026, 'Tinkatink Hair', 'Tinka Tink Cabello', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1027, 'Tiny Bamboo Shoot', 'Pequeño brote de bambú', NULL, 'A small and rare bamboo shoot. It’s quite popular with a certain class of gourmands.', 'Un brote de bambú pequeño y raro. Es bastante popular entre cierta clase de gourmets.');
INSERT INTO public.recurso VALUES (1028, 'Tiny Mushroom', 'Hongo diminuto', 'CI02', 'A small and rare mushroom. It is sought after by collectors.', 'Un hongo pequeño y raro. Es buscado por los coleccionistas.');
INSERT INTO public.recurso VALUES (1029, 'TM00', 'TM00', 'CI07', 'Teaches the move Mega Punch.', 'Enseña el movimiento Mega Puñetazo.');
INSERT INTO public.recurso VALUES (1030, 'TM01', 'TM01', 'CI07', 'Teaches the move Mega Punch/Dynamic Punch/Focus Punch/Hone Claws/Work Up/Headbutt/Mega Kick.', 'Enseña el movimiento Mega Puñetazo/Puñetazo Dinámico/Puñetazo Foco/Afilar Garras/Ejercicio/Cabezazo/Mega Patada.');
INSERT INTO public.recurso VALUES (1031, 'TM02', 'TM02', 'CI07', 'Teaches the move Razor Wind/Headbutt/Dragon Claw/Taunt/Pay Day.', 'Enseña el movimiento Razor Wind/Headbutt/Dragon Claw/Taunt/Pay Day.');
INSERT INTO public.recurso VALUES (1032, 'TM03', 'TM03', 'CI07', 'Teaches the move Swords Dance/Curse/Water Pulse/Psyshock/Helping Hand/Fire Punch.', 'Enseña el movimiento Swords Dance/Curse/Water Pulse/Psyshock/Helping Hand/Fire Punch.');
INSERT INTO public.recurso VALUES (1033, 'TM04', 'TM04', 'CI07', 'Teaches the move Whirlwind/Rollout/Calm Mind/Teleport/Ice Punch.', 'Enseña el movimiento Torbellino/Desplazamiento/Calma mental/Teletransportación/Puñetazo helado.');
