INSERT INTO public.recurso VALUES (1202, 'Toedscool Flaps', 'Flaps Toedscool', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1203, 'Tofu', 'tofu', NULL, 'An ingredient with a touch of sweetness. It’s unclear how well this raw block of tofu will serve as a sandwich filling.', 'Un ingrediente con un toque de dulzura. No está claro qué tan bien servirá este bloque crudo de tofu como relleno de sándwich.');
INSERT INTO public.recurso VALUES (1204, 'Tomato', 'Tomate', NULL, 'This very tart ingredient has a lot of savory elements to it, making it popular with many Pokémon.', 'Este ingrediente muy agrio tiene muchos elementos sabrosos, lo que lo hace popular entre muchos Pokémon.');
