INSERT INTO public.recurso VALUES (1210, 'Toxic Orb', 'Orbe tóxico', 'CI01', 'An item to be held by a Pokémon. It is a bizarre orb that badly poisons the holder in battle.', 'Un objeto para ser sostenido por un Pokémon. Es un orbe extraño que envenena gravemente a quien lo posee en la batalla.');
