INSERT INTO public.recurso VALUES (1312, 'Tropical Shell', 'Concha tropical', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (1313, 'Tropius Leaf', 'hoja de tropius', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1314, 'Tumblestone', 'piedra rodante', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (1315, 'Twice-Spiced Radish', 'Rábano dos veces especiado', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (1316, 'Twisted Spoon', 'Cuchara Torcida', 'CI01', 'Increases the power of Psychic-type moves.', 'Aumenta el poder de los movimientos de tipo psíquico.');
INSERT INTO public.recurso VALUES (1317, 'Tynamo Slime', 'Limo de tínamo', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1318, 'Tyranitarite', 'tiranitarita', 'CI01', 'Enables Tyranitar to Mega Evolve during battle.', 'Permite que Tyranitar megaevolucione durante la batalla.');
INSERT INTO public.recurso VALUES (1319, 'Ultra Ball', 'UltraBola', 'CI06', 'An ultra-performance Ball that provides a higher Pokémon catch rate than a Great Ball.', 'Una Bola de ultra rendimiento que proporciona una tasa de captura de Pokémon más alta que una Gran Bola.');
INSERT INTO public.recurso VALUES (1320, 'Ultranecrozium Z', 'Ultranecrosis Z', 'CI01', 'Allows Ultra Necrozma to upgrade Photon Geyser to a Z-Move, Light That Burns the Sky.', 'Permite a Ultra Necrozma actualizar Photon Geyser a un Z-Move, Light That Burns the Sky.');
INSERT INTO public.recurso VALUES (1321, 'Upgrade', 'Mejora', 'CI02', 'Evolves Porygon when traded holding the item.', 'Evoluciona a Porygon cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (1322, 'Utility Umbrella', 'Paraguas utilitario', 'CI01', 'An item to be held by a Pokémon. This sturdy umbrella protects the holder from the effects of weather.', 'Un objeto para ser sostenido por un Pokémon. Este robusto paraguas protege al titular de los efectos del clima.');
INSERT INTO public.recurso VALUES (1323, 'Varoom Fume', 'Humo de varoom', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1324, 'Vee-Vee Pick', 'Púa en uve', NULL, 'A pick designed after Eevee, sporting the Pokémon’s usual expression. It’s easy to grab by the ears, which is part of why it’s so popular.', 'Una selección diseñada después de Eevee, luciendo la expresión habitual del Pokémon. Es fácil de agarrar por las orejas, lo cual es parte de por qué es tan popular.');
INSERT INTO public.recurso VALUES (1325, 'Veluza Fillet', 'Filete de Veluza', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1326, 'Venonat Fang', 'Colmillo Venonat', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1327, 'Venusaurite', 'Venusaurita', 'CI01', 'Enables Venusaur to Mega Evolve during battle.', 'Permite a Venusaur megaevolucionar durante la batalla.');
INSERT INTO public.recurso VALUES (1328, 'Vinegar', 'Vinagre', NULL, 'A very sour condiment. Vinegars derived from grapes are popular in Paldea. Highly effective when used to add just a light note of flavor.', 'Un condimento muy ácido. Los vinagres derivados de la uva son populares en Paldea. Altamente efectivo cuando se usa para agregar solo una ligera nota de sabor.');
INSERT INTO public.recurso VALUES (1329, 'Violet Book', 'Libro violeta', NULL, 'A record of the expedition that the author, Heath, went on within the Great Crater of Paldea. The book has the name “Turo” written on it in clumsy handwriting.', 'Un registro de la expedición que el autor, Heath, realizó dentro del Gran Cráter de Paldea. El libro tiene el nombre “Turo” escrito con letra torpe.');
INSERT INTO public.recurso VALUES (1330, 'Vivichoke', 'Vivichoke', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (1331, 'Voltorb Sparks', 'Chispas Voltorb', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1332, 'Wacan Berry', 'Buena baya', 'CI04', 'Weakens a supereffective Electric-type attack against the holding Pokémon.', 'Debilita un ataque de tipo eléctrico supereficaz contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (1333, 'Wasabi', 'Wasabi', NULL, 'This very spicy condiment seems close to horseradish at first, but you’ll find that it has a superb flavor all its own.', 'Este condimento muy picante parece cercano al rábano picante al principio, pero descubrirá que tiene un sabor excelente por sí solo.');
INSERT INTO public.recurso VALUES (1334, 'Water Gem', 'Gema de agua', 'CI01', 'Increases the power of a Water-type move only once.', 'Aumenta el poder de un movimiento de tipo Agua solo una vez.');
INSERT INTO public.recurso VALUES (1335, 'Water Memory', 'Memoria del agua', 'CI01', 'Changes Silvally and its move Multi-Attack to Water type.', 'Cambia Silvally y su movimiento Multi-Ataque a tipo Agua.');
INSERT INTO public.recurso VALUES (1336, 'Water Stone', 'Piedra de agua', 'CI02', 'Evolves certain species of Pokémon.', 'Evoluciona ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (1337, 'Water Tera Shard', 'Fragmento de agua Tera', NULL, 'On rare occasions, these shards form when a Tera Pokémon falls in battle and its Tera Jewel shatters.', 'En raras ocasiones, estos fragmentos se forman cuando un Pokémon Tera cae en la batalla y su Tera Jewel se rompe.');
INSERT INTO public.recurso VALUES (1338, 'Watercress', 'Berro', NULL, 'A very bitter ingredient that stands out among veggies for its quirky flavor. People tend to either like it or not like it—they rarely sit on the fence.', 'Un ingrediente muy amargo que destaca entre las verduras por su peculiar sabor. A la gente tiende a gustarle o no gustarle; rara vez se sientan en la cerca.');
INSERT INTO public.recurso VALUES (1339, 'Waterium Z', 'Agua Z', 'CI01', 'Allows the use of Hydro Vortex, the Water type Z-Move.', 'Permite el uso de Hydro Vortex, el tipo de agua Z-Move.');
INSERT INTO public.recurso VALUES (1340, 'Watmel Berry', 'Baya Watmel', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (1341, 'Wattrel Feather', 'Pluma de acacia', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1342, 'Wave Incense', 'Incienso Ola', 'CI01', 'Increases the power of Water-type moves. Breeding Mantine produces Mantyke when held.', 'Aumenta el poder de los movimientos de tipo agua. Breeding Mantine produce Mantyke cuando se sostiene.');
INSERT INTO public.recurso VALUES (1343, 'Weakness Policy', 'Política de debilidad', 'CI01', 'Sharply raises Attack and Special Attack if hit by a super-effective move.', 'Aumenta bruscamente el Ataque y el Ataque especial si lo golpea un movimiento súper efectivo.');
INSERT INTO public.recurso VALUES (1344, 'Wepear Berry', 'Baya de Wear', 'CI04', 'A Berry which is very rare in the Unova region. A maniac will buy it for a high price.', 'Una baya que es muy rara en la región de Unova. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (1345, 'Whimsical Tablecloth', 'Mantel caprichoso', NULL, 'A tablecloth made in collaboration with a popular picture-book author. The gently drawn Pokémon make even the loveliest picnic table more charming.', 'Un mantel hecho en colaboración con un popular autor de libros ilustrados. Los Pokémon dibujados suavemente hacen que incluso la mesa de picnic más hermosa sea más encantadora.');
INSERT INTO public.recurso VALUES (1346, 'Whipped Cream', 'Crema batida', NULL, 'A very sweet condiment. Folks in Paldea seem to love the varieties that really let the sweetness sing.', 'Un condimento muy dulce. La gente de Paldea parece amar las variedades que realmente dejan cantar la dulzura.');
INSERT INTO public.recurso VALUES (1347, 'Whipped Dream', 'sueño batido', 'CI02', 'Evolves Swirlix when traded holding the item.', 'Evoluciona a Swirlix cuando se intercambia con el objeto.');
INSERT INTO public.recurso VALUES (1348, 'White Apricorn', 'albaricoque blanco', 'CI02', 'A white Apricorn. It doesn''t smell like anything.', 'Un albaricoque blanco. No huele a nada.');
INSERT INTO public.recurso VALUES (1349, 'White Dish', 'plato blanco', NULL, 'A dish for picnics. Comes in plenty of colors to choose from based on the food or the mood. The white variety comes recommended by sellers.', 'Un plato para picnics. Viene en muchos colores para elegir según la comida o el estado de ánimo. La variedad blanca viene recomendada por los vendedores.');
INSERT INTO public.recurso VALUES (1350, 'White Flute', 'flauta blanca', 'CI02', 'A toy flute made from white glass. A maniac will buy it for a high price.', 'Una flauta de juguete hecha de cristal blanco. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (1351, 'White Herb', 'Hierba blanca', 'CI01', 'An item to be held by a POKéMON. It restores any lowered stat in battle. It can be used only once.', 'Objeto que debe llevar un POKéMON. Restaura cualquier estadística baja en la batalla. Se puede usar una sola vez.');
INSERT INTO public.recurso VALUES (1352, 'Wide Lens', 'Lente ancha', 'CI01', 'Increases the accuracy of moves.', 'Aumenta la precisión de los movimientos.');
INSERT INTO public.recurso VALUES (1353, 'Wiglett Sand', 'Arena de Wiglett', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1354, 'Wiki Berry', 'baya wiki', 'CI04', 'Restores HP if it''s low, but may cause confusion.', 'Restaura HP si es bajo, pero puede causar confusión.');
INSERT INTO public.recurso VALUES (1355, 'Wing Ball', 'Bola de Ala', 'CI06', NULL, NULL);
INSERT INTO public.recurso VALUES (1356, 'Wingull Feather', 'Pluma de gaviota', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1357, 'Winking Pika Pick', 'Guiño Pika Púa', NULL, 'A Pick-achu, if you will, sporting Pikachu’s winking face. It’s easy to grab by the ears, which is part of why it’s so popular.', 'Un Pick-achu, por así decirlo, luciendo la cara parpadeante de Pikachu. Es fácil de agarrar por las orejas, lo cual es parte de por qué es tan popular.');
INSERT INTO public.recurso VALUES (1358, 'Wise Glasses', 'Gafas sabias', 'CI01', 'Increases the power of Special-category moves.', 'Aumenta el poder de los movimientos de categoría especial.');
INSERT INTO public.recurso VALUES (1359, 'Wishing Piece', 'Pedazo de deseo', 'CI02', 'Activates a Pokémon Den for a Max Raid Battle.', 'Activa un Pokémon Den para una Max Raid Battle.');
INSERT INTO public.recurso VALUES (1360, 'Wood', 'Madera', 'CI02', NULL, NULL);
INSERT INTO public.recurso VALUES (1361, 'Wooper Slime', 'Baba Wooper', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
