INSERT INTO public.recurso VALUES (1374, 'X Sp. Atk', 'X esp. atk', 'CI03', 'Raises Special Attack of a Pokémon in battle.', 'Aumenta el Ataque Especial de un Pokémon en combate.');
INSERT INTO public.recurso VALUES (1375, 'X Sp. Atk 2', 'X esp. ataque 2', 'CI03', 'Sharply raises Special Attack of a Pokémon in battle.', 'Aumenta bruscamente el Ataque Especial de un Pokémon en combate.');
