INSERT INTO public.recurso VALUES (1378, 'X Sp. Def', 'X esp. Def', 'CI03', 'Raises Special Defense of a Pokémon in battle.', 'Aumenta la Defensa Especial de un Pokémon en batalla.');
INSERT INTO public.recurso VALUES (1379, 'X Sp. Def 2', 'X esp. Def 2', 'CI03', 'Sharply raises Special Defense of a Pokémon in battle.', 'Aumenta bruscamente la Defensa Especial de un Pokémon en combate.');
INSERT INTO public.recurso VALUES (1380, 'X Sp. Def 3', 'X esp. Def 3', 'CI03', 'Drastically raises Special Defense of a Pokémon in battle.', 'Aumenta drásticamente la Defensa Especial de un Pokémon en batalla.');
INSERT INTO public.recurso VALUES (1381, 'X Sp. Def 6', 'X esp. Def 6', 'CI03', 'Immensely raises Special Defense of a Pokémon in battle.', 'Aumenta inmensamente la Defensa Especial de un Pokémon en batalla.');
INSERT INTO public.recurso VALUES (1382, 'X Speed', 'Velocidad X', 'CI03', 'Raises Speed of a Pokémon in battle.', 'Aumenta la velocidad de un Pokémon en batalla.');
INSERT INTO public.recurso VALUES (1383, 'X Speed 2', 'X Velocidad 2', 'CI03', 'Sharply raises Speed of a Pokémon in battle.', 'Aumenta bruscamente la velocidad de un Pokémon en batalla.');
INSERT INTO public.recurso VALUES (1384, 'X Speed 3', 'X Velocidad 3', 'CI03', 'Drastically raises Speed of a Pokémon in battle.', 'Aumenta drásticamente la velocidad de un Pokémon en batalla.');
INSERT INTO public.recurso VALUES (1385, 'X Speed 6', 'X Velocidad 6', 'CI03', 'Immensely raises Speed of a Pokémon in battle.', 'Aumenta inmensamente la velocidad de un Pokémon en batalla.');
INSERT INTO public.recurso VALUES (1386, 'Yache Berry', 'Baya Yaché', 'CI04', 'Weakens a supereffective Ice-type attack against the holding Pokémon.', 'Debilita un ataque supereficaz de tipo Hielo contra el Pokémon que lo sostiene.');
INSERT INTO public.recurso VALUES (1387, 'Yarn Ball', 'Bola de hilo', NULL, 'A small ball of yarn. It’s woven tight so as not to unravel, but even if it were to come undone, at least you could still use the yarn for something.', 'Una pequeña bola de hilo. Está tejido apretado para que no se deshaga, pero incluso si se deshiciera, al menos podrías usar el hilo para algo.');
INSERT INTO public.recurso VALUES (1388, 'Yellow Apricorn', 'albaricoque amarillo', 'CI02', 'A yellow Apricorn. It has an invigorating scent.', 'Un albaricoque amarillo. Tiene un aroma vigorizante.');
INSERT INTO public.recurso VALUES (1389, 'Yellow Bell Pepper', 'Pimienta amarilla', NULL, 'An ingredient with some bitterness. It’s not much different from its red counterpart in flavor, but mixing the colors makes a feast for the eyes.', 'Un ingrediente con algo de amargor. No es muy diferente de su contraparte roja en sabor, pero mezclar los colores es un festín para los ojos.');
INSERT INTO public.recurso VALUES (1390, 'Yellow Bottle', 'botella amarilla', NULL, 'A go-to bottle widely used for drinks at picnics. Its simple design and portability make it popular among all sorts of people.', 'Una botella de referencia muy utilizada para bebidas en picnics. Su diseño simple y portabilidad lo hacen popular entre todo tipo de personas.');
INSERT INTO public.recurso VALUES (1391, 'Yellow Cup', 'Copa amarilla', NULL, 'A cup sold with the Yellow Bottle. The two don’t stack, so they’re tough to pack—but they look good, so they’re popular with those who like to post picnic photos.', 'Una taza vendida con la botella amarilla. Los dos no se apilan, por lo que son difíciles de empacar, pero se ven bien, por lo que son populares entre quienes les gusta publicar fotos de picnic.');
INSERT INTO public.recurso VALUES (1392, 'Yellow Dish', 'plato amarillo', NULL, 'A dish for picnics. Comes in plenty of colors to choose from based on the food or the mood. The yellow variety is impossible to go wrong with.', 'Un plato para picnics. Viene en muchos colores para elegir según la comida o el estado de ánimo. Es imposible equivocarse con la variedad amarilla.');
INSERT INTO public.recurso VALUES (1393, 'Yellow Flute', 'flauta amarilla', 'CI02', 'A toy flute made from yellow glass. A maniac will buy it for a high price.', 'Una flauta de juguete hecha de cristal amarillo. Un maníaco lo comprará por un alto precio.');
INSERT INTO public.recurso VALUES (1394, 'Yellow Nectar', 'néctar amarillo', 'CI01', 'A flower nectar obtained at Melemele Meadow. It changes the form of certain species of Pokémon.', 'Un néctar de flores obtenido en Melemele Meadow. Cambia la forma de ciertas especies de Pokémon.');
INSERT INTO public.recurso VALUES (1395, 'Yellow Scarf', 'Pañuelo amarillo', 'CI02', 'Raises holder''s Tough aspect in a Contest.', 'Aumenta el aspecto Duro del poseedor en un Concurso.');
INSERT INTO public.recurso VALUES (1396, 'Yellow Shard', 'Fragmento amarillo', 'CI02', 'A small yellow shard. It appears to be from some sort of implement made long ago.', 'Un pequeño fragmento amarillo. Parece ser de algún tipo de implemento hecho hace mucho tiempo.');
INSERT INTO public.recurso VALUES (1397, 'Yellow Tablecloth', 'Mantel Amarillo', NULL, 'A simple yellow tablecloth. It’s smooth and pleasant to the touch, and dishes can be placed on it with hardly a sound.', 'Un simple mantel amarillo. Es suave y agradable al tacto, y se pueden colocar platos sobre él sin apenas ruido.');
INSERT INTO public.recurso VALUES (1398, 'Yogurt', 'Yogur', NULL, 'A condiment that’s very sweet and very sour. It goes especially well with fruit and is easy to incorporate into a sandwich.', 'Un condimento muy dulce y muy ácido. Va especialmente bien con frutas y es fácil de incorporar en un sándwich.');
INSERT INTO public.recurso VALUES (1399, 'Yungoos Fur', 'Piel de Yungoos', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1400, 'Zangoose Claw', 'Garra de zangoose', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
INSERT INTO public.recurso VALUES (1401, 'Zap Plate', 'Placa Zap', 'CI01', 'Increases power of Electric-type moves. Changes Arceus'' type to Electric.', 'Aumenta la potencia de los movimientos de tipo eléctrico. Cambia el tipo de Arceus a Eléctrico.');
INSERT INTO public.recurso VALUES (1402, 'Zinc', 'Zinc', 'CI05', 'Increases Special Defense EVs by 10.', 'Aumenta los EV de defensa especial en 10.');
INSERT INTO public.recurso VALUES (1403, 'Zoom Lens', 'Lentes de aumento', 'CI01', 'Raises a move''s accuracy if the holder moves after its target.', 'Aumenta la precisión de un movimiento si el portador se mueve tras su objetivo.');
INSERT INTO public.recurso VALUES (1404, 'Zorua Fur', 'Piel de piso', NULL, 'Material accidentally dropped by a Pokémon. It can be used to make TMs.', 'Material dejado caer accidentalmente por un Pokémon. Se puede utilizar para hacer TM.');
